import { useAdminThemeBoundary } from "./admin-themes/use-admin-theme.hooks";
import { useCmsSidebarLabelTooltips } from "./hooks/use-cms-sidebar-label-tooltips.hooks";
import { SitesSidebarNav } from "./components/SitesSidebarNav";
import { useAdminDocumentLocale } from "./hooks/use-admin-document-locale.hooks";
import { useAdminAppearance } from "./hooks/use-admin-appearance.hooks";
import { useAdminThemeDocument } from "./admin-themes/use-admin-theme.hooks";
import { AdminModulesProvider } from "./integrations/jini-admin/AdminModulesProvider";
import { ChartRegistryProvider } from "./integrations/chart-providers/ChartRegistryProvider";
import { AdminBootScopeContext } from "./lib/admin-boot-scope";
import { api } from "./lib/api";
import { useMemo, type ReactNode } from "react";
import type { FrontendSessionBridge } from "@jini-ai/chat/react";
import { matchRoute, resolveAgentPageId, type AdminRoute } from "@jini-ai/admin/core";
import { ConfirmDialog, ConfirmDialogDefaultsProvider, Sidebar, useSidebar } from "@jini-ai/admin/react";
import { Toast } from "@jini-ai/ui";
import { KitProvider } from "@jini-ai/ui-kit/react";
import { tovuAgentAttrs, tovuKit } from "./integrations/jini-admin/kit";
import { useRouteLocation } from "./lib/router";
import { useDesktopViewRelease } from "./hooks/use-desktop-view-release.hooks";
import { resolveAddonsRoute } from "./lib/addons-routes";
import { resolveImportExportRoute } from "./lib/import-export-routes";
import { IntegrationsRedirect } from "./features/integrations";
import { getNav } from "./nav";
import { Login } from "./features/auth";
import { Placeholder } from "./components/Placeholder";
import { ADMIN_PANELS } from "./panels";
import { resolvePanelAccessGate, withoutInaccessiblePanels } from "./lib/panel-access";
import { translateAdminNavGroups, translateAdminNavLabel } from "./lib/admin-nav-i18n";
import { t as tApp } from "./app-i18n";
import { ScrollJumpButtons } from "@jini-ai/ui/admin-widgets";
import { useWiredAdminLocale } from "./hooks/use-admin-locale.hooks";
import { resolveAdminLayoutClassName, useInterfacePreferences } from "./hooks/use-interface-preferences.hooks";
import { useDrawerActiveItemCentring } from "./hooks/use-drawer-active-item-centring.hooks";
import { useAgentScreenRoute } from "./hooks/use-agent-screen-context.hooks";
import { useAdminTelemetry } from "./hooks/use-admin-telemetry.hooks";
import { useSidebarEmptyClickToggle } from "./hooks/use-sidebar-empty-click-toggle.hooks";
import { AssistantDock } from "./components/AssistantDock/AssistantDock";
import { DockHeaderTip } from "./components/AssistantDock/DockHeaderTip";
import { ChatFab } from "./components/ChatFab/ChatFab";
import { useListTableCellLabels } from "./hooks/use-list-table-cell-labels.hooks";
import { useDockAutoRail } from "./hooks/use-dock-auto-rail.hooks";
import { PublishContentDialog } from "./features/publish-content/PublishContentDialog";
import { closePublishRequest, usePublishRequest } from "./features/publish-content/hooks/publish-request.store";
import { t as translateDashboard } from "./features/dashboard/dashboard-i18n";
import {
  resolveChatFabClearance,
  resolveSiteSectionRouteGate,
  translateAssistantDockLabel,
  useAdminAssistantAvailability,
  useAdminSession,
  useAgentPageBridge,
  useChatDockLayout,
  useCollapsibleNavGroupLabels,
  useDefaultSectionRedirect,
  useInternalLinkInterceptor,
  useLogoutConfirm,
  usePublishCriteriaDeepLink,
  useScreenshotAnnouncement,
  useSidebarDrawer,
  useSiteSectionAvailability,
  useSidebarSiteSection,
  withoutSiteSection,
  type SiteSectionAvailability,
  type UseLogoutConfirm,
} from "./App.hooks";

/**
 * A resolved route, plus Tovu's legacy sections and URL migration metadata — see `parseRoute`.
 */
interface Route extends AdminRoute {
  /** Replacement URL for a retired Tovu route, executed before mounting its screen. */
  redirectPath?: string;
  /**
   * Set only by the legacy `/section/:id` branch when `id` does not match a registered panel.
   * Distinguishes "a stored URL naming a section that no longer exists" (render `Placeholder`,
   * `unknownSectionId` set) from "an unrecognized bare segment" (`matchRoute` already returns
   * `panelId: null` for that, and it means fall through to the dashboard) — the same distinction
   * `App.tsx` used to make via a separate `"section"` variant in its own `Route` union.
   */
  unknownSectionId?: string;
}

/** Panel id -> panel, for O(1) render dispatch. Built once; `ADMIN_PANELS` is a module constant. */
const PANELS_BY_ID = new Map(ADMIN_PANELS.map((panel) => [panel.id, panel] as const));

/**
 * The `localStorage` key Tovu has always persisted the desktop sidebar rail collapse under.
 * `@jini-ai/admin/react`'s `Sidebar` defaults `railStorageKey` to its own package key
 * (`jini-admin-sidebar-rail-collapsed`) — letting that default stand here would strand every
 * operator's saved rail preference behind a key nothing ever wrote to, springing every collapsed
 * rail back open on the next deploy. Passed straight through to `Sidebar` below.
 */
const SIDEBAR_RAIL_STORAGE_KEY = "tovu-admin-sidebar-rail-collapsed";

/** `AdminModulesProvider`'s input while the session's permissions are not known yet. */
const NO_PERMISSIONS: readonly string[] = [];

/**
 * Parses a *route path* (base already stripped by `router.ts`) into a `Route`.
 *
 * Delegates to `@jini-ai/admin/core`'s `matchRoute` against `panels.tsx`'s `ADMIN_PANELS`.
 * Tovu's `/assistant` alias and Add-ons URLs are canonicalized first; Jini still matches their
 * stable panel IDs. Another Tovu-specific shape the generic matcher was never given a branch for is:
 * legacy `/section/:id` URLs, which — unlike a modern bare `/settings` segment — accept an
 * *arbitrary* id. `matchRoute` matches over an array (`panels.find(p => p.id === segment)`), so
 * the historic `Object.hasOwn` hazard this file used to guard against (`/admin/constructor` etc.
 * resolving to `Object.prototype` members via `in`) cannot recur here by construction — there is
 * no plain-object key lookup left to walk a prototype chain.
 *
 * `section/` is still accepted as a leading segment. Not for new URLs — nothing generates it any
 * more — but `router.ts`'s legacy-hash redirect strips it, and this is the second line of defence
 * for a stored URL that reaches the parser without going through that redirect.
 *
 * @returns The canonical panel/query plus a replacement URL for a retired Tovu path; no I/O.
 * @complexity O(n + p·r·s) time and O(n + s) space: n URL characters, p registered panels,
 * r patterns per panel, s path segments. Legacy/alias rewrites add only a bounded parsing pass.
 */
export function parseRoute(routePath: string): Route {
  // Everything before the first `?` (the query is `matchRoute`'s to read). A replace rather than
  // `split("?")[0]`, whose `?? ""` fallback for an index that always exists could never fire.
  const rawPath = routePath.split("?", 1)[0]!;
  const parts = rawPath.split("/").filter(Boolean);

  // Stored assistant links must reach the registered page without mounting Dashboard first.
  // Keep the original query bytes; serializing URLSearchParams would change encodings/order.
  if (rawPath === "/assistant" || rawPath === "/assistant/") {
    const redirectPath = `/ai-assistant${routePath.slice(rawPath.length)}`;
    return { ...parseRoute(redirectPath), redirectPath };
  }

  if (parts[0] === "section" && parts[1]) {
    const id = parts[1];
    if (!PANELS_BY_ID.has(id)) {
      return { panelId: null, view: null, params: {}, query: new URLSearchParams(), unknownSectionId: id };
    }
    // A known id resolves exactly like the modern bare-segment path. Anything past the id is
    // ignored, matching the single inline branch this replaces (`/section/settings/foo` never
    // looked past `settings` either). The query is kept: `/section/sites?tab=import` must still
    // reach the moved-tab resolver below, not the Sites gate.
    return parseRoute(`/${id}${routePath.slice(rawPath.length)}`);
  }

  // Sites' old Export/Import tabs first: their new home is not under Add-ons, and the redirect has to
  // win before `renderRoute`'s Sites gate would send the route to the dashboard.
  const moved = resolveImportExportRoute({ routePath }) ?? resolveAddonsRoute({ routePath });
  return { ...matchRoute({ routePath: moved.matchPath, panels: ADMIN_PANELS }), redirectPath: moved.redirectPath };
}

/**
 * Which panel id is "current" for this route — feeds the sidebar highlight directly, and (via
 * {@link agentPageId}'s fallback) the page id an agent is told when no per-route override applies.
 * Deliberately not always {@link agentPageId}'s answer; see that function's own comment for the
 * routes (`widget-regions`, `jini-media`) where the two diverge.
 */
function currentPanelId(route: Route): string {
  return route.unknownSectionId ?? route.panelId ?? "dashboard";
}

/**
 * The page id this route reports to an agent through `data-agent-page`.
 *
 * Deliberately a separate question from {@link currentPanelId}, which is what it used to share
 * before the split. The two answer different questions and only *usually* agree: the sidebar wants
 * the nav row to light up, and an agent wants the id it can pass back to `page.navigate`. Widget
 * regions is where they genuinely diverge — `agent-pages.ts` publishes `widget-regions`, and the
 * sidebar has no such row, so it highlights `widgets`. Sharing one function meant
 * `page.navigate("widget-regions")` landed on the right screen and then reported `after:
 * "widgets"`, i.e. told the agent it had arrived somewhere it had not asked for. An agent's only
 * correction for that is to navigate again. `panels.tsx`'s `widgets` entry carries this exact case
 * forward as a per-route `agentPageId`, which `resolveAgentPageId` reads.
 *
 * Jini Media similarly reports `jini-media` at `/media/new` while the sidebar highlights `media`,
 * so an agent can return to the comparison page without landing on the legacy renderer.
 * Everything else still falls through to the panel id on purpose: a detail route reports its list
 * page (`/posts/abc` → `posts`), which is the nearest id an agent can actually act on.
 *
 * Values here must stay keys of `ADMIN_AGENT_PAGE_PATHS` wherever a published page exists for the
 * route, or the id an agent reads back is one `page.navigate` will refuse.
 */
export function agentPageId(route: Route): string {
  if (route.unknownSectionId !== undefined) return route.unknownSectionId;
  return resolveAgentPageId({ panels: ADMIN_PANELS, panelId: route.panelId ?? "dashboard", view: route.view }) ?? "dashboard";
}

/** What {@link renderRoute} needs to decide whether the operator may see the routed panel. */
interface RouteAccess {
  /** The session's `effectivePermissions`; `undefined` while not known (see `lib/panel-access.ts`). */
  readonly permissions: readonly string[] | undefined;
  readonly locale: string;
}

/**
 * The screen for this route: `Placeholder` for a legacy `/section/:id` naming an id that no longer
 * exists (see `Route.unknownSectionId`), otherwise the matched panel's own render — each panel does
 * its own small `view` switch (see `panels.tsx`), which is what lets a panel own its URL space
 * without a shared dispatch to edit.
 */
function renderRoute(route: Route, siteSection: SiteSectionAvailability, access: RouteAccess): ReactNode {
  // Replace the old URL before mounting its screen; the canonical route retains the same gate.
  if (route.redirectPath) return <IntegrationsRedirect routePath={route.redirectPath} />;
  if (route.unknownSectionId !== undefined) {
    return <Placeholder sectionId={route.unknownSectionId} />;
  }
  // The Sites section does not exist on every deployment — see `resolveSiteSectionRouteGate`. The
  // gate sits HERE rather than inside `panels.tsx`'s own `sites` render thunk so the panel manifest
  // stays a pure declaration of what this admin can show, and so "which sections this deployment
  // has" is answered in the one place that already owns routing.
  const gate = resolveSiteSectionRouteGate(route.panelId, siteSection);
  if (gate === "redirect") return <UnavailableSectionRedirect />;
  if (gate === "hold") return null;
  // A panel the operator holds none of the permissions for: say so, rather than mount a screen
  // whose first read the server answers 403. Same "routing owns visibility" placement as the
  // Sites gate above; the decision itself lives in `lib/panel-access.ts`.
  if (resolvePanelAccessGate({ panelId: route.panelId, panels: ADMIN_PANELS, permissions: access.permissions }) === "denied") {
    return <NoAccess locale={access.locale} />;
  }
  // Non-null by construction, so there is no `panel ? … : null` fallback: `parseRoute` (via
  // `matchRoute` over this same `ADMIN_PANELS`) only ever yields a registered panel id, the root's
  // `"dashboard"`, or `null` (mapped to `"dashboard"` here) — and `panels.tsx` registers
  // `dashboard`. The legacy `/section/:id` branch returns early above for an unregistered id.
  const panel = PANELS_BY_ID.get(route.panelId ?? "dashboard")!;
  return panel.render({ view: route.view, params: route.params, query: route.query, Placeholder });
}

/**
 * The screen for a section the operator has no permission to use (direct URL or a stale link — the
 * nav no longer lists it). Presentational only; `renderRoute` decides when it shows.
 */
function NoAccess(props: { locale: string }) {
  return (
    <div className="page">
      <div className="page-header">
        <div className="page-header-text">
          <h1 className="page-title">{tApp({ locale: props.locale, key: "You don't have access to this" })}</h1>
          <p className="page-description">{tApp({ locale: props.locale, key: "Ask the site owner if you need this section." })}</p>
        </div>
      </div>
    </div>
  );
}

/**
 * The screen for a route whose section this deployment does not have: no markup at all, just the
 * redirect to the default section. Same shape as `features/workspace/WorkspaceRedirect.tsx` — the
 * effect lives in `App.hooks.tsx`'s `useDefaultSectionRedirect`, so this component carries no logic
 * of its own.
 */
function UnavailableSectionRedirect() {
  useDefaultSectionRedirect();
  return null;
}

/**
 * Tovu's own log-out control, rendered inside `<Sidebar.Footer>`.
 *
 * `@jini-ai/admin/react`'s `Sidebar` no longer renders a log-out button itself — the compound
 * component's whole premise is that "who logs out and how" is a host decision, not a package one
 * (see the package's own file header). This is that decision: same markup, class names
 * (`.cms-logout`, styled by `styles.css`, unchanged by this port), and icon the package used to
 * render internally. `useSidebar().railTooltipProps` is what wires this button into the same
 * rail-mode tooltip behavior every nav item gets — it must be called from inside a `<Sidebar>`,
 * which is why this is a separate component rather than inline JSX in `App`.
 */
function SidebarLogoutButton(props: { onLogout: () => void; locale: string }) {
  const { railTooltipProps } = useSidebar();
  const logOutLabel = translateAdminNavLabel({ locale: props.locale, key: "Log out" });
  return (
    <button className="cms-logout" onClick={props.onLogout} {...railTooltipProps(logOutLabel)}>
      <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth={1.5}>
        <path d="M7 15H4a1.5 1.5 0 01-1.5-1.5v-9A1.5 1.5 0 014 3h3M11.5 12L15 9l-3.5-3M15 9H7" />
      </svg>
      <span>{logOutLabel}</span>
    </button>
  );
}

function SidebarLabelTooltips() {
  useCmsSidebarLabelTooltips({});
  return null;
}

/**
 * Click on blank sidebar space toggles the desktop rail — see `useSidebarEmptyClickToggle`. A
 * separate component for the same reason as `SidebarLogoutButton`: `useSidebar()` only works
 * inside `<Sidebar>`.
 */
function SidebarEmptyClickToggle() {
  const { toggleRail } = useSidebar();
  useSidebarEmptyClickToggle({ toggleRail });
  return null;
}

/**
 * The "are you sure you want to log out?" confirmation (owner-requested, 2026-08-31 — someone can
 * click "Log out" by accident, and the sidebar button used to sign them out immediately with no way
 * back). `onLogout` above now opens this instead of logging out directly — see `useLogoutConfirm`'s
 * own doc comment in `App.hooks.tsx`.
 *
 * Reuses `@jini-ai/admin/react`'s `ConfirmDialog`, the same component every other destructive
 * action in this app already confirms through (`Roles.tsx`'s `RoleDeleteDialog`, `Media.tsx`'s
 * permanent-delete dialog, `ThemeExplore.tsx`'s theme-delete dialog, …) rather than a bespoke modal
 * or `window.confirm` — a native dialog would block the whole tab and look like a browser artifact,
 * not part of the product (see `ConfirmDialog.tsx`'s own file header). It gets real focus trapping
 * and Escape-to-cancel for free from the native `<dialog>` element it's built on, and focus lands on
 * Cancel — never Confirm — on open, so a fast Enter after a slow read-through can't accidentally
 * log someone out (`ConfirmDialog.hooks.tsx`'s own comment gives the identical reasoning).
 *
 * `confirmLabel` reuses `admin-nav-i18n.ts`'s existing "Log out" translation (the sidebar button's
 * own label) rather than a second copy of the same English string in the new `app-i18n.ts` — see
 * that file's own header for why the title/body live there instead. `cancelLabel` is left unset,
 * matching every other `ConfirmDialog` caller in this app (none override it — see this component's
 * own commit for the survey): its translated "Cancel" comes from the `ConfirmDialogDefaultsProvider`
 * `App` mounts around its whole tree (see that provider's own call site below), not a per-dialog
 * prop — `ConfirmDialog`'s own built-in English "Cancel" is only ever a fallback for a host that
 * mounts no provider at all.
 */
function LogoutConfirmDialog(props: { logoutConfirm: UseLogoutConfirm; locale: string }) {
  const { logoutConfirm, locale } = props;
  return (
    <ConfirmDialog
      open={logoutConfirm.open}
      title={tApp({ locale: locale, key: "Log out?" })}
      body={<p>{tApp({ locale: locale, key: "Are you sure you want to log out?" })}</p>}
      confirmLabel={translateAdminNavLabel({ locale: locale, key: "Log out" })}
      pending={logoutConfirm.pending}
      onConfirm={logoutConfirm.confirm}
      onCancel={logoutConfirm.cancel}
    />
  );
}

/**
 * The assistant dock/sheet chrome and its `ChatFab` trigger — split out of `App` for the same
 * "independent branches scored in their own scope" reasoning `SidebarLogoutButton`/
 * `LogoutConfirmDialog` above already are, and `Media.tsx`'s `MediaToolbar`/`MediaPurgeDialog`
 * document in full: the `enabled` gate, the sheet-expand toggle's icon/label ternaries, and the
 * FAB clearance math were four of `App`'s own independent branches (`enabled` alone was the
 * `adminAssistantEnabled ? (...) : null` ternary this file's own comments used to sit around).
 * Returns `null` internally rather than `App` deciding whether to render this at all, so `App`
 * itself carries no conditional for it — always rendered, `enabled` decides.
 *
 * The FAB clearance math (`resolveChatFabClearance`, `App.hooks.tsx`) is pure derived state, not
 * JSX — kept out of this component's own body for the same reason it was never inline JSX-prop
 * ternaries here.
 */
function AssistantChrome(props: {
  /** `TOVU_ADMIN_ASSISTANT=off` (`useAdminAssistantAvailability`'s own doc): the chat surface
   *  itself, not rendered at all in that state — every endpoint it calls 404s off, so mounting it
   *  anyway would show a permanently broken dock instead of nothing. Distinct from the
   *  `ai-assistant` operator control panel (`panels.tsx`), which stays reachable regardless. */
  enabled: boolean;
  chatOpen: boolean;
  setChatOpen: React.Dispatch<React.SetStateAction<boolean>>;
  sheetExpanded: boolean;
  setSheetExpanded: React.Dispatch<React.SetStateAction<boolean>>;
  isSheetMode: boolean;
  sheetHeightPx: number;
  dockWidthPx: number;
  chatDockRef: React.RefObject<HTMLElement | null>;
  chatFabRef: React.RefObject<HTMLButtonElement | null>;
  /** SPEC-053 — `useChatDockLayout`'s `handleDockDropCapture` (`App.hooks.tsx`): the `<aside>`'s
   *  capture-phase drop handler. */
  onDockDropCapture: (event: React.DragEvent<HTMLElement>) => void;
  /** SPEC-053 — `useChatDockLayout`'s `publishDropCapture`, handed to `AssistantDock` as its
   *  `onFolderDropCaptureReady`. */
  publishDropCapture: (handler: (event: React.DragEvent<HTMLElement>) => void) => void;
  agentBridge: FrontendSessionBridge | null;
  /** The signed-in admin's id — scopes the assistant's remembered last conversation. */
  principalId: string;
  /** Bound translator — see `App`'s own `dockT` for where this comes from. */
  dockT: (key: string) => string;
  locale: string;
  /** Settings → User Interface, via `useInterfacePreferences` (`resolveChatFabClearance` reads it). */
  hideFabWhileOpen: boolean;
}): ReactNode {
  const themeBoundary = useAdminThemeBoundary({}, {});
  if (!props.enabled) return null;

  const {
    chatOpen,
    setChatOpen,
    sheetExpanded,
    setSheetExpanded,
    isSheetMode,
    sheetHeightPx,
    dockWidthPx,
    chatDockRef,
    chatFabRef,
    onDockDropCapture,
    publishDropCapture,
    agentBridge,
    principalId,
    dockT,
    locale,
  } = props;
  const { avoidBottomPx, avoidRightPx } = resolveChatFabClearance({
    isSheetMode,
    chatOpen,
    sheetHeightPx,
    dockWidthPx,
    fabHidesWhileOpen: props.hideFabWhileOpen,
  });

  return (
    <>
      {/* `hidden`, never unmounted: every admin page shares one assistant conversation, which must
          survive both closing the dock and navigating to a different section (ADR-049).
          `inert` alongside it (not instead of it) — belt-and-suspenders: `hidden` already drops
          this to `display: none`, which removes it from the tab order and accessibility tree on
          its own, but `inert` states that intent explicitly rather than leaving it as a side
          effect of a display value. `tabIndex={-1}` makes the element a valid *programmatic*
          focus target (the open-focus effect in `useChatDockLayout`) without adding it to the
          normal Tab order — the sheet's own close button and the assistant's composer are what Tab
          should reach, not the `<aside>` wrapper itself. */}
      {/*
        Classic's light pin is REQUIRED, not cosmetic, for the same reason `features/settings/SettingsUi.tsx`
        and `features/ai-assistant/AiAssistant.tsx` pin it — and it must live on THIS element, not on a wrapper
        inside `<AssistantDock>`. Glass uses the document's resolved scheme at this same boundary.

        The runtime picker's BYOK model dropdown is `@jini-ai/ui`'s `CustomSelect`, which portals its
        menu to `document.body` and so escapes any ancestor's theme. It compensates by copying the
        theme from its trigger's nearest `[data-theme]` ancestor. The dock had none, so the menu fell
        through to the stylesheet's dark variant and opened dark inside an all-light admin.

        A `display: contents` wrapper inside `AssistantDock` looks like the tidier place for this and
        is a trap: it generates no box, so `assistant.css`'s `.admin-chat-dock > * { flex: 1 }`
        matched the wrapper and applied to nothing, while `ChatPane` — a grandchild in the DOM, which
        is what child combinators read — stopped matching it at all and collapsed to content width.
        Measured: the dock rendered at roughly half its width. Putting the attribute here adds no
        element and cannot affect layout.
      */}
      <aside
        ref={chatDockRef}
        {...themeBoundary}
        // Jini's tip placement keeps every ⓘ / header tip bubble inside the dock, not over the page.
        data-jini-tip-bounds=""
        className={`admin-chat-dock${chatOpen ? " is-open" : ""}${sheetExpanded ? " is-expanded" : ""}`}
        hidden={!chatOpen}
        inert={!chatOpen}
        tabIndex={-1}
        aria-label={tApp({ locale: locale, key: "Assistant" })}
        // SPEC-053: capture phase, on this EXISTING element rather than a new wrapper inside
        // `<AssistantDock>` — a `display: contents` (or any real) div added there is the exact
        // layout trap `data-theme="light"`'s own comment two blocks up already documents for
        // `.admin-chat-dock > * { flex: 1 }`. `onDockDropCapture` (`useChatDockLayout`) is a no-op
        // until `AssistantDock` mounts and publishes its handler through `onFolderDropCaptureReady`,
        // so a drop before then just falls through to `ChatPane`'s own (bubble-phase)
        // attachment-upload handling — the same "no-op until ready" behavior
        // `getPathForFile === undefined` gives the desktop shell's own equivalent handler.
        onDropCapture={onDockDropCapture}
      >
        {/* Mobile-sheet-only chrome (`styles.css` hides this at desktop widths, where the docked
            panel closes only via the FAB same as before) — rendered here, around
            `<AssistantDock>`, rather than inside it: that component's own internals are not
            where this dispatch's changes belong (ADR-049's "never unmount" is about not touching
            its mount lifecycle, and staying out of its render body is the safest way to honor
            that). */}
        <div className="chat-sheet-bar">
          <span className="chat-sheet-handle" aria-hidden="true" />
          <span className="chat-sheet-bar-title">{dockT("Tovu assistant")}</span>
          <span className="chat-sheet-bar-actions">
            <button
              type="button"
              className="chat-sheet-action"
              onClick={() => setSheetExpanded((current) => !current)}
              aria-expanded={sheetExpanded}
              aria-label={sheetExpanded ? dockT("Collapse assistant panel") : dockT("Expand assistant panel")}
              title={sheetExpanded ? dockT("Collapse assistant panel") : dockT("Expand assistant panel")}
            >
              <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth={1.5} aria-hidden="true">
                {sheetExpanded ? <path d="M4 6.5 9 11.5l5-5" /> : <path d="M4 11.5 9 6.5l5 5" />}
              </svg>
            </button>
            {/* Same white tip under it as the dock header's other icon buttons (owner, 2026-10-11). */}
            <DockHeaderTip label={dockT("Close AI chat")}>
              <button
                type="button"
                className="chat-sheet-action"
                onClick={() => setChatOpen(false)}
                aria-label={dockT("Close AI chat")}
              >
                <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth={1.5} aria-hidden="true">
                  <path d="M5 5 13 13M13 5 5 13" strokeLinecap="round" />
                </svg>
              </button>
            </DockHeaderTip>
          </span>
        </div>
        <AssistantDock
          agentBridge={agentBridge}
          principalId={principalId}
          onFolderDropCaptureReady={publishDropCapture}
        />
      </aside>
      <ChatFab
        ref={chatFabRef}
        open={chatOpen}
        onToggle={() => setChatOpen((current) => !current)}
        label={dockT("assistant")}
        locale={locale}
        avoidBottomPx={avoidBottomPx}
        avoidRightPx={avoidRightPx}
      />
    </>
  );
}

export interface AppProps {
  /**
   * Injectable seam for the boot-time auth check — defaults to the real {@link useAdminSession}.
   * Every existing test of `App` pays for mocking `fetch`/`EventSource` and awaiting the boot
   * screen's exit before it can assert anything about routing or the shell, because there was no
   * way to skip the real `api.me()` round trip. A fake here lets a future test render `App`
   * already authenticated instead.
   */
  useSession?: typeof useAdminSession;
  /** Injectable seam for the mobile drawer's open state — defaults to the real
   *  {@link useSidebarDrawer}. Touches `document` (its Escape-key listener) and `localStorage`
   *  indirectly through the effects it owns, so INFO.md's Components rule 3 applies. */
  useDrawer?: typeof useSidebarDrawer;
  /** Injectable seam for the app-wide SPA-link interceptor — defaults to the real
   *  {@link useInternalLinkInterceptor}. Attaches a real `document` click listener, so rule 3
   *  applies even though this hook has no return value to fake. */
  useLinkInterceptor?: typeof useInternalLinkInterceptor;
  /** Injectable seam for the assistant dock/sheet chrome — defaults to the real
   *  {@link useChatDockLayout}. Touches `window.matchMedia`, two `ResizeObserver`s, `document`
   *  keydown/focus, and `lib/assistant-dock-bus.ts`'s pub/sub, so rule 3 applies. */
  useChatDock?: typeof useChatDockLayout;
  /** Injectable seam for the agent page-control bridge — defaults to the real
   *  {@link useAgentPageBridge}. Constructs an `EventSource`-backed session bridge and a DOM page
   *  driver scoped to the live `<main>` node, so rule 3 applies. */
  useAgentBridge?: typeof useAgentPageBridge;
}

/**
 * Resolves each of `App`'s five injectable-seam props to its real implementation when a caller
 * passes none. The same `??`-avoidance idiom `MenuEditor.tsx`'s `orEmpty`,
 * `CollectionEntryEditor.tsx`'s `resolveCollectionEntryEditorHook`, and
 * `AssistantDock.tsx`'s own resolver group use (2026-08-14, applied here per the DI migration
 * sweep's own follow-up audit — this file's debt-list entry already attributed +6 cyclomatic to
 * exactly this shape): ESLint's cyclomatic-complexity rule counts a default parameter value inside
 * a function's OWN body as one of that function's own branches — a call out to a separately-scoped
 * resolver does not.
 */
function resolveSessionHook(override: typeof useAdminSession | undefined): typeof useAdminSession {
  return override ?? useAdminSession;
}
function resolveDrawerHook(override: typeof useSidebarDrawer | undefined): typeof useSidebarDrawer {
  return override ?? useSidebarDrawer;
}
function resolveLinkInterceptorHook(
  override: typeof useInternalLinkInterceptor | undefined
): typeof useInternalLinkInterceptor {
  return override ?? useInternalLinkInterceptor;
}
function resolveChatDockHook(override: typeof useChatDockLayout | undefined): typeof useChatDockLayout {
  return override ?? useChatDockLayout;
}
function resolveAgentBridgeHook(override: typeof useAgentPageBridge | undefined): typeof useAgentPageBridge {
  return override ?? useAgentPageBridge;
}

/** Keep the session owner mounted while every reader observes the same boot/identity boundary. */
export function App(props: AppProps) {
  // No `AppProps = {}` default on the parameter itself (2026-08-14 — the sixth branch this file's
  // debt-list note flagged as untried): every real call site is JSX (`<App />`), and JSX's own
  // `createElement`/`jsx` runtime always constructs an actual props object — `{}` when no
  // attributes are given, never `undefined` — so `App` is never invoked with zero arguments the way
  // a plain function call could be. `AppProps`' five fields are all optional, so `{}` satisfies the
  // type and this compiles the same as before for every existing call site.
  const useSession = resolveSessionHook(props.useSession);
  const session = useSession();
  return <AdminBootScopeContext.Provider value={{ principalId: session.user?.id ?? null, checking: session.checking }}>
    <AdminShell {...props} session={session} />
  </AdminBootScopeContext.Provider>;
}

function AdminShell(props: AppProps & { session: ReturnType<typeof useAdminSession> }) {
  const useDrawer = resolveDrawerHook(props.useDrawer);
  const useLinkInterceptor = resolveLinkInterceptorHook(props.useLinkInterceptor);
  const useChatDock = resolveChatDockHook(props.useChatDock);
  const useAgentBridge = resolveAgentBridgeHook(props.useAgentBridge);

  // `effectivePermissions` stays `undefined` until known — the nav filter and route gate below read
  // that as "show everything"; `AdminModulesProvider` gets `[]` for it, as before.
  const { user, checking, handleLogin, logout, effectivePermissions } = props.session;
  // Confirmation-modal state around `logout` above — see `useLogoutConfirm`'s own doc comment
  // (`App.hooks.tsx`) for why this is its own hook rather than a `useSession()` field. Called
  // unconditionally here, ahead of the `checking`/`!user` early returns below (rules of hooks),
  // same reasoning `useAdminAssistantAvailability` just below already documents for itself.
  const logoutConfirm = useLogoutConfirm(logout);
  // `TOVU_ADMIN_ASSISTANT=off` — see `useAdminAssistantAvailability`'s own doc for why this is a
  // separate hook rather than a `useSession()` field, and why it is called unconditionally here
  // (before the `checking`/`!user` early returns below) even though it only fetches once `user` is
  // set: React's rules of hooks forbid calling it conditionally.
  const adminAssistantEnabled = useAdminAssistantAvailability(user);
  // `TOVU_ENABLE_SITE_SWITCHER` — whether this deployment has a Sites section at all. Called
  // unconditionally here for the same rules-of-hooks reason as the line above, and read TWICE
  // below (the nav filter and the route gate) from this one value, so the sidebar and the router
  // can never disagree about whether the section exists. See `useSiteSectionAvailability`. The one
  // exception is the pending window: the sidebar keeps the last confirmed answer so the Sites row
  // does not arrive late and shift the rows under it, while the route gate still holds.
  const siteSection = useSiteSectionAvailability(user);
  const sidebarSiteSection = useSidebarSiteSection(siteSection);
  const routePath = useRouteLocation();
  useDesktopViewRelease({ routePath, signedIn: Boolean(user) && !checking });
  const route = useMemo(() => parseRoute(routePath), [routePath]);
  // Tells the assistant which screen each message is sent from; an editor adds its open entry.
  useAgentScreenRoute({ path: routePath, section: agentPageId(route), view: route.view });
  // The admin's own page views (route template only) and errors, relayed by the server.
  useAdminTelemetry({ signedIn: Boolean(user), routePath, params: route.params });

  const { sidebarOpen, setSidebarOpen } = useDrawer({ routePath });
  // The phone drawer opens with the current page's item in its vertical middle (owner, 2026-10-07).
  useDrawerActiveItemCentring({ open: sidebarOpen });
  useLinkInterceptor();

  // --- Assistant dock/sheet chrome (MSG-06/MSG-09) — see `useChatDockLayout`'s own doc for why
  // this is one hook rather than several: every value here reads or reacts to at least one other.
  const {
    chatOpen,
    setChatOpen,
    sheetExpanded,
    setSheetExpanded,
    isSheetMode,
    sheetHeightPx,
    dockWidthPx,
    chatDockRef,
    chatFabRef,
    handleDockDropCapture,
    publishDropCapture,
  } = useChatDock();
  // Nav expanded + dock open in a 901–1171px window left a phone-width page: fold the nav to its
  // rail while the dock is open there (see the hook's doc for the rule and the mechanism).
  const dockRail = useDockAutoRail({ dockOpen: chatOpen });

  const { setContentEl, contentEl, agentBridge } = useAgentBridge();
  // Phone card layout for every `.list-table` needs each cell's column name (mobile catalog P-4).
  const contentNode = contentEl ?? null;
  useListTableCellLabels(contentNode);
  // The `admin.capture_screenshot` consent announcement — see `useScreenshotAnnouncement`'s own doc
  // (`App.hooks.tsx`) and `agent-screenshot-bus.ts`'s module doc for the privacy decision behind it.
  const { announced: screenshotAnnounced, dismiss: dismissScreenshotAnnouncement } = useScreenshotAnnouncement();
  // publish-criteria-tool-webmcp-plan-2026-09-24.md §4 S2 — the Publish dialog moved here, to the top
  // of the tree, because none of its three callers (the Dashboard button, the chat capability, the
  // WebMCP projection) is the component that renders it. `publish-request.store.ts`'s own header
  // explains the whole division of labour; this is just the one place that reads it.
  const openPublishRequest = usePublishRequest();
  // The admin's own `?publish=` deep link — see `usePublishCriteriaDeepLink`'s own doc for why this
  // is unconditional (before the `checking`/`!user` early returns below) and gated on nothing.
  usePublishCriteriaDeepLink();

  /**
   * Read once per render rather than at each of the two `<Sidebar.Nav>` call sites below, so both
   * slices are guaranteed to come from the same array instance. `getNav()` is memoized internally
   * (see `nav.ts`), so this is about intent rather than cost: it makes "one nav model, split for
   * layout" explicit instead of leaving two independent lookups to be kept in agreement by hand.
   *
   * `withoutSiteSection` is applied HERE, to the single shared read, for that same reason — the two
   * slices below must not be able to disagree about whether the Sites row exists. It filters items
   * and never groups, so the `slice(0, 1)`/`slice(1)` boundary below is unaffected; see its own doc.
   * `nav.ts` itself is left alone: `getNav()` is a cached, synchronous module-level derivation of
   * `ADMIN_PANELS` that `components/Placeholder.tsx` also reads for its own label lookup, and it has
   * no access to a value that only arrives from the server.
   *
   * `withoutInaccessiblePanels` then drops the rows the operator holds no permission for, on the
   * same shared read for the same reason. It CAN drop a whole labelled group, but never group 0:
   * Overview declares no permission, so the `slice(0, 1)` boundary still holds.
   */
  const rawNavGroups = withoutInaccessiblePanels({
    groups: withoutSiteSection(getNav(), sidebarSiteSection),
    panels: ADMIN_PANELS,
    permissions: effectivePermissions,
  });

  /**
   * Sidebar nav translation — outside `SettingsUi.tsx`'s `I18nProvider` entirely, since this nav
   * renders on every admin page, not just inside the settings dialog. `useWiredAdminLocale()`
   * (shared with every translated content screen — see `use-admin-locale.hooks.ts`'s own doc
   * comment) re-fetches on every `core.language` refresh notification, not just at mount, so
   * switching the Language setting updates the sidebar immediately instead of requiring a reload.
   */
  const navLocale = useWiredAdminLocale();
  useAdminDocumentLocale({ locale: navLocale }, {});
  useAdminAppearance({}, {});
  // The operator's admin theme + scheme on <html> (Studio → Admin Themes).
  useAdminThemeDocument({}, {});
  /** Settings → User Interface: whether the FAB hides while the dock is open, and whether phone tab
   *  strips wrap (see the hook's doc). */
  const interfacePreferences = useInterfacePreferences();
  const hideFabWhileOpen = interfacePreferences.hideChatFabWhileOpen;
  const navGroups = translateAdminNavGroups(navLocale, rawNavGroups);
  const navSoonLabel = translateAdminNavLabel({ locale: navLocale, key: "Soon" });

  /** Same `navLocale`, reused for the assistant dock's mobile-sheet chrome and `ChatFab`'s
   *  "assistant" label below — both live here rather than inside `AssistantDock.tsx`/`ChatFab.tsx`
   *  themselves (see the `<aside>`'s own comment for why), so this is that chrome's translation. */
  const dockT = (key: string): string => translateAssistantDockLabel(navLocale, key);

  /** The Publish dialog's own copy lives in `dashboard-i18n.ts`'s `DASHBOARD_DICT` — it is the
   *  Dashboard's dialog, wherever it mounts — never `tApp`/`dockT`, which would silently regress
   *  every locale but English for this one dialog (both resolve against `app-i18n.ts`'s different
   *  dictionary, which has no entries for this copy). */
  const dashboardT = (key: string): string => translateDashboard({ locale: navLocale, key: key });

  // See `useCollapsibleNavGroupLabels`'s own doc for which groups collapse and why.
  const collapsibleGroups = useCollapsibleNavGroupLabels(navGroups);

  if (checking) return <div className="boot-screen">{tApp({ locale: navLocale, key: "Loading Tovu…" })}</div>;
  if (!user) return <Login onLogin={handleLogin} />;

  const content: ReactNode = renderRoute(route, siteSection, { permissions: effectivePermissions, locale: navLocale });

  return (
    // Sets the translated "Cancel" once for every `ConfirmDialog` mounted anywhere beneath this
    // tree (`@jini-ai/admin/react`'s `ConfirmDialogDefaultsProvider`) — the ~22 features that build
    // a confirm dialog on that shared component (`Roles.tsx`, `Media.tsx`, `Trash.tsx`, this file's
    // own `LogoutConfirmDialog`, …) all inherit it instead of each passing `cancelLabel` itself, so
    // a future dialog is translated for free too. `navLocale`/`tApp` are already computed above for
    // this file's own dialog copy; `tApp(navLocale, "Cancel")` resolves through `tApp`'s fallback to
    // `COMMON_I18N` (`lib/i18n-common.ts`, `"Cancel"` already covers all 21 locales) since
    // `app-i18n.ts`'s own `APP_DICT` defines no `"Cancel"` key of its own — see
    // `createDictionaryTranslator`'s doc comment in `lib/dictionary-translator.ts`.
    <AdminModulesProvider permissions={effectivePermissions ?? NO_PERMISSIONS}>
    <ChartRegistryProvider key={user.id} principalId={user.id}>
    <ConfirmDialogDefaultsProvider cancelLabel={tApp({ locale: navLocale, key: "Cancel" })}>
      <div className={resolveAdminLayoutClassName(interfacePreferences)}>
        {/* First focusable element in the app, deliberately before `<Sidebar>` — the auditor
            measured 26 Tab presses to reach main content from a fresh load, because every route
            repeats the full sidebar first, paid on every navigation by a keyboard/screen-reader
            operator. Visually hidden until focused (`.skip-link` in styles.css); the target is
            `#main-content` on `<main>` below, not a route change, so this works identically
            whichever section is currently rendered there. */}
        <a href="#main-content" className="skip-link">
          {tApp({ locale: navLocale, key: "Skip to content" })}
        </a>
        {/* `railDefaultCollapsed`: Tovu's admin opens as an icon rail for a first-time operator, so
            the 26-item nav does not claim 232px before anyone has asked it to. It is a DEFAULT, not a
            forced state — anyone who toggles the rail has their choice persisted under
            `SIDEBAR_RAIL_STORAGE_KEY` and that stored value wins on every later load. */}
        <Sidebar
          activeId={currentPanelId(route)}
          open={sidebarOpen}
          railStorageKey={SIDEBAR_RAIL_STORAGE_KEY}
          {...dockRail}
          railDefaultCollapsed
        >
          <Sidebar.MobileHeader onClose={() => setSidebarOpen(false)} />
          <SidebarEmptyClickToggle />
          <SidebarLabelTooltips />
          {/* The nav is rendered in two calls so the rail toggle can sit directly under "AI
              Assistant" instead of down in the footer — the operator wants the collapse control
              beside the sections it collapses, not adrift at the bottom of a 26-item list.
              `getNav()[0]` is the ungrouped top row (Overview + Sites + AI Assistant, in that order —
              Sites ranks above AI Assistant per the owner's 2026-09-05 call; see `panels.tsx:109`),
              and every later group is a labelled section starting with CONTENT. Sites is absent from
              that row on a deployment that has no Sites section (`withoutSiteSection` above); Overview
              and AI Assistant are not, so the row itself always exists and this index is stable.

              Splitting is safe precisely because `Sidebar.Nav` renders a bare fragment of
              `.cms-section` divs — no wrapper element, no ids, no internal indexing across groups —
              so two calls produce exactly the DOM one call would, with the toggle spliced between.
              Doing it here also keeps this a host-only layout choice: `@jini-ai/admin` is unchanged,
              so no package rebuild is involved and no other host inherits Tovu's arrangement. */}
          <SitesSidebarNav groups={navGroups.slice(0, 1)} locale={navLocale} soonLabel={navSoonLabel} />
          <Sidebar.RailToggle />
          {/* Collapsible sections (owner-directed, 2026-08-06 — piloted on PEOPLE, then widened to
              all six). `collapsibleGroups` defaults to empty in `@jini-ai/admin`, so this opt-in is
              what turns the headings into controls; other hosts embedding the admin are unaffected.
              Open/closed state persists per section via `useNavSections` (localStorage), survives
              reload and navigation, and syncs across tabs. */}
          <Sidebar.Nav groups={navGroups.slice(1)} collapsibleGroups={collapsibleGroups} soonLabel={navSoonLabel} />
          <Sidebar.Footer>
            <SidebarLogoutButton onLogout={logoutConfirm.request} locale={navLocale} />
          </Sidebar.Footer>
        </Sidebar>
        <LogoutConfirmDialog logoutConfirm={logoutConfirm} locale={navLocale} />
        {/* Mobile-only backdrop behind the open drawer (`styles.css` hides `.cms-nav`'s off-canvas
            behavior above 900px, so this has nothing to sit behind there either — conditionally
            rendered rather than CSS-hidden since it would otherwise sit invisibly over the whole
            page, intercepting clicks, whenever the drawer is closed). */}
        {sidebarOpen ? <div className="sidebar-backdrop" onClick={() => setSidebarOpen(false)} /> : null}
        <div className="admin-main-col">
          {/* Hidden above the tablet breakpoint (desktop keeps the always-visible sidebar) — see
              `.admin-topbar` in styles.css. */}
          <AdminTopbar sidebarOpen={sidebarOpen} setSidebarOpen={setSidebarOpen} navLocale={navLocale} />
          {/* `data-agent-page` is how the page driver reports where it is: `page.find_elements` tags
              every handle with its nearest `[data-agent-page]` ancestor, and `page.navigate` reads it
              back to say which page it left and which it landed on. `agentPageId`, not
              `currentPanelId` — they agree for every route but widget regions, where the published
              page id and the highlighted sidebar row are genuinely different things. */}
          {/* `tabIndex={-1}` — without it, activating the skip link above scrolls `<main>` into
              view but does not actually move keyboard focus there, since a plain `<main>` isn't
              natively focusable; the skip link would then satisfy the letter of "skip navigation"
              while missing the actual point (the next Tab press would resume from wherever focus
              really was, not from main content). Not in the normal Tab order either way, since -1
              only allows *programmatic* focus (the skip link's own `href` jump). */}
          {/* MailStatusBanner (components/MailStatusBanner) is not mounted while email is parked
              (owner, 2026-10-23: "we aren't doing anything with email right now"); re-mount it here
              with fetchStatus={api.getMailStatus} when email work resumes (development/todos.md). */}
          <main id="main-content" className="admin-content" ref={setContentEl} tabIndex={-1} data-agent-page={agentPageId(route)}>
            {/* Keep page overlays in the same allowed root and page identity as their triggers. */}
            <KitProvider kit={tovuKit} agent={tovuAgentAttrs} overlayContainer={contentEl}>
              {content}
            </KitProvider>
          </main>
          {/* One ↑/↓ pair for every long admin page (owner, 2026-10-21); `styles.css` places it
              beside the assistant FAB. */}
          <ScrollJumpButtons
            container={contentNode}
            labels={{ toTop: tApp({ locale: navLocale, key: "Scroll to top" }), toBottom: tApp({ locale: navLocale, key: "Scroll to bottom" }) }}
          />
        </div>
        {/* See `AssistantChrome`'s own doc comment for why this is unconditional — `enabled` is what
            decides, not a ternary here. */}
        <AssistantChrome
          enabled={adminAssistantEnabled}
          chatOpen={chatOpen}
          setChatOpen={setChatOpen}
          sheetExpanded={sheetExpanded}
          setSheetExpanded={setSheetExpanded}
          isSheetMode={isSheetMode}
          sheetHeightPx={sheetHeightPx}
          dockWidthPx={dockWidthPx}
          chatDockRef={chatDockRef}
          chatFabRef={chatFabRef}
          onDockDropCapture={handleDockDropCapture}
          publishDropCapture={publishDropCapture}
          agentBridge={agentBridge}
          principalId={user.id}
          dockT={dockT}
          locale={navLocale}
          hideFabWhileOpen={hideFabWhileOpen}
        />
        {/* Rendered unconditionally on `chatOpen`, deliberately: the assistant can capture a
            screenshot while the panel is collapsed (a background run in flight), and the operator must
            see the announcement either way — see `screenshotAnnounced`'s own comment above. */}
        {screenshotAnnounced ? (
          <Toast
            message={dockT("The assistant just captured a screenshot of this screen.")}
            tone="default"
            ttlMs={5000}
            onDismiss={dismissScreenshotAnnouncement}
          />
        ) : null}
        {/* publish-criteria-tool-webmcp-plan-2026-09-24.md §4 S2 — `key={requestId}` remounts the
            dialog fresh per request, so a stale instance can never call a newer request's own
            `resolve` (see `publish-request.store.ts`'s header). `port` is left `undefined`: this is
            the one real (non-test) mount, so the dialog resolves its own default port itself. */}
        {openPublishRequest ? (
          <PublishContentDialog
            key={openPublishRequest.requestId}
            criteria={openPublishRequest.criteria}
            scope={openPublishRequest.scope}
            onPlanned={openPublishRequest.resolve}
            onCancel={closePublishRequest}
            t={dashboardT}
            port={undefined}
          />
        ) : null}
      </div>
    </ConfirmDialogDefaultsProvider>
    </ChartRegistryProvider>
    </AdminModulesProvider>
  );
}

/** Mobile shell chrome follows the same drawer state as the sidebar and backdrop. */
function AdminTopbar({ sidebarOpen, setSidebarOpen, navLocale }: {
  sidebarOpen: boolean; setSidebarOpen: (value: boolean | ((current: boolean) => boolean)) => void; navLocale: string;
}) {
  return (
    <div className="admin-topbar">
      <button
        type="button"
        className="admin-topbar-toggle"
        aria-expanded={sidebarOpen}
        aria-controls="admin-sidebar"
        aria-label={tApp({ locale: navLocale, key: sidebarOpen ? "Close navigation" : "Open navigation" })}
        onClick={() => setSidebarOpen((current) => !current)}
      >
        <svg viewBox="0 0 18 18" fill="none" stroke="currentColor" strokeWidth={1.5} aria-hidden="true">
          <path d="M2.5 5h13M2.5 9h13M2.5 13h13" strokeLinecap="round" />
        </svg>
      </button>
      <span className="admin-topbar-title">Tovu</span>
    </div>
  );
}

import { useId, type CSSProperties } from "react";
import { createPortal } from "react-dom";
import { RemixIcon } from "@jini-ai/ui";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { ChatSettingsSegmented } from "@jini-ai/chat/react";

import { useTaxonomyRowMenu } from "@/features/taxonomy/TaxonomyRowMenu.hooks";
import { activateDockMenuItem, isChoiceSection, type DockSettingsMenuItem, type DockSettingsMenuSection } from "./dock-header-rules";

type DockMenu = ReturnType<typeof useTaxonomyRowMenu>;

/**
 * The dock header's gear (owner, 2026-10-11): a small menu under it, right-aligned. Built from the
 * admin's row menu — the same `.row-menu-popup`/`.row-menu-item` styling and the same open/close,
 * positioning and roving-focus hook `TaxonomyRowMenu` uses (published `RowMenu` hard-codes its ⋮
 * trigger and has no disabled rows). The hook already anchors the popup's right edge to the
 * trigger's, which keeps it inside the narrow dock.
 * Rows come in sections (a heading, then its rows); a setting row carries a check mark that is
 * always laid out and only shown when on, so toggling never shifts the menu. `notice` is a status
 * line under the rows (a failed save). A row's ⓘ sits beside its button; a radio group's single
 * ⓘ (`groupOptionTooltips`) sits beside its heading.
 * A radio group (Tool calls, Agent plugins) is the Chat settings dialog's own segmented control
 * (owner, 2026-10-21), not a column of check rows. It takes ONE roving-focus stop, its checked
 * option: ↑/↓ move between stops as before, ←/→ pick within the pill (native radio keys).
 * Disabled rows use `aria-disabled`, not `disabled`, so keyboard focus can still land on them.
 */
export function DockSettingsMenu({ label, sections, notice, useMenu = useTaxonomyRowMenu }: {
  label: string; sections: DockSettingsMenuSection[]; notice?: string; useMenu?: typeof useTaxonomyRowMenu;
}) {
  const helpId = useId();
  // Each section's first row index in the flat roving-focus order; a segmented choice is one stop.
  let nextIndex = 0;
  const firstIndexes = sections.map((section) => {
    const first = nextIndex;
    nextIndex += isChoiceSection(section) ? 1 : section.items.length;
    return first;
  });
  const menu = useMenu({ itemCount: nextIndex });
  return <>
    <button
      ref={menu.triggerRef}
      type="button"
      className="assistant-dock-icon-button"
      aria-label={label}
      aria-haspopup="menu"
      aria-expanded={menu.open}
      onClick={menu.onTriggerClick}
      onKeyDown={menu.onTriggerKeyDown}
    >
      <RemixIcon name="settings-3-line" size={16} />
    </button>
    {menu.open ? createPortal(
      <div
        ref={menu.menuRef}
        role="menu"
        aria-label={label}
        className={`row-menu-popup dock-settings-menu${menu.position?.placement === "above" ? " row-menu-popup-above" : ""}`}
        style={popupStyle(menu.position)}
        onKeyDown={menu.onMenuKeyDown}
      >
        {sections.map((section, sectionIndex) => <MenuSection key={section.key} section={section} separated={sectionIndex > 0}
          firstIndex={firstIndexes[sectionIndex]!} helpId={helpId} menu={menu} />)}
        {notice ? <p className="dock-settings-menu-notice" role="status">{notice}</p> : null}
      </div>,
      document.body,
    ) : null}
  </>;
}

/** Off-screen and hidden until the hook has measured the popup; lifted when it opens above the gear. */
function popupStyle(position: DockMenu["position"]): CSSProperties {
  return {
    position: "fixed",
    top: position ? position.top : -9999,
    left: position ? position.left : -9999,
    visibility: position ? "visible" : "hidden",
    transform: position?.placement === "above" ? "translateY(-100%)" : undefined,
    maxHeight: popupMaxHeight(position),
  };
}

/**
 * Caps the menu to the room on its side of the gear so it scrolls instead of running off-screen
 * when neither side fits it (a short phone viewport with the dock sheet half-way up). The hook
 * checks "fits below" first, so a capped below-menu still fits below on re-measure and never flips.
 */
function popupMaxHeight(position: DockMenu["position"]): string | undefined {
  if (!position) return undefined;
  return position.placement === "above" ? `${Math.max(0, position.top - 4)}px` : `calc(100dvh - ${position.top + 8}px)`;
}

function MenuSection({ section, separated, firstIndex, helpId, menu }: {
  section: DockSettingsMenuSection; separated: boolean; firstIndex: number; helpId: string; menu: DockMenu;
}) {
  return <>
    {separated ? <div role="separator" className="dock-settings-menu-separator" /> : null}
    <div role="group" aria-labelledby={section.label ? `dock-settings-${section.key}` : undefined}
      aria-describedby={section.tooltip ? `${helpId}-section-${section.key}` : undefined}>
      {/* The section's one ⓘ sits beside the heading, not in it, so the group's name stays the heading alone. */}
      {section.label ? <div className="dock-settings-menu-heading-row">
        <div id={`dock-settings-${section.key}`} className="dock-settings-menu-heading">{section.label}</div>
        {section.tooltip ? <InfoTip label={section.tooltip} descriptionId={`${helpId}-section-${section.key}`} /> : null}
      </div> : null}
      {isChoiceSection(section)
        ? <MenuChoice section={section} itemIndex={firstIndex} name={`${helpId}-${section.key}`} menu={menu} />
        : section.items.map((item, offset) => <MenuRow key={item.key} item={item} itemIndex={firstIndex + offset} helpId={helpId} menu={menu} />)}
    </div>
  </>;
}

/** A radio section as the dialog's segmented pill; a choice applies in place and leaves the menu open. */
function MenuChoice({ section, itemIndex, name, menu }: { section: DockSettingsMenuSection; itemIndex: number; name: string; menu: DockMenu }) {
  return <div className="dock-settings-menu-choice">
    <ChatSettingsSegmented name={name} inputRole="menuitemradio"
      // The hook's roving focus only calls `focus()`, so the checked radio can fill a button's slot.
      checkedRef={(input) => { menu.itemRefs.current[itemIndex] = input as unknown as HTMLButtonElement | null; }}
      items={section.items.map((item) => ({ ...item, change: () => activateDockMenuItem({ item, selectItem: menu.selectItem }) }))} />
  </div>;
}

function MenuRow({ item, itemIndex, helpId, menu }: { item: DockSettingsMenuItem; itemIndex: number; helpId: string; menu: DockMenu }) {
  const checkable = item.role === "menuitemradio" || item.role === "menuitemcheckbox";
  const descriptionId = `${helpId}-${item.key}`;
  return <div className="dock-settings-menu-row">
    <button
      ref={(element) => { menu.itemRefs.current[itemIndex] = element; }}
      type="button"
      role={item.role ?? "menuitem"}
      aria-checked={checkable ? Boolean(item.checked) : undefined}
      tabIndex={-1}
      className="row-menu-item"
      aria-describedby={item.tooltip ? descriptionId : undefined}
      aria-disabled={item.disabled ? true : undefined}
      onClick={() => activateDockMenuItem({ item, selectItem: menu.selectItem })}
    >
      {checkable ? <span className="dock-settings-menu-check" aria-hidden="true"><RemixIcon name="check-line" size={14} /></span> : null}
      {item.label}
    </button>
    {item.tooltip ? <InfoTip label={item.tooltip} descriptionId={descriptionId} /> : null}
  </div>;
}

import type { ReactNode } from "react";
import { useT } from "@jini-ai/chat/react";
import { agentHandle } from "@jini-ai/agentic";

import { useMessageOverflowModal } from "./MessageOverflowModal.hooks";

/**
 * @file The chat pane's "Show in modal" surface (owner request, chat-overflow fix 2026-08-30):
 * *"if we have a UI element that we can't really show in the chat very well, I want to have a
 * 'show in modal' button that brings up a modal and shows the whole table / the whole UI."*
 *
 * Built on the native `<dialog>` element (`showModal()`/`close()`), the same foundation
 * `ImagePreviewModal.tsx` already uses in this app and `@jini-ai/admin/react`'s `ConfirmDialog`
 * uses upstream — reusing the established dialog PATTERN rather than inventing a second one, per
 * this feature's own review note ("do not introduce a new dialog pattern"). Not built on
 * `ImagePreviewModal` or `ConfirmDialog` directly: both have a fixed content shape (an `<img>`; a
 * title+body+two-button confirm/cancel pair) neither of which fits "arbitrary chat content at full
 * size" — same reasoning `ImagePreviewModal.tsx`'s own doc gives for not forcing image content
 * through `ConfirmDialog`'s contract. `children` here is a plain `ReactNode` on purpose, so any
 * host content — the re-rendered markdown text, a second `McpUiSurfaceCard` instance, a future
 * content type — can be shown full-size without this component needing to know its shape.
 *
 * A generic host-agnostic modal (not `@jini-ai/chat`'s own component) because the injection point
 * for it differs by content type: `OverflowAwareMcpUiSurfaceCard.tsx` renders one directly, and any
 * future per-message-content affordance (see that file's own doc for why plain markdown text isn't
 * wired up yet) would render one the same way.
 */
export interface MessageOverflowModalProps {
  open: boolean;
  /** The dialog's accessible name — read by assistive tech since this content has no visible page
   *  heading of its own inside the dialog. */
  title: string;
  onClose: () => void;
  /** Only rendered while `open` — callers should pass `null`/`undefined` when closed rather than an
   *  always-mounted element, so content with real side effects (a second live MCP-UI iframe
   *  session) is never mounted until the dialog actually opens. See
   *  `OverflowAwareMcpUiSurfaceCard.tsx` for the concrete case this matters for. */
  children: ReactNode;
  /** Injectable seam for the dialog's open/close lifecycle. Defaults to the real
   *  {@link useMessageOverflowModal}; a test can pass a fake here to exercise this component's
   *  rendering without a real `<dialog>` lifecycle. */
  useModal?: typeof useMessageOverflowModal;
  /** Publishes the close button as agent-addressable via `agentHandle()` (`@jini-ai/agentic`).
   *  Omit to leave it untagged — every existing render then stays byte-identical. */
  agentHandle?: string;
}

export function MessageOverflowModal({
  open,
  title,
  onClose,
  children,
  useModal = useMessageOverflowModal,
  agentHandle: handle,
}: MessageOverflowModalProps) {
  const t = useT();
  const { dialogRef, handleNativeCancel, handleBackdropClick } = useModal(open, onClose);

  return (
    <dialog
      ref={dialogRef}
      className="message-overflow-modal"
      aria-label={title}
      onCancel={handleNativeCancel}
      onClick={handleBackdropClick}
    >
      <button
        type="button"
        className="message-overflow-modal-close"
        onClick={onClose}
        aria-label={t("Close")}
        {...(handle ? agentHandle({ handle }, { role: "button", label: t("Close") }) : {})}
      >
        ×
      </button>
      <div className="message-overflow-modal-body">{children}</div>
    </dialog>
  );
}

import { useId } from "react";
import { Dialog } from "@jini-ai/ui-kit/react";
import { Icon } from "@jini-ai/ui";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { agentHandle } from "@jini-ai/agentic";
import { interpolate, type Translate } from "@jini-ai/ui/panel-kit";
import { resolveTabBarTabIndex, useTabBarKeyboard } from "@jini-ai/ui/tab-strip";
import type { AdminMedia } from "../../lib/api";
import type { MediaPickerPort } from "../MediaPickerDialog/media-picker-port.hooks";
import { DockHeaderTip } from "../AssistantDock/DockHeaderTip";
import "../../styles/native-domain-dialogs.css";
import "../../styles/media-content-editor.css";
import { HtmlAttributeRows } from "./HtmlAttributeRows";
import { useMediaContentEditor, type MediaContentEditorController, type MediaItemRow } from "./MediaContentEditor.hooks";
import type { MediaContentMode, MediaLayout, MediaSlugProblem } from "./media-content-rules";
import { DevicePreviewFrame } from "../DevicePreview/DevicePreviewFrame";
import { useWidgetPreview } from "./WidgetPreview.hooks";

/**
 * @file `MediaContentEditor` — the owner-approved two-tab editor ("Media" structured / "Raw HTML")
 * for media content (2026-10-11). ONE component, two hosts: `WidgetConfigFields` renders it for
 * `media` and `gallery` widgets (the widget editor page and the "create new" picker form), and the
 * `widgetEmbed` node's Style dialog renders it for a per-placement "Custom for this post" override
 * (`widget-embed-extension.tsx`). Replaces the 10-09 `GalleryConfigFields` form the owner called
 * "terrible": loose label/inputs, big filled Move/Remove buttons, full-size thumbnails.
 *
 * Markup only — state lives in `MediaContentEditor.hooks.ts`, rules in `media-content-rules.ts`.
 * Design rules it follows (owner checklist): no control wider than its content, label + compact
 * control on one line, ⓘ tips instead of paragraphs, small icon buttons; rows reflow under the
 * `admin-content` container (`styles/media-content-editor.css`) for 390px and the open dock.
 *
 * ## Agent handles
 *
 * Given `agentHandle="widget-instance-config"`: `<base>-tab-media`, `<base>-tab-html`,
 * `<base>-layout-<layout>`, `<base>-columns`, `<base>-aspect-ratio`, `<base>-choose`,
 * `<base>-slug`, `<base>-slug-add`, `<base>-css-class`, `<base>-attribute-add`, `<base>-html`,
 * `<base>-insert-media`, `<base>-picker-add`. Item rows are reorderable and their slugs editable,
 * so they carry no per-row handle (no stable id to key one on). Omit the base to leave editor-owned
 * controls untagged; shared help triggers and dialog controls keep their default instance handles.
 */

const TABS: ReadonlyArray<{ id: MediaContentMode; label: string }> = [{ id: "media", label: "Media" }, { id: "html", label: "Raw HTML" }];

function handle(base: string | undefined, suffix: string, role: "field" | "button", label: string) {
  return base ? agentHandle({ handle: `${base}-${suffix}` }, { role, label }) : {};
}

/** Literal keys (not `t(variable)`) so the i18n parity test can resolve every one statically. */
function layoutLabel(layout: MediaLayout, t: Translate): string {
  if (layout === "single") return t("Single");
  if (layout === "grid") return t("Grid");
  if (layout === "carousel") return t("Carousel");
  return t("Masonry");
}

function problemText(problem: MediaSlugProblem, slug: string, t: Translate): string {
  if (problem === "empty") return t("Type a media slug.");
  if (problem === "invalid") return t("Slugs can't contain spaces or slashes.");
  if (problem === "duplicate") return t("Already in this list.");
  if (problem === "full") return interpolate({ template: t("Up to {max} items."), vars: { max: 50 } });
  return interpolate({ template: t('No media with the slug "{slug}".'), vars: { slug } });
}

export interface MediaContentEditorProps {
  /** `media`, `gallery` (no Single layout), or `media` for a placement override. */
  widgetType: string;
  config: Record<string, unknown>;
  onChange: (config: Record<string, unknown>) => void;
  /** Shared-components dictionary translator; omit for the English source strings. */
  t?: Translate;
  agentHandle?: string;
  /** Media library seam; defaults to the live `/media` client. */
  port?: MediaPickerPort;
  /** Injectable seam for the state hook — a test can render this markup against a fake. */
  useEditor?: typeof useMediaContentEditor;
  usePreview?: typeof useWidgetPreview;
}

export function MediaContentEditor({ widgetType, config, onChange, t = (key) => key, agentHandle: base, port, useEditor = useMediaContentEditor, usePreview = useWidgetPreview }: MediaContentEditorProps) {
  const vm = useEditor({ config, onChange, widgetType }, port ? { port } : {});
  const preview = usePreview({ widgetType, config });
  const panelId = useId();
  return (
    <div className="media-content-editor">
      <EditorTabs vm={vm} t={t} base={base} panelId={panelId} />
      <div id={panelId} role="tabpanel" className="media-content-editor__panel">
        {vm.mode === "media" ? <MediaTab vm={vm} t={t} base={base} /> : <HtmlTab vm={vm} t={t} base={base} />}
      </div>
      <PreviewSection preview={preview} t={t} />
      {vm.libraryError ? <p className="field-error" role="alert">{vm.libraryError}</p> : null}
      {vm.picker ? <LibraryPicker vm={vm} t={t} base={base} /> : null}
    </div>
  );
}

function EditorTabs({ vm, t, base, panelId }: { vm: MediaContentEditorController; t: Translate; base: string | undefined; panelId: string }) {
  const { onKeyDown } = useTabBarKeyboard({ tabs: TABS, activeId: vm.mode, onChange: (id) => vm.setMode(id as MediaContentMode) });
  return (
    <div className="media-content-editor__tabs">
      <div className="segmented" role="tablist" aria-label={t("Widget content")} onKeyDown={onKeyDown}>
        {TABS.map((tab) => (
          <button key={tab.id} type="button" role="tab" aria-selected={vm.mode === tab.id} aria-controls={panelId}
            className={vm.mode === tab.id ? "is-active" : undefined}
            tabIndex={resolveTabBarTabIndex({ tabs: TABS, activeId: vm.mode, tab })}
            onClick={() => vm.setMode(tab.id)}
            {...handle(base, `tab-${tab.id}`, "button", `Switch to the ${tab.label} tab`)}>
            {tab.id === "media" ? t("Media") : t("Raw HTML")}
          </button>
        ))}
      </div>
      {vm.inactiveHasContent ? (
        <span className="field-hint media-content-editor__notice" role="status">
          <Icon name="alert-triangle" size={14} aria-hidden="true" />
          {t("Saving keeps only this tab. The other tab's content will be dropped.")}
        </span>
      ) : null}
    </div>
  );
}

function previewStatus(preview: ReturnType<typeof useWidgetPreview>, t: Translate): string | null {
  if (preview.error) return t("Preview unavailable.");
  return preview.loading ? t("Loading preview…") : null;
}

function PreviewSection({ preview, t }: { preview: ReturnType<typeof useWidgetPreview>; t: Translate }) {
  return (
    <section className="media-content-editor__preview" aria-label={t("Preview")}>
      <div className="media-content-editor__toolbar">
        <span className="field-label">{t("Preview")}</span>
        <span className={preview.error ? "field-error" : "field-hint"} role="status">
          {previewStatus(preview, t)}
        </span>
      </div>
      <DevicePreviewFrame width={preview.paneWidth} frameRef={preview.frameRef} paneWidth={preview.paneWidth} expanded>
        <iframe title={t("Preview")} className="page-preview-iframe" sandbox="" srcDoc={preview.document} />
      </DevicePreviewFrame>
    </section>
  );
}

function MediaTab({ vm, t, base }: { vm: MediaContentEditorController; t: Translate; base: string | undefined }) {
  const layoutLabelId = useId();
  return (
    <>
      <div className="media-content-editor__toolbar">
        <span className="media-content-editor__field">
          <span id={layoutLabelId}>{t("Layout")}</span>
          <span className="segmented media-content-editor__layouts" role="radiogroup" aria-labelledby={layoutLabelId}>
            {vm.layouts.map((layout) => (
              <button key={layout} type="button" role="radio" aria-checked={vm.media.layout === layout}
                className={vm.media.layout === layout ? "is-active" : undefined} onClick={() => vm.setLayout(layout)}
                {...handle(base, `layout-${layout}`, "button", `Use the ${layout} layout`)}>
                {layoutLabel(layout, t)}
              </button>
            ))}
          </span>
        </span>
        {vm.showColumns ? (
          <label className="media-content-editor__field">
            {t("Columns")}
            <input type="number" min={1} max={6} className="media-content-editor__number" value={vm.media.columns ?? 3}
              onChange={(event) => vm.setColumns(event.target.value)} {...handle(base, "columns", "field", "Number of columns")} />
          </label>
        ) : null}
        <span className="media-content-editor__field">
          <label>
            {t("Aspect ratio")}
            <input className="field-mono media-content-editor__ratio" placeholder="4/3" value={vm.media.aspectRatio ?? ""}
              onChange={(event) => vm.setAspectRatio(event.target.value)} {...handle(base, "aspect-ratio", "field", "Aspect ratio, e.g. 16/9")} />
          </label>
          <InfoTip label={t("e.g. 1, 4/3, 16/9")} />
        </span>
      </div>

      {vm.rows.length === 0 ? (
        <p className="field-hint media-content-editor__empty">{t("No media yet. Choose from the library or add one by slug.")}</p>
      ) : (
        <ol className="media-content-editor__items">
          {/* Index keys: a row's slug is editable, so keying on it would remount the row (and drop
              focus) on every keystroke; values are controlled, so reordering stays correct. */}
          {vm.rows.map((row, index) => <MediaItemRowView key={index} row={row} index={index} vm={vm} t={t} />)}
        </ol>
      )}

      <AddMediaRow vm={vm} t={t} base={base} />
      <AttributesSection vm={vm} t={t} base={base} />
    </>
  );
}

function Thumbnail({ row, vm, t }: { row: MediaItemRow; vm: MediaContentEditorController; t: Translate }) {
  if (row.problem === "unknown") return <span className="media-content-editor__thumb is-missing"><Icon name="alert-triangle" size={18} aria-hidden="true" /></span>;
  if (row.asset && row.kind === "image") return <img className="media-content-editor__thumb" src={vm.mediaUrl(row.asset)} alt="" loading="lazy" width={48} height={48} />;
  if (row.kind === "video") return <span className="media-content-editor__thumb" title={t("Video file")}><Icon name="play" size={18} aria-label={t("Video file")} /></span>;
  if (row.kind === "audio") return <span className="media-content-editor__thumb" title={t("Audio file")}><Icon name="volume" size={18} aria-label={t("Audio file")} /></span>;
  return <span className="media-content-editor__thumb"><Icon name="image" size={18} aria-hidden="true" /></span>;
}

function MediaItemRowView({ row, index, vm, t }: { row: MediaItemRow; index: number; vm: MediaContentEditorController; t: Translate }) {
  const n = index + 1;
  return (
    <li className="media-content-editor__row">
      <Thumbnail row={row} vm={vm} t={t} />
      <input className={`field-mono media-content-editor__slug${row.showsSlugEnd ? " is-end-first" : ""}`} value={row.item.slug} spellCheck={false} autoComplete="off"
        aria-label={`${t("Media slug")} ${n}`} aria-invalid={row.problem ? true : undefined} title={row.item.slug}
        onChange={(event) => vm.updateItem(index, { slug: event.target.value.trim() })} />
      {/* Clearing alt/caption omits the key, so the library's own text is used at render time
          (contract); the placeholder shows that fallback. */}
      <input className="media-content-editor__alt" value={row.item.alt ?? ""} placeholder={mediaTextPlaceholder({ row, field: "alt", t })}
        aria-label={`${t("Alt text")} ${n}`} onChange={(event) => vm.updateItem(index, { alt: event.target.value || undefined })} />
      <input className="media-content-editor__caption" value={row.item.caption ?? ""} placeholder={mediaTextPlaceholder({ row, field: "caption", t })}
        aria-label={`${t("Caption")} ${n}`} onChange={(event) => vm.updateItem(index, { caption: event.target.value || undefined })} />
      <RowActions index={index} vm={vm} t={t} />
      {row.problem ? <p className="field-error media-content-editor__row-error">{rowProblemText(row.problem, row.item.slug, t)}</p> : null}
    </li>
  );
}

function rowProblemText(problem: NonNullable<MediaItemRow["problem"]>, slug: string, t: Translate): string {
  return problem === "unknown" ? t("Not in the media library") : problemText(problem, slug, t);
}

function RowActions({ index, vm, t }: { index: number; vm: MediaContentEditorController; t: Translate }) {
  const n = index + 1;
  const last = index === vm.rows.length - 1;
  return (
    // The admin's white tip, not the browser's dark `title` one (owner, 2026-10-11).
    <span className="media-content-editor__row-actions">
      <DockHeaderTip label={t("Move up")}>
        <button type="button" className="btn-ghost media-content-editor__icon" disabled={index === 0}
          aria-label={`${t("Move up")} ${n}`} onClick={() => vm.moveItem(index, -1)}>
          <Icon name="arrow-up" size={14} aria-hidden="true" />
        </button>
      </DockHeaderTip>
      <DockHeaderTip label={t("Move down")}>
        <button type="button" className="btn-ghost media-content-editor__icon is-down" disabled={last}
          aria-label={`${t("Move down")} ${n}`} onClick={() => vm.moveItem(index, 1)}>
          <Icon name="arrow-up" size={14} aria-hidden="true" />
        </button>
      </DockHeaderTip>
      <DockHeaderTip label={t("Remove")}>
        <button type="button" className="btn-ghost media-content-editor__icon"
          aria-label={`${t("Remove")} ${n}`} onClick={() => vm.removeItem(index)}>
          <Icon name="close" size={14} aria-hidden="true" />
        </button>
      </DockHeaderTip>
    </span>
  );
}

function AddMediaRow({ vm, t, base }: { vm: MediaContentEditorController; t: Translate; base: string | undefined }) {
  const listId = useId();
  const full = vm.rows.length >= vm.maxItems;
  return (
    <>
      <div className="media-content-editor__add">
        <button type="button" className="btn-secondary media-content-editor__compact" disabled={full} onClick={() => vm.openPicker("items")}
          {...handle(base, "choose", "button", "Choose media from the library")}>
          <Icon name="image" size={14} aria-hidden="true" />
          {t("Choose from library")}
        </button>
        <span className="media-content-editor__slug-add">
          <input className="field-mono" list={listId} value={vm.slugDraft} placeholder={t("Add by slug")} aria-label={t("Add by slug")}
            spellCheck={false} autoComplete="off" disabled={full} aria-invalid={vm.slugProblem ? true : undefined}
            onChange={(event) => vm.setSlugDraft(event.target.value)}
            onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); vm.addSlug(); } }}
            {...handle(base, "slug", "field", "Media slug to add")} />
          <button type="button" className="btn-ghost media-content-editor__compact" disabled={full} onClick={vm.addSlug}
            {...handle(base, "slug-add", "button", "Add the typed media slug")}>
            <Icon name="plus" size={14} aria-hidden="true" />
            {t("Add")}
          </button>
        </span>
        <span className="field-hint media-content-editor__count">{vm.rows.length} / {vm.maxItems}</span>
        <datalist id={listId}>
          {(vm.pickable ?? []).map((asset) => <option key={asset.id} value={asset.slug}>{asset.title}</option>)}
        </datalist>
      </div>
      {vm.slugProblem ? <p className="field-error" role="alert">{problemText(vm.slugProblem.problem, vm.slugProblem.slug, t)}</p> : null}
    </>
  );
}

function AttributesSection({ vm, t, base }: { vm: MediaContentEditorController; t: Translate; base: string | undefined }) {
  return (
    <div className="media-content-editor__attrs">
      <div className="media-content-editor__toolbar">
        <label className="media-content-editor__field">
          {t("CSS class")}
          <input className="field-mono media-content-editor__class" value={vm.media.cssClass ?? ""} spellCheck={false}
            onChange={(event) => vm.setCssClass(event.target.value)} {...handle(base, "css-class", "field", "CSS class on the layout root")} />
        </label>
        <span className="media-content-editor__field">
          {t("HTML attributes")}
          <InfoTip label={t("data-*, aria-*, class, id, style. Unsafe ones are dropped.")} />
        </span>
      </div>
      <HtmlAttributeRows value={vm.media.htmlAttributes ?? ""} onChange={vm.setHtmlAttributes} t={t} agentHandle={base} />
    </div>
  );
}

function HtmlTab({ vm, t, base }: { vm: MediaContentEditorController; t: Translate; base: string | undefined }) {
  return (
    <>
      <div className="media-content-editor__toolbar">
        <button type="button" className="btn-secondary media-content-editor__compact" onClick={() => vm.openPicker("html")}
          {...handle(base, "insert-media", "button", "Insert library media at the cursor")}>
          <Icon name="image" size={14} aria-hidden="true" />
          {t("Insert media…")}
        </button>
        <InfoTip label={t('Use {{media:slug}} for a file\'s URL, or data-media-slug="slug" on img, video, audio or source to fill in src, alt and size.')} />
        <span className={`field-hint media-content-editor__count${vm.htmlTooLong ? " is-over" : ""}`}>
          {vm.html.length.toLocaleString()} / {vm.maxHtmlLength.toLocaleString()}
        </span>
      </div>
      <div className="media-content-editor__code">
        <div ref={vm.gutterRef} className="media-content-editor__gutter" aria-hidden="true">
          {Array.from({ length: vm.htmlLines }, (_, i) => i + 1).join("\n")}
        </div>
        <textarea ref={vm.htmlRef} className="media-content-editor__source" value={vm.html} wrap="off" spellCheck={false}
          aria-label={t("HTML source")} aria-invalid={vm.htmlTooLong ? true : undefined} placeholder={'<img data-media-slug="…" alt="…">'}
          onChange={(event) => vm.setHtml(event.target.value)} onScroll={vm.onHtmlScroll}
          {...handle(base, "html", "field", "Raw HTML for this media content")} />
      </div>
      {vm.htmlTooLong ? (
        <p className="field-error" role="alert">
          {interpolate({ template: t("HTML is longer than {max} characters and won't save."), vars: { max: vm.maxHtmlLength.toLocaleString() } })}
        </p>
      ) : null}
    </>
  );
}

function PickerThumb({ asset, vm }: { asset: AdminMedia; vm: MediaContentEditorController }) {
  if (asset.contentType?.startsWith("video/")) return <span className="media-content-editor__picker-icon"><Icon name="play" size={22} aria-hidden="true" /></span>;
  if (asset.contentType?.startsWith("audio/")) return <span className="media-content-editor__picker-icon"><Icon name="volume" size={22} aria-hidden="true" /></span>;
  return <img src={vm.mediaUrl(asset)} alt="" loading="lazy" />;
}

/** Multi-select over the active library — images, video and audio. Same grid/item classes as
 *  `MediaPickerDialog`, checkbox per asset since several can be added at once. */
function LibraryPicker({ vm, t, base }: { vm: MediaContentEditorController; t: Translate; base: string | undefined }) {
  return (
    <Dialog open onClose={vm.cancelPicker} title={t("Choose media")} className="settings-dialog jini-domain-dialog media-picker-dialog">
      <div className="media-picker-body">
        {vm.pickable === null ? <p className="notice">{t("Loading media…")}</p> : (
          <div className="media-picker-grid">
            {vm.pickable.map((asset) => (
              <label key={asset.id} className="media-picker-item" title={asset.slug}>
                <input type="checkbox" checked={vm.picked.includes(asset.slug)} onChange={() => vm.togglePicked(asset.slug)} />
                <PickerThumb asset={asset} vm={vm} />
                <span className="media-picker-item-title">{asset.title}</span>
              </label>
            ))}
          </div>
        )}
      </div>
      <div className="widget-picker-footer">
        <span className="editor-actions">
          <button data-jini-autofocus="" type="button" className="btn-secondary" onClick={vm.cancelPicker}>{t("Cancel")}</button>
          <button type="button" className="btn-primary" disabled={vm.picked.length === 0} onClick={vm.confirmPicker}
