export function Media(props: MediaProps) {
  // No `MediaProps = {}` default on the parameter itself (same reasoning as `App.tsx`'s own
  // `AppProps` — see that file's comment): every real call site is JSX (`<Media />` in
  // `panels.tsx`/tests), and JSX's `createElement`/`jsx` runtime always constructs an actual props
  // object — `{}` when no attributes are given, never `undefined` — so `Media` is never invoked
  // with zero arguments the way a plain function call could be. `MediaProps`' three fields are all
  // optional, so `{}` satisfies the type and this compiles the same as before for every existing
  // call site.
  // Keep both injection seams. Forwarding resolvers previously isolated the default branches
  // for the complexity gate; Media is small enough to resolve them directly.
  const useMediaHook = props.useMediaHook ?? useWiredMedia;
  const useMediaTabsHook = props.useMediaTabsHook ?? useMediaTabs;
  const controller = useMediaHook();
  const { media, error, t } = controller;
  const { activeTab, setActiveTab } = useMediaTabsHook(props.tabId);
  const { notFound } = useMediaItemLink({
    itemId: props.itemId,
    activeTab,
    media,
    editingId: controller.editingId,
    setEditingId: controller.setEditingId,
  });

  if (error && !media) return <div className="notice error">{error}</div>;
  if (!media) return <div className="notice">{t("Loading media…")}</div>;

  // Per-tab item counts (owner ask, 2026-09-26) — computed once here, after the loading guard above
  // so `media` is non-null, and shared by BOTH of this function's returns below (External Providers
  // included), since the tab bar itself renders identically regardless of which tab is active.
  // "External Providers" is not `media`-derived at all: it counts the fixed provider CATALOG
  // (`MEDIA_PROVIDER_CATALOG`, imported above) rather than a live server fetch — that catalog is the
  // exact same array `ExternalProvidersPanel`'s `MediaProvidersTab` maps one card per entry from, so
  // its length is already "what that tab lists" with no extra request and nothing that could ever
  // go stale relative to what renders when the tab opens.
  const tabCounts: Partial<Record<MediaTabId, number>> = {
    ...mediaContentTabCounts(media),
    "external-providers": MEDIA_PROVIDER_CATALOG.length,
  };

  // External Providers renders no grid, no filter, and has no concept of the grid's "empty" state —
  // an early return here (rather than a ternary further down) is what lets `MediaContentTabId`
  // narrow `activeTab` for the REST of this function, so `filterMediaByTab`/`MediaLibraryPanel`
  // below can declare that narrower type directly instead of re-widening to the full tab set (see
  // `MediaContentTabId`'s own doc comment in `use-media-tabs.hooks.ts`).
  if (activeTab === "external-providers") {
    return (
      <MediaPageShell t={t} activeTab={activeTab} setActiveTab={setActiveTab} tabCounts={tabCounts}>
        <ExternalProvidersPanel locale={controller.locale} />
      </MediaPageShell>
    );
  }

  // Computed after every early return so `media` is non-null and `activeTab` is narrowed to
  // `MediaContentTabId`. Not memoized: a single filter over a media library is cheap next to the
  // render it feeds, and a `useMemo` here cannot be hoisted above the early returns without
  // changing hook order.
  const visibleMedia = sortMediaByOrder(filterMediaByTab(media, activeTab), controller.orderBy);
  // Asset ids are stable and unique, so they disambiguate one card's expand button from another's —
  // same reasoning as every other list on this workstream.
  const mediaExpandHandles = buildAgentListHandles({ prefix: "media-item", ids: visibleMedia.map((item) => item.id) }
  );

  return (
    <MediaPageShell t={t} activeTab={activeTab} setActiveTab={setActiveTab} tabCounts={tabCounts}>
      {/* "all", "images" and "videos" all render the SAME grid, differing only in which items reach
          it — one code path, so a card looks and behaves identically whichever tab it is viewed
          from, and the lightbox/edit/row-menu wiring below cannot drift per tab. */}
      {notFound ? <div className="notice">{t("That media item wasn't found.")}</div> : null}
      <MediaLibraryPanel
        {...controller}
        media={media}
        activeTab={activeTab}
        visibleMedia={visibleMedia}
        mediaExpandHandles={mediaExpandHandles}
      />
    </MediaPageShell>
  );
}

/** The preview image/video and decorative backdrop share one fitted asset snapshot. */
function MediaCardPicture({ preview }: { preview: ReturnType<typeof useWiredMediaPreview> }) {
  const { stage, src, altText, handleImageError, handleVideoError, shape, handleImageLoad, handleVideoMetadata } = preview;
  const badges = shape ? mediaShapeBadges(shape) : null;
  // A `<video>` without `controls` is not interactive content, so (like an `<img>`) it may sit
  // inside the expand button: clicking the still frame opens the lightbox for both kinds.
  const fill = shape ? mediaFillsPreview(shape) : false;
  const fit = fill ? " media-card-media--fill" : "";
  const media = stage === "video" ? (
    <video className={`media-card-media${fit}`} src={src} preload="metadata" muted playsInline aria-label={altText} onError={handleVideoError} onLoadedMetadata={handleVideoMetadata} />
  ) : (
    <img className={badges?.isLong ? "media-card-media media-card-media--long" : `media-card-media${fit}`} src={src} alt={altText} loading="lazy" onError={handleImageError} onLoad={handleImageLoad} />
  );
  // A tall or very wide image stays whole (never cropped), so its spare space gets a soft blurred
  // copy of the same picture instead of flat gray. Videos keep the card background: a second
  // decoding <video> per tile is not worth a blur.
  const backdrop = showMediaBackdrop({ stage, shape, fill, badges }) ? (
    <img className="media-card-backdrop" src={src} alt="" aria-hidden="true" loading="lazy" />
  ) : null;

  return <>{backdrop}{media}</>;
}

/** Only still images with spare space need a decorative blurred copy; never decode a second video. */
function showMediaBackdrop({ stage, shape, fill, badges }: {
  stage: ReturnType<typeof useWiredMediaPreview>["stage"]; shape: MediaShape | null;
  fill: boolean; badges: ReturnType<typeof mediaShapeBadges> | null;
}): boolean {
  return stage === "image" && !!shape && !fill && !badges?.isLong;
}

/** Shape-derived labels omit unknown dimensions and inapplicable duration without hiding other metadata. */
function mediaShapeParts({ shape, t }: { shape: MediaShape | null; t: (key: string) => string }): ReactNode[] {
  const badges = shape ? mediaShapeBadges(shape) : null;
  const parts: ReactNode[] = [];
  if (badges?.isLong) parts.push(<span key="long">{t("Long image")}</span>);
  if (badges) parts.push(<span key="size">{badges.size}</span>);
  if (badges?.duration) parts.push(<span key="duration">{badges.duration}</span>);

  return parts;
}

import { agentHandle } from "@jini-ai/agentic";
import { resolveTabBarTabIndex, useTabBarKeyboard } from "@jini-ai/ui/tab-strip";

import type { AdminMenuItem, AdminMenuItemAttrs, AdminMenuMode } from "../../lib/api";
import type { Translate } from "@jini-ai/ui/panel-kit";
import { useWiredMenuEditor, type MenuEditorController } from "./hooks/use-menu-editor.hooks";
import { useMenuItemRemove } from "./MenuEditor.hooks";
import { MenuPageLinkFields } from "./MenuPageLinkFields";
import type { MenuPageChoice } from "./page-link-rules";
import { useMenuTargetEditor } from "./MenuPageLinkFields.hooks";
export { targetForKind } from "./page-link-rules";

/**
 * @file Per-menu tree editor (ADR-029 whole-tree replace) — markup only.
 *
 * v1 scope: a simple recursive nested-list UI — each item shows its
 * label/target-kind/target-value with add-child/remove/reorder controls.
 * No drag-and-drop.
 *
 * Every piece of state and every API call lives in `hooks/use-menu-editor.hooks.ts`; see that
 * file's header for why. What stays here is `ItemRow` plus
 * `MenuItemTargetFields`/`MenuItemAttrsFields` — presentation concerns invoked directly from
 * `ItemRow`'s own markup, not part of the hook's state transitions. Target reshaping now lives in
 * `page-link-rules.ts` and `MenuPageLinkFields.hooks.ts`. `ItemRow`'s Remove-button
 * confirmation logic (`countDescendants` included) lives in the colocated `MenuEditor.hooks.tsx`
 * instead — see that file's header for why.
 *
 * `MenuItemAttrsFields` exposes `NavItemAttrs`'s five presentational fields (Jini
 * `packages/cms/src/navigation/types.ts:104-115` — `cssClass`/`description`/`icon`/`openInNewTab`/
 * `rel`) behind a per-item `<details>` disclosure. These already round-trip through storage
 * untouched (`validateAndCloneTree` in Jini's `menu-service.ts` clones each node with `{ ...node,
 * children }`, never touching `attrs`) and the static-tier theme renderer already consumed
 * `cssClass`/`icon`/`description` — this screen was simply the one gap in an otherwise-working
 * pipeline. `rel`/`openInNewTab` were not consumed by ANY render path before this change; both the
 * static-tier tree-variant renderer (`features/theme/static-render.ts`) and the widget-IR menu
 * renderer (`server/inbound/public-http/http/site/render.ts`) now honor all five fields.
 */

/**
 * `?? ""` as a named function rather than inline. ESLint's cyclomatic-complexity rule counts each
 * `??` as its own branch — six of them across {@link targetForKind} and {@link MenuItemTargetFields}
 * below (2026-08-06, complexity pass, fourth pass) inflated each function's flat 4-case switch from
 * a base of ~5 to 10, even though cognitive complexity for both is 1: no nesting, four sibling cases,
 * each a single fallback. Naming the fallback removes the count from each switch's own scope without
 * changing what either function produces — every call site still falls back to `""` for exactly the
 * same absent values it did before.
 */
function orEmpty(value: string | undefined): string {
  return value ?? "";
}

/** Boolean counterpart to {@link orEmpty}, same rationale — see {@link attrsOrDefaults}. */
function orFalse(value = false): boolean {
  return value;
}

/**
 * Same rationale as {@link orEmpty} above: five `attrs?.field ?? default` fallbacks inlined
 * directly in {@link MenuItemAttrsFields}'s JSX pushed its cyclomatic complexity from a base of
 * ~6 (five sibling fields + the disclosure) to 11 — each `?.` and `??` is its own branch. Naming
 * the defaulting removes that count from the component's own scope without changing what any
 * field renders; every caller still sees the same fallback for the same absent value.
 */
function attrsOrDefaults(attrs: AdminMenuItemAttrs | undefined): Required<AdminMenuItemAttrs> {
  const a = attrs ?? {};
  return {
    cssClass: orEmpty(a.cssClass),
    icon: orEmpty(a.icon),
    description: orEmpty(a.description),
    rel: orEmpty(a.rel),
    openInNewTab: orFalse(a.openInNewTab),
  };
}

/**
 * The target-kind-specific field(s) — URL/Route/Entry each show one input, Term shows two.
 * Extracted out of `ItemRow`'s four `item.target.kind === "…" ? (...) : null` blocks (its entire
 * branch count beyond the label field and the children map) into a `switch` over the same
 * target-kind union `targetForKind` (now re-exported from rules) switches on — same convention, and
 * unlike an if/else-if chain a `switch`'s cases don't nest, which is what keeps this low under
 * cognitive complexity too. Uses {@link orEmpty} for the same reason `targetForKind` above does —
 * see that function's doc.
 */
export function MenuItemTargetFields({
  item,
  path,
  onChange,
  t,
}: {
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  t: Translate;
}) {
  switch (item.target.kind) {
    case "url":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">URL</span>
          <input
            value={orEmpty(item.target.href)}
            placeholder="https://…"
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, href: e.target.value } }))}
          />
        </label>
      );
    case "route":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Route name")}</span>
          <input
            value={orEmpty(item.target.route)}
            placeholder={t("route name")}
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, route: e.target.value } }))}
          />
        </label>
      );
    case "entryRef":
      return (
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Entry ID")}</span>
          <input
            value={orEmpty(item.target.entryId)}
            placeholder={t("entry id")}
            onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, entryId: e.target.value } }))}
          />
        </label>
      );
    case "termRef":
      return (
        <>
          <label className="a11y-label-wrap">
            <span className="visually-hidden">{t("Term ID")}</span>
            <input
              value={orEmpty(item.target.termId)}
              placeholder={t("term id")}
              onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, termId: e.target.value } }))}
            />
          </label>
          <label className="a11y-label-wrap">
            <span className="visually-hidden">{t("Taxonomy")}</span>
            <input
              value={orEmpty(item.target.taxonomy)}
              placeholder={t("taxonomy")}
              onChange={(e) => onChange(path, (it) => ({ ...it, target: { ...it.target, taxonomy: e.target.value } }))}
            />
          </label>
        </>
      );
    default:
      // Every target kind is handled above; an unknown one renders no fields.
      return null;
  }
}

/**
 * `NavItemAttrs`'s five presentational fields, collapsed behind a `<details>` disclosure rather
 * than five more always-visible inputs on an already-dense row (label/kind/target-value/move/
 * child/remove) — see this file's own header for why they're safe to expose now. Applies
 * identically to every target kind, unlike {@link MenuItemTargetFields}'s kind-specific fields, so
 * it renders once per row rather than switching on `item.target.kind`. Native `<details>` needs no
 * open/closed state of its own (browser-managed), so this stays presentation-only, same as
 * {@link MenuItemTargetFields} above.
 */
export function MenuItemAttrsFields({
  item,
  path,
  onChange,
  t,
}: {
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  t: Translate;
}) {
  const attrs = attrsOrDefaults(item.attrs);

  return (
    <details className="menu-item-advanced">
      <summary>{t("Advanced")}</summary>
      <div className="menu-item-advanced-fields">
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("CSS class")}</span>
          <input
            value={attrs.cssClass}
            placeholder={t("CSS class")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, cssClass: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Icon")}</span>
          <input
            value={attrs.icon}
            placeholder={t("Icon")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, icon: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Description")}</span>
          <input
            value={attrs.description}
            placeholder={t("Description")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, description: e.target.value } }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Link rel")}</span>
          <input
            value={attrs.rel}
            placeholder={t("Link rel")}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, rel: e.target.value } }))}
          />
        </label>
        <label className="menu-item-advanced-checkbox">
          <input
            type="checkbox"
            checked={attrs.openInNewTab}
            onChange={(e) => onChange(path, (it) => ({ ...it, attrs: { ...it.attrs, openInNewTab: e.target.checked } }))}
          />
          {t("Open in new tab")}
        </label>
      </div>
    </details>
  );
}

function ItemRow(props: {
  pages?: readonly MenuPageChoice[];
  item: AdminMenuItem;
  path: number[];
  onChange: (path: number[], fn: (item: AdminMenuItem) => AdminMenuItem) => void;
  onRemove: (path: number[]) => void;
  onAddChild: (path: number[]) => void;
  onMove: (path: number[], direction: -1 | 1) => void;
  t: Translate;
}) {
  const { item, path, onChange, onRemove, onAddChild, onMove, t, pages } = props;
  const { handleRemoveClick } = useMenuItemRemove(item, path, onRemove);
  const targetController = useMenuTargetEditor({ item, path, onChange, pages });

  return (
    <div className="menu-item-row" style={{ marginLeft: path.length * 20 }}>
      <div className="menu-item-fields">
        {/* Audit finding: every control below was placeholder-only (or, for the `<select>`, had no
            accessible name at all — no placeholder, no label, nothing). Each now wraps in a real
            `<label>` with a `.visually-hidden` name, same fix and same reasoning as the title/slug
            fields above — see `styles/editor.css`'s `.a11y-label-wrap` comment for why the wrap
            costs no layout in this dense flex row. */}
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Item label")}</span>
          <input
            value={item.label ?? ""}
            placeholder={t("Label")}
            onChange={(e) => onChange(path, (it) => ({ ...it, label: e.target.value }))}
          />
        </label>
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Link type")}</span>
          <select
            value={targetController.kind}
            onChange={targetController.selectType}
          >
            <option value="url">{t("URL")}</option>
            <option value="route">{t("Route")}</option>
            <option value="page">{t("Page")}</option>
            <option value="entryRef">{t("Entry")}</option>
            <option value="termRef">{t("Term")}</option>
          </select>
        </label>
        {targetController.isPage
          ? <MenuPageLinkFields item={item} path={path} pages={pages} onChange={onChange} t={t} />
          : <MenuItemTargetFields item={item} path={path} onChange={onChange} t={t} />}
        {/* `aria-label` alongside `title`: `title` alone isn't reliably exposed to assistive tech
            and isn't keyboard-discoverable without a mouse hover (audit Minor finding). */}
        <button className="tb-btn" onClick={() => onMove(path, -1)} title={t("Move up")} aria-label={t("Move item up")}>
          ↑
        </button>
        <button className="tb-btn" onClick={() => onMove(path, 1)} title={t("Move down")} aria-label={t("Move item down")}>
          ↓
        </button>
        <button className="tb-btn" onClick={() => onAddChild(path)} title={t("Add child item")}>
          {t("+ child")}
        </button>
        <button
          className="tb-btn"
          // Audit Major finding: Remove previously deleted the clicked item's entire subtree in
          // one click, no confirmation, no indication children existed — hits hardest for a
          // screen-reader user, since the same indentation a sighted operator reads "this has
          // children" from (`marginLeft: path.length * 20` below) carries no structural signal
          // for them either. A leaf item (no children) stays a bare click, matching this screen's
          // own `FormFieldsEditor`-sibling "Remove" convention for low-stakes removals — see
          // `MenuEditor.hooks.tsx`'s `useMenuItemRemove` for the confirmation logic itself.
          onClick={handleRemoveClick}
          title={t("Remove item")}
          // `✕` is this button's only text content, so — unlike Move up/down above, whose glyphs
          // are at least paired with a real word via `title` alone being insufficient too — its
          // accessible name would otherwise compute to the glyph itself ("✕"/"multiplication
          // sign"), not "Remove item". Found empirically while adding this button's test:
          // `title` is never part of the accessible-name computation when text content exists.
          aria-label={t("Remove item")}
        >
          ✕
        </button>
      </div>
      <MenuItemAttrsFields item={item} path={path} onChange={onChange} t={t} />
      {(item.children ?? []).map((child, i) => (
        <ItemRow
          key={child.id}
          item={child}
          path={[...path, i]}
          onChange={onChange}
          onRemove={onRemove}
          onAddChild={onAddChild}
          onMove={onMove}
          t={t}
          pages={pages}
        />
      ))}
    </div>
  );
}

/** The "Options" | "HTML" tabs, keyed by the {@link AdminMenuMode} each one saves. `id` is what the
 *  `@jini-ai/ui/tab-strip` keyboard helpers key on — the same `.segmented` tablist PageEditor uses. */
const MODE_TABS: ReadonlyArray<{ id: AdminMenuMode; label: string }> = [{ id: "items", label: "Options" }, { id: "html", label: "HTML" }];

/**
 * The authoring-mode tablist — PageEditor's `.page-editor-toolbar` > `.segmented role=tablist` row,
 * with the shared arrow/Home/End keys and roving tab stop from `useTabBarKeyboard`.
 */
function MenuModeTabs({ mode, onChange, t }: { mode: AdminMenuMode; onChange: (mode: AdminMenuMode) => void; t: Translate }) {
  const { onKeyDown } = useTabBarKeyboard({ tabs: MODE_TABS, activeId: mode, onChange: (id) => onChange(id as AdminMenuMode) });
  return (
    <div className="page-editor-toolbar">
      <div className="segmented" role="tablist" aria-label={t("Menu editor mode")} onKeyDown={onKeyDown}>
        {MODE_TABS.map((tab) => (
          <button
            key={tab.id}
            type="button"
            role="tab"
            aria-selected={mode === tab.id}
            className={mode === tab.id ? "is-active" : undefined}
            tabIndex={resolveTabBarTabIndex({ tabs: MODE_TABS, activeId: mode, tab })}
            onClick={() => onChange(tab.id)}
            {...agentHandle({ handle: `menu-mode-${tab.id}` }, { role: "button", label: `Switch to the ${tab.label} tab` })}
          >
            {/* Literal keys, not `t(tab.label)`: the i18n parity test resolves every key statically. */}
            {t(tab.id === "html" ? "HTML" : "Options")}
          </button>
        ))}
      </div>
    </div>
  );
}

export interface MenuEditorProps {
  menuId: string | null;
  /** Dependency injection seam for tests — the same convention `@jini-ai/ui`'s `CustomSelect` uses
   *  for `useCustomSelect`. Defaulted to the real hook, so production callers (`panels.tsx`) pass
   *  only `menuId` and behave exactly as before. */
  useMenuEditorHook?: typeof useWiredMenuEditor;
}

/** The menu's navigation and save controls share one header in both authoring modes. */
function MenuEditorHeader({ editor }: {
  editor: Pick<MenuEditorController, "isNew" | "menu" | "copyHtmlEmbed" | "copyFeedback" | "message" | "save" | "saving" | "confirmLeave" | "t">;
}) {
  const { isNew, menu, copyHtmlEmbed, copyFeedback, message, save, saving, confirmLeave, t } = editor;
  /* `page-header-split` (`styles.css`) — same shared idiom Pages/Posts/Forms already use:
        back link alone at the left rail, title block centred. Menus (like Widgets) never grew a
        separate `.editor-action-row` below a toolbar, so Save/status stay IN the header instead
        of an empty third rail — `.page-header-actions` (`styles.css`) pins that rail to the
        right and gives it its own narrow-container stacking row alongside the back link (owner,
        2026-09-22: "put the back button on the left, like the other editors" — this used to be a
        plain `.page-header`/`.page-actions` row with Back and Save both crowded at the right). */
  return (
    <div
      className="page-header page-header-split"
      {...agentHandle({ handle: "menu-editor-header" }, {
        role: "region",
        label: "Menu editor header — the back link, the menu's title, and the Save button",
      })}
    >
      <div className="page-header-lead">
        {/* Audit finding: no editor screen warns before an in-app navigation discards unsaved
            edits — confirmed live on this exact screen. `preventDefault()` here also stops
            `router.ts`'s document-level click interceptor from firing `navigate()`, since that
            listener's first check is `event.defaultPrevented` — no change to `router.ts` needed.
            Plain `<a className="btn-secondary">`, not a `<button>` nested inside an `<a>`
            (invalid HTML) — same fix Pages/Posts/Forms' own back links already made; this one
            still carried the old nested-button markup.

            Visible label shortened to a plain "← Back" (owner, 2026-09-22 — every editor's back
            button reads the same short way now). `aria-label` keeps "Back: Menus" — colon-joined
            rather than concatenated into a sentence so it needs no new per-locale phrase key and
            still starts with the exact visible text (WCAG 2.5.3 Label in Name). */}
        <a
          className="btn-secondary"
          href="/admin/menus"
          onClick={(e) => {
            if (!confirmLeave()) e.preventDefault();
          }}
          aria-label={`${t("Back")}: ${t("Menus")}`}
          {...agentHandle({ handle: "menu-editor-back" }, { role: "link", label: "Back to the list of all menus" })}
        >
          ← {t("Back")}
        </a>
      </div>
      <div className="page-header-text">
        <p className="page-kicker">{t("Content")}</p>
        <h1 className="page-title">{t(isNew ? "New menu" : "Edit menu")}</h1>
        <p className="page-description">{t("Build this menu's items and where each one links to.")}</p>
      </div>
      <div
        className="page-header-actions page-actions"
        {...agentHandle({ handle: "menu-editor-actions" }, { role: "region", label: "Save status and the Save button" })}
      >
        {menu ? <button type="button" className="btn-secondary" onClick={copyHtmlEmbed} {...agentHandle({ handle: "menu-editor-copy-html-embed" }, { role: "button", label: "Copy this menu's HTML embed" })}>{t("Copy HTML embed")}</button> : null}
        {copyFeedback ? <span role="status">{copyFeedback}</span> : null}
        {message ? <span className="save-ok">{message}</span> : null}
        <button onClick={save} disabled={saving} {...agentHandle({ handle: "menu-editor-save" }, { role: "button", label: "Save this menu" })}>
          {t("Save")}
        </button>
      </div>
    </div>
  );
}

export function MenuEditor({ menuId, useMenuEditorHook = useWiredMenuEditor }: MenuEditorProps) {
  const editor = useMenuEditorHook(menuId);
  const {
    pageChoices,
    isNew,
    menu,
    title,
    setTitle,
    slug,
    setSlug,
    items,
    mode,
    changeMode,
    html,
    setHtml,
    error,
    loading,
    changeAt,
    removeAt,
    addChildAt,
    moveAt,
    addRootItem,
    t,
  } = editor;

  if (error && !isNew && !menu) return <div className="notice error">{error}</div>;
  if (loading) return <div className="notice">{t("Loading menu…")}</div>;

  return (
    <div className="page">
      <MenuEditorHeader editor={editor} />
      {/* Forms' full-width notice keeps save refusals (permission, size cap, unbalanced markup)
          readable outside the narrow header rail in both authoring modes.
          Above the source, not below: the textarea is 512px tall, so an error under it sat
          below the fold at desktop height. */}
      {error ? <div className="notice error" role="alert">{error}</div> : null}
      {/* Title and slug share one row — PostEditor's `.editor-title-row` (`styles.css` stacks it at
          narrow widths). Audit finding: both were placeholder-only, no `<label>` — same fix as
          `PostEditor.tsx`'s title/slug (see `styles/editor.css`'s `.a11y-label-wrap` comment). */}
      <div className="editor-title-row">
        <label className="a11y-label-wrap">
          <span className="visually-hidden">{t("Menu title")}</span>
          <input
            className="editor-title"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            placeholder={t("Menu title")}
          />
        </label>
        <div className="editor-slug">
          /{" "}
          <label className="a11y-label-wrap">
            <span className="visually-hidden">{t("Menu slug")}</span>
            <input value={slug} onChange={(e) => setSlug(e.target.value)} placeholder="menu-slug" />
          </label>
          {/* The internal id used to be surfaced here as a read-only field (2026-08-09). Removed
              2026-08-11 alongside PostEditor's, and this one had the stronger case for going: a menu's
              id is minted by `idGen.newId()`, so it is random per install and a theme can never
              reference it — which is exactly why `ffc0f44` made theme menu markers resolve by SLUG
              first. Showing the id next to the slug invited an author to paste the one handle that
              provably cannot work in a shipped theme. */}
        </div>
      </div>
      <MenuModeTabs mode={mode} onChange={changeMode} t={t} />
      {/* HTML mode: the author's own markup, rendered inside the theme's menu element so theme
          CSS still applies — forms' HTML editor class and trust model (`pages.edit_html`). */}
      {mode === "html" ? (
        <>
          <textarea
            className="page-html-source"
            value={html}
            onChange={(e) => setHtml(e.target.value)}
            spellCheck={false}
            aria-label={t("Menu HTML")}
            {...agentHandle({ handle: "menu-html-source" }, { role: "field", label: "This menu's raw HTML" })}
          />
        </>
      ) : (
        <div className="menu-tree">
          {items.map((item, i) => (
            <ItemRow
              key={item.id}
              item={item}
              path={[i]}
              onChange={changeAt}
              onRemove={removeAt}
              onAddChild={addChildAt}
              onMove={moveAt}
              t={t}
              pages={pageChoices}
            />
          ))}
          {/* Secondary, not bare/primary — Save in the header is this screen's one primary action;
              an equally-loud "+ Add item" here would be the same two-primaries flatness problem
              `styles.css`'s button-hierarchy comment describes for row actions, just at the
              page level instead of a table row. */}
          <button type="button" className="btn-secondary" onClick={addRootItem}>
            {t("+ Add item")}
          </button>
        </div>
      )}
    </div>
  );
}

