/**
 * The VERSION-CONFLICT banner (2026-09-07) — an EXPLICIT Save/Publish the server rejected, with a
 * way past it. Mirrors `features/posts/PostEditor.tsx`'s `PostVersionConflictBanner`.
 *
 * Distinct from `PageAutosaveStaleBanner` below, which reports the same collision hitting the
 * BACKGROUND autosave: that one is a state the operator never asked for and gets no buttons, this
 * one is a button they pressed and watched fail, so it owes them an answer. `pageVersionConflict
 * Message` (`rules.ts`) owns the wording so this component stays markup only.
 *
 * "Save anyway" is the only way past the conflict, and that is on purpose: the plain Save button
 * keeps failing until the operator explicitly chooses to replace the other version. Copy is
 * hardcoded English, matching every other string in this file — `PageEditor.tsx` is out of the
 * pages dictionary's declared scope (see `pages-i18n.ts`'s own header).
 */
function PageVersionConflictBanner({
  saveConflict,
  onSaveAnyway,
  onDismiss,
  t,
}: {
  saveConflict: PageSaveConflict;
  onSaveAnyway: () => void;
  onDismiss: () => void;
  t: Translate;
}) {
  return (
    <div
      className="notice error"
      {...agentHandle({ handle: "page-version-conflict" }, {
        role: "region",
        label: "Another operator saved this while you were editing — your changes are unsaved and still in the editor",
      })}
    >
      <p>{pageVersionConflictMessage(t, saveConflict)}</p>
      <button
        type="button"
        className="btn-secondary"
        onClick={onSaveAnyway}
        {...agentHandle({ handle: "page-version-conflict-overwrite" }, {
          role: "button",
          label: "Save these changes anyway, replacing the version the other operator saved",
        })}
      >
        {t("Save anyway")}
      </button>
      <button
        type="button"
        className="btn-secondary"
        onClick={onDismiss}
        {...agentHandle({ handle: "page-version-conflict-dismiss" }, {
          role: "button",
          label: "Hide this notice and keep editing without saving",
        })}
      >
        {t("Keep editing")}
      </button>
    </div>
  );
}

/**
 * Standing-draft autosave — the STALE-BASIS notice (2026-09-06). The counterpart to
 * `PageAutosaveRecoveryBanner` above and not a duplicate of it: that banner offers work found parked
 * from a PREVIOUS session, this reports that background autosaving has STOPPED for the session
 * happening right now, because another operator's save moved this page's version out from under this
 * tab. Until then the operator had no way to know — the editor looked completely normal while every
 * write it made was being thrown away. `pageAutosaveStaleBasisMessage` (`rules.ts`) owns the wording
 * so this component stays markup only, the same split the recovery banner already uses.
 *
 * NO buttons, deliberately, and this is the one design decision here worth defending:
 * - A "Dismiss" would let the operator silence a warning that is still true, putting them straight
 *   back into the silent data loss this whole path exists to end. The notice clears by itself when
 *   autosaving actually resumes (`usePageEditor`'s `autosaveStaleBasis` goes null once a write is
 *   accepted on a fresh basis) and at no other time, so it can never be lying while it is on screen.
 * - A "Reload" would wipe the operator's typed text out of the editor on their behalf. Their only
 *   remaining copy would then be the shared hook's best-effort browser-storage mirror, which is not
 *   a guarantee this component can make on their behalf (`localStorage` throws outright in some
 *   privacy modes). The message tells them to copy their work first and leaves the choice with them.
 */
function PageAutosaveStaleBanner({ staleBasis, t }: { staleBasis: StandingDraftStaleBasis; t: Translate }) {
  return (
    <div
      className="notice warning"
      {...agentHandle({ handle: "page-autosave-stale" }, {
        role: "region",
        label:
          "Another operator saved this page while you were editing — autosaving has stopped, and your " +
          "unsaved changes are still here in the editor",
      })}
    >
      <p>{pageAutosaveStaleBasisMessage(t, staleBasis)}</p>
    </div>
  );
}

/**
 * The EXTERNAL-CHANGE notice (2026-09-16) — an assistant tool wrote a newer version of this page
 * while the editor had unsaved edits. A CLEAN editor applies the newer version silently instead (see
 * `use-external-entry-refresh.hooks.ts`); this banner exists only for the case a silent apply could
 * clobber unsaved work — which, on the Interactive tab, is always assumed, because canvas typing can
 * be invisible to `dirty` (see `pageRefreshMayHaveUnsavedEdits`, `rules.ts`).
 *
 * Distinct from `PageVersionConflictBanner` above: that one is a Save the operator pressed and
 * watched fail; this one is a background check that found the row moved before they ever pressed
 * Save. "Load latest" mirrors that banner's "Save anyway" in shape (an explicit, named action) but
 * opposite in effect — it discards the operator's edits rather than the other write.
 */
export function PageExternalChangeBanner({ onLoadLatest, onKeepEdits, t }: { onLoadLatest: () => void; onKeepEdits: () => void; t: Translate }) {
  return (
    <div
      className="notice warning"
      {...agentHandle({ handle: "page-external-change" }, {
        role: "region",
        label: "This page was changed outside the editor, probably by the assistant — load the latest version or keep your unsaved edits",
      })}
    >
      <p>{t(PAGE_EXTERNAL_CHANGE_MESSAGE)}</p>
      <button
        type="button"
        className="btn-secondary"
        onClick={onLoadLatest}
        {...agentHandle({ handle: "page-external-change-load-latest" }, {
          role: "button",
          label: "Load latest version, discarding my unsaved edits",
        })}
      >
        {t("Load latest")}
      </button>
      <button
        type="button"
        className="btn-secondary"
        onClick={onKeepEdits}
        {...agentHandle({ handle: "page-external-change-keep-edits" }, {
          role: "button",
          label: "Keep my edits and ignore the outside change",
        })}
      >
        {t("Keep my edits")}
      </button>
    </div>
  );
}

/**
 * The four "something happened to your work" notices, grouped into one component so their four
 * independent render decisions are scored in this scope instead of accumulating onto `PageEditor`'s
 * own complexity — same extraction `features/posts/PostEditor.tsx`'s `PostEditorNotices` already
 * makes, added there for the identical reason (recovery/stale-basis/conflict already put that
 * component over the ceiling; a fourth notice here would do the same to this one).
 *
 * Order: recovery (work from a previous session) first, then the stale-basis notice (a condition
 * still true right now), then the rejected save (the most recent thing the operator personally did),
 * then the external-change notice last (the newest kind, and the only one whose trigger — an
 * assistant write — has nothing to do with what the operator themselves just did). All four can be
 * true at once; none is suppressed in favor of another.
 */
function PageEditorNotices({
  recoverableDraft,
  serverUpdatedAt,
  onRestore,
  onDiscard,
  autosaveStaleBasis,
  saveConflict,
  onSaveAnyway,
  onDismissConflict,
  pendingExternalVersion,
  onLoadExternalChange,
  onDismissExternalChange,
  t,
}: {
  recoverableDraft: StandingDraftAutosaveSnapshot | null;
  serverUpdatedAt: string;
  onRestore: () => void;
  onDiscard: () => void;
  autosaveStaleBasis: StandingDraftStaleBasis | null;
  saveConflict: PageSaveConflict | null;
  onSaveAnyway: () => void;
  onDismissConflict: () => void;
  pendingExternalVersion: number | null;
  onLoadExternalChange: () => void;
  onDismissExternalChange: () => void;
  t: Translate;
}) {
  return (
    <>
      {recoverableDraft ? (
        <PageAutosaveRecoveryBanner
          recoverableDraft={recoverableDraft}
          serverUpdatedAt={serverUpdatedAt}
          onRestore={onRestore}
          onDiscard={onDiscard}
          t={t}
        />
      ) : null}
      {/* Waits while the outside-change notice is up: one moved version, one banner — see `PostEditorNotices`. */}
      {autosaveStaleBasis && pendingExternalVersion === null ? <PageAutosaveStaleBanner staleBasis={autosaveStaleBasis} t={t} /> : null}
      {saveConflict ? (
        <PageVersionConflictBanner saveConflict={saveConflict} onSaveAnyway={onSaveAnyway} onDismiss={onDismissConflict} t={t} />
      ) : null}
      {pendingExternalVersion !== null ? (
        <PageExternalChangeBanner onLoadLatest={onLoadExternalChange} onKeepEdits={onDismissExternalChange} t={t} />
      ) : null}
    </>
  );
}

/**
 * The toolbar's right-hand group — the device-width control (preview view only) and the template
 * picker. Extracted out of `PageEditor` for the same reason `PageEditorHeader` above was: this is
 * where nearly all of the remaining branching in that component's render lived (the preview-only
 * visibility check, the html-format check, and the has-templates check nested inside it), and as a
 * top-level function its branches are scored in their own scope instead of accumulating onto
 * `PageEditor`'s.
 *
 * Device-width control and template picker share this one row (owner feedback, 2026-08-11: "move the
 * UI for the template dropdown where the desktop tablet mobile is right now ... so it's all one row"
 * — the picker's own standalone row above is gone). `.page-editor-toolbar-end` is a plain grouping
 * wrapper (`pages.css`) so `.page-editor-toolbar`'s existing `justify-content: space-between` still
 * only has to place two things: the view tabs on the left, this group on the right.
 *
 * The template picker mirrors `PostEditor.tsx`'s own `.editor-template-picker` markup/classes
 * verbatim. Rendered only for an `"html"`-format Page: a `"doc"`-format Page (pre-conversion legacy
 * row) has no render path that would honor a template choice yet (`isEligibleForTemplateBranch`
 * requires `bodyFormat: "html"`), so showing the picker on one would let an operator set a value with
 * no visible effect.
 *
 * UNLIKE the Post picker, the selected value is NOT defaulted to the theme's first template when
 * unset — see `use-page-editor.hooks.ts`'s load effect and `isEligibleForTemplateBranch`'s doc for the
 * full reasoning: "no template chosen" is a Page's normal, fully-working state (render its own body
 * through the theme's own page shell — "Theme default"), not an absence-of-decision needing a UI
 * default to stay honest.
 *
 * Bare-page ruling (2026-09-23, S6): `null` and `""` used to render identically and this picker showed
 * both as "No template chosen". They now diverge — `null` still renders through the theme's page shell
 * ("Theme default"), `""` renders ONLY this Page's own HTML (no theme styles, scripts, header or
 * footer) — so the picker routes through {@link pagePickerValue}/{@link pickerValueToChoice} (`rules.ts`)
 * rather than `templateChoice ?? ""` directly, and shows a hint line under the `<select>` whenever the
 * bare option is selected.
 *
 * "View Template" eye button (2026-09-24, parity with `PostEditor.tsx`'s identical control): left of
 * the `<select>`, same shared `ViewTemplateButton` (`components/TemplateSource/ViewTemplateButton.tsx`)
 * Posts renders, disabled whenever nothing is chosen ({@link templateChoice} falsy — covers both
 * "Theme default" (`null`) and the explicit bare "No template" (`""`), neither of which names a real
 * file to show). Opens `TemplateSourceModal` (`PageEditor`'s own `PageEditorTemplateModalGate` below).
 */
function PageEditorToolbarEnd({
  view,
  bodyFormat,
  availableTemplates,
  templateChoice,
  setTemplateChoice,
  onViewTemplateClick,
  t,
}: {
  view: PageEditorView;
  bodyFormat: "doc" | "html" | undefined;
  availableTemplates: string[];
  templateChoice: string | null;
  setTemplateChoice: (value: string | null) => void;
  onViewTemplateClick: () => void;
  t: Translate;
}) {
  const pickerValue = pagePickerValue(templateChoice, availableTemplates);
  return (
    <div className="page-editor-toolbar-end">
      {view === "preview" ? <WiredThemePreviewReloadButton /> : null}
      {bodyFormat === "html" ? (
        <div className="editor-template-picker">
          <ViewTemplateButton
            disabled={!templateChoice}
            onClick={onViewTemplateClick}
            t={t}
            agentHandleId="page-view-template"
          />
          {availableTemplates.length > 0 ? (
            <select
              value={pickerValue}
              aria-label={t("Template")}
              // `pickerValueToChoice`, not the raw `e.target.value` — translates the synthetic
              // `THEME_DEFAULT_SENTINEL` option back to `null`; every other value (a real filename, or
              // the bare `""`) already IS the `templateChoice` to store, see that function's own doc.
              onChange={(e) => setTemplateChoice(pickerValueToChoice(e.target.value))}
              {...agentHandle({ handle: "page-template-choice" }, {
                role: "field",
                label:
                  "Which theme page template this page renders through on the public site. 'No template' serves only the page's own HTML.",
              })}
            >
              {pickerValue === THEME_DEFAULT_SENTINEL ? <option value={THEME_DEFAULT_SENTINEL}>{t("Theme default")}</option> : null}
              {availableTemplates.map((template) => (
                <option key={template} value={template}>
                  {template}
                </option>
              ))}
              <option value="">{t("No template — HTML only")}</option>
            </select>
          ) : (
            <select
              disabled
              value=""
              aria-label={t("Template")}
              {...agentHandle({ handle: "page-template-choice" }, {
                role: "field",
                label: "The active theme declares no page templates, so there is nothing to choose here.",
              })}
            >
              <option value="">{t("No templates for this theme")}</option>
            </select>
          )}
          {/* No hint line beside the select for "No template — HTML only" (owner, 2026-10-10): it
              ran off the right edge on phones and dragged the page sideways. The option's own name
              says what it does. */}
        </div>
      ) : null}
    </div>
  );
}

/**
 * The "View Template" modal's mount gate — mirrors `PostEditor.tsx`'s identical
 * `PostEditorTemplateModalGate` (see that function's own doc for the full "why conditionally
 * mounted, why re-check here" reasoning, which applies unchanged: `PreviewModalShell` has no `open`
 * prop to toggle, and `templateChoice`/`activeThemeId` are re-checked so this can never render with
 * an empty/`null` URL segment even if state changes out from under an already-open modal).
 */
function PageEditorTemplateModalGate({
  show,
  templateChoice,
  activeThemeId,
  activeThemeTier,
  activeThemeApiVersion,
  onClose,
  confirmLeave,
  t,
}: {
  show: boolean;
  templateChoice: string | null;
  activeThemeId: string | null;
  activeThemeTier: ThemeTier | null;
  activeThemeApiVersion: 2 | undefined;
  onClose: () => void;
  confirmLeave: () => boolean;
  t: Translate;
}) {
  if (!show || !templateChoice || !activeThemeId) return null;
  return (
    <TemplateSourceModal
      themeId={activeThemeId}
      themeTier={activeThemeTier}
      themeApiVersion={activeThemeApiVersion}
      templateFilename={templateChoice}
      onClose={onClose}
      confirmLeave={confirmLeave}
      t={t}
      editAgentHandleId="page-template-edit"
    />
  );
}

export function PageEditor({ slug: routeSlug, usePageEditorHook = useWiredPageEditor }: PageEditorProps) {
  const {
    page,
    error,
    message,
    title,
    setTitle,
    slug,
    setSlug,
    status,
    setStatus,
    templateChoice,
    setTemplateChoice,
    availableTemplates,
    activeThemeId,
    activeThemeTier,
    activeThemeApiVersion,
    showTemplateModal,
    onViewTemplateClick,
    onCloseTemplateModal,
    html,
    setHtml,
    draftHtml,
    setDraftHtml,
    htmlTextareaRef,
    onHtmlScroll,
    onPreviewFrameLoad,
    view,
    setView,
    device,
    setDevice,
    previewExpanded,
    togglePreviewExpanded,
    frameRef,
    paneWidth,
    saving,
    dirty,
    contentDirty,
    templatePreviewUrl,
    previewFormRef,
    previewFormTarget,
    canvasStyling,
    save,
    saveConflict,
    saveOverwritingConflict,
    dismissSaveConflict,
    remove,
    confirmingDelete,
    setConfirmingDelete,
    onSave,
    confirmingUnchangedSave,
    onUnchangedSaveConfirm,
    onUnchangedSaveCancel,
    deleting,
    confirmLeave,
    onBackLinkClick,
    recoverableDraft,
    restoreRecoveredDraft,
    discardRecoveredDraft,
    autosaveStaleBasis,
    pendingExternalVersion,
    loadExternalChange,
    dismissExternalChange,
    contentRevision,
    t,
    embedPlaceholderDescriber,
    onRequestEditHtml,
    onInteractiveSourceError,
    interactiveEditorRef,
    setHtmlFromCanvas,
  } = usePageEditorHook(routeSlug);
  // Above the early returns below: `use*` has to be called unconditionally for the rules-of-hooks
  // lint even though this one holds no state of its own.
  const { onKeyDown: onViewTabsKeyDown } = useTabBarKeyboard({ tabs: VIEW_TABS, activeId: view, onChange: (id) => setView(id as PageEditorView) });

  if (error && !page) return <div className="notice error">{error}</div>;
  if (!page) return <div className="notice">{t("Loading editor…")}</div>;

  return (
    <div className="page content-editor-page">
      <PageEditorHeader
        onBackLinkClick={onBackLinkClick}
        title={title}
        setTitle={setTitle}
        slug={slug}
        setSlug={setSlug}
        livePath={pagePublicPath(page.slug)}
        t={t}
      />

      <PageEditorNotices
        recoverableDraft={recoverableDraft}
        serverUpdatedAt={page.updatedAt}
        onRestore={restoreRecoveredDraft}
        onDiscard={discardRecoveredDraft}
        autosaveStaleBasis={autosaveStaleBasis}
        saveConflict={saveConflict}
        onSaveAnyway={() => void saveOverwritingConflict()}
        onDismissConflict={dismissSaveConflict}
        pendingExternalVersion={pendingExternalVersion}
        onLoadExternalChange={() => void loadExternalChange()}
        onDismissExternalChange={dismissExternalChange}
        t={t}
      />

      <div className="page-editor-toolbar">
        {/* Device icons + width sit right next to the view tabs (owner, 2026-10-10, same as Edit
            post); reload, template eye and template select stay on the right. */}
        <div className="content-editor-toolbar-start">
          <div className="segmented" role="tablist" aria-label={t("Editor view")} onKeyDown={onViewTabsKeyDown}>
            {VIEW_TABS.map((entry) => (
              <button
                key={entry.key}
                type="button"
                role="tab"
                aria-selected={view === entry.key}
                className={view === entry.key ? "is-active" : undefined}
                tabIndex={resolveTabBarTabIndex({ tabs: VIEW_TABS, activeId: view, tab: entry })}
                onClick={() => setView(entry.key)}
                {...agentHandle({ handle: `page-view-${entry.key}` }, { role: "button", label: `Switch to the ${entry.label} view` })}
              >
                {t(entry.label)}
              </button>
            ))}
          </div>
          {view === "preview" ? (
            <DevicePreviewToggle device={device} setDevice={setDevice} t={t} handlePrefix="page-preview-width" />
          ) : null}
        </div>
        {/* Reload and the template picker share the toolbar's right-hand side — see
            `PageEditorToolbarEnd`'s own doc for the layout history and the template-picker's rules. */}
        <PageEditorToolbarEnd
          view={view}
          bodyFormat={page.bodyFormat}
          availableTemplates={availableTemplates}
          templateChoice={templateChoice}
          setTemplateChoice={setTemplateChoice}
          onViewTemplateClick={onViewTemplateClick}
          t={t}
        />
      </div>

      {/* Directly under the toolbar, not in the header — see `PageEditorActions`' own doc. */}
      <PageEditorActions
        dirty={dirty}
        message={message}
        error={error}
        status={status}
        setStatus={setStatus}
        saving={saving}
        onPublish={() => save("published")}
        onSave={onSave}
        onDeleteClick={() => setConfirmingDelete(true)}
        t={t}
      />

      <PageEditorPane
        view={view}
        canvasStyling={canvasStyling}
        html={html}
        setHtml={setHtml}
        draftHtml={draftHtml}
        setDraftHtml={setDraftHtml}
        htmlTextareaRef={htmlTextareaRef}
        onHtmlScroll={onHtmlScroll}
        onPreviewFrameLoad={onPreviewFrameLoad}
        device={device}
        slug={slug}
        version={page.version}
        contentRevision={contentRevision}
        status={status}
        dirty={dirty}
        contentDirty={contentDirty}
        templatePreviewUrl={templatePreviewUrl}
        previewFormRef={previewFormRef}
        previewFormTarget={previewFormTarget}
        frameRef={frameRef}
        paneWidth={paneWidth}
        previewExpanded={previewExpanded}
        onTogglePreviewExpanded={togglePreviewExpanded}
        t={t}
        embedPlaceholderDescriber={embedPlaceholderDescriber}
        onRequestEditHtml={onRequestEditHtml}
        onInteractiveSourceError={onInteractiveSourceError}
        interactiveEditorRef={interactiveEditorRef}
        setHtmlFromCanvas={setHtmlFromCanvas}
      />

      {/* Categories & Tags — the same box the post and collection-entry editors mount; it saves on
          its own button, separately from the page's Save/Publish. */}
      <TermPicker contentType={page.kind} contentId={page.id} />

      {/* Save with nothing changed (owner, 2026-10-10): a warning, not a disabled button — same as
          Edit post. "Save anyway" still sends the content; the server writes nothing if it's identical. */}
      <ConfirmDialog
        open={confirmingUnchangedSave}
        agentHandle="page-save-unchanged-confirm"
        title={t("Nothing changed")}
        body={<p>{t("Nothing has changed since the last save. Save anyway?")}</p>}
        confirmLabel={t("Save anyway")}
        pending={saving}
        onConfirm={onUnchangedSaveConfirm}
        onCancel={onUnchangedSaveCancel}
      />
      <ConfirmDialog
        open={confirmingDelete}
        agentHandle="page-delete-confirm"
        title={t("Move to trash?")}
        body={<p>{t("Move")} &quot;{title}&quot; {t("to trash? It will disappear from the site and from this list.")}</p>}
        confirmLabel={t("Move to trash")}
        destructive
        pending={deleting}
        onConfirm={remove}
        onCancel={() => setConfirmingDelete(false)}
      />
      {/* See `PageEditorTemplateModalGate`'s own doc for why this is conditionally mounted rather
          than always-mounted-with-`open`. */}
      <PageEditorTemplateModalGate
        show={showTemplateModal}
        templateChoice={templateChoice}
        activeThemeId={activeThemeId}
        activeThemeTier={activeThemeTier}
        activeThemeApiVersion={activeThemeApiVersion}
        onClose={onCloseTemplateModal}
        confirmLeave={confirmLeave}
        t={t}
      />
    </div>
  );
}

/**
 * The editor's main pane — one of four surfaces, chosen by {@link pageEditorSurface}.
 *
 * Extracted from `PageEditor` in the 2026-09-06 complexity-ceiling pass. This was a chain of nested
 * ternaries inline in that component's JSX, worth 6 of its 10 cognitive-complexity points against a
 * ceiling of 9 (plus two `sonarjs/no-nested-conditional` warnings). The DECISION did not move here —
 * it moved to `rules.ts`, where it is pure and directly testable, per this feature's own "everything
 * that computes a value rather than rendering one" rule; what is left below is markup dispatch and
 * nothing else, one early return per surface, scored in its own scope.
 *
 * The Interactive tab remounts with fresh `html` on every tab switch — see `InteractiveHtmlEditor`'s
 * own file header for why it reads `html` once at mount rather than reacting to later prop changes.
 * `canvasStyling` is read once at mount for that same reason, which is why `interactive-pending` is
 * its own surface rather than a skipped loading flash: mounting an unstyled canvas could never pick
 * the theme up afterwards. The wait is normally invisible — `preview` is this screen's default tab,
 * so the theme's token files have already loaded by the time anyone clicks Interactive.
 *
 * `embedPlaceholderDescriber` (Bug A / interactive-bugs plan Slice A3) is the same mount-once
 * contract: `usePageEditor` rebuilds it whenever the bound translator changes, but
 * `InteractiveHtmlEditor` only reads `describeEmbedPlaceholder` at construction, so a later identity
 * change (a locale switch mid-session) takes effect on the NEXT Interactive-tab mount, not live.
 *
 * `interactiveEditorRef` (Interactive flush, 2026-09-23 plan) is attached to `<InteractiveHtmlEditor>`
 * below so `usePageEditor`'s `flushInteractiveEdits` can close an open RTE session and sync its edit
 * before a save, publish, tab switch, or template change — see `PageEditorController
 * .interactiveEditorRef`'s own doc.
 */
function PageEditorPane({
  view,
  canvasStyling,
  html,
  setHtml,
  draftHtml,
  setDraftHtml,
  htmlTextareaRef,
  onHtmlScroll,
  onPreviewFrameLoad,
  device,
  slug,
  version,
  contentRevision,
  status,
  dirty,
  contentDirty,
  templatePreviewUrl,
  previewFormRef,
  previewFormTarget,
  frameRef,
  paneWidth,
  previewExpanded,
  onTogglePreviewExpanded,
  t,
  embedPlaceholderDescriber,
  onRequestEditHtml,
  onInteractiveSourceError,
  interactiveEditorRef,
  setHtmlFromCanvas,
}: {
  view: PageEditorView;
  canvasStyling: ThemeCanvasStylingState;
  html: string;
  setHtml: (value: string) => void;
  draftHtml: string;
  setDraftHtml: (value: string) => void;
  /** Per-tab scroll memory — see `PageEditorController.htmlTextareaRef`'s own doc. */
  htmlTextareaRef: (node: HTMLTextAreaElement | null) => void;
  onHtmlScroll: (scrollTop: number) => void;
  /** Per-tab scroll memory, Preview half — see `PageEditorController.onPreviewFrameLoad`'s own doc.
   *  Threaded straight through to `PagePreview` below; this dispatcher does not call it itself. */
  onPreviewFrameLoad: (iframe: HTMLIFrameElement) => void;
  device: DevicePreviewDevice;
  slug: string;
  /** The loaded row's current version — see `PagePreviewFrame`'s own doc for why the live-site src
   *  is cache-busted with it. */
  version: number;
  /** Content refresh (2026-09-16) — `usePageEditor`'s `contentRevision`, keyed onto the Interactive
   *  surface below so an assistant write the operator loads (Load latest, while on this tab) remounts
   *  GrapesJS with the new body, the same way switching tabs already does. */
  contentRevision: number;
  status: "draft" | "published";
  dirty: boolean;
  contentDirty: boolean;
  templatePreviewUrl: string;
  previewFormRef: (node: HTMLFormElement | null) => void;
  previewFormTarget: string;
  frameRef: (node: HTMLDivElement | null) => void;
  paneWidth: number;
  /** Preview fullscreen (2026-09-16) — `usePageEditor`'s `previewExpanded` / `togglePreviewExpanded`.
   *  Only the `preview` surface below reads them: the fab is part of the preview, not of this
   *  dispatcher, so switching to HTML/Interactive takes it out of the DOM entirely (and the hook's
   *  own effect collapses the state at the same time). */
  previewExpanded: boolean;
  onTogglePreviewExpanded: () => void;
  t: Translate;
  /** Bug A / interactive-bugs plan Slice A3 — see `PageEditorController.embedPlaceholderDescriber`'s
   *  own doc. Passed straight through to the `interactive` surface below. */
  embedPlaceholderDescriber: (el: Element) => CanvasEmbedPlaceholderDescriptor | undefined;
  onRequestEditHtml?: RequestEditHtml;
  onInteractiveSourceError?: (error: Error) => void;
  /** Interactive flush (2026-09-23 plan) — see `PageEditorController.interactiveEditorRef`'s own
   *  doc. Attached to the `interactive` surface's `<InteractiveHtmlEditor>` below. */
  interactiveEditorRef: RefObject<InteractiveHtmlEditorHandle | null>;
  /** See `PageEditorController.setHtmlFromCanvas`. The `interactive` surface's `onChange`. */
  setHtmlFromCanvas: (value: string) => void;
}) {
  const surface = pageEditorSurface(view, canvasStyling);
  // Bug B, Slice B3 (dev-only instrumentation, pages-redo plan): logs which surface this pane renders,
  // keyed on `surface.kind` alone — not the whole `surface` object, which carries a fresh `styling`
  // reference every render — so this fires once per actual surface change, not once per render (this
  // component also re-renders on every `draftHtml` keystroke while `view === "html"`). Removed once
  // Bug B is closed; not covered by a test for that reason (logging only, no behavior to assert).
  useEffect(() => {
    if (import.meta.env.DEV) {
      console.debug("[page-editor] interactive", { phase: `surface:${surface.kind}`, ms: Math.round(performance.now()) });
    }
  }, [surface.kind]);
  if (surface.kind === "preview") {
    return (
      <PagePreview
        html={html}
        width={DEVICE_PREVIEW_WIDTHS[device]}
        slug={slug}
        version={version}
        status={status}
        dirty={dirty}
        contentDirty={contentDirty}
        templatePreviewUrl={templatePreviewUrl}
        previewFormRef={previewFormRef}
        previewFormTarget={previewFormTarget}
        frameRef={frameRef}
        paneWidth={paneWidth}
        expanded={previewExpanded}
        onToggleExpanded={onTogglePreviewExpanded}
        onFrameLoad={onPreviewFrameLoad}
        t={t}
      />
    );
  }
  if (surface.kind === "html") {
    return (
      <textarea
        ref={htmlTextareaRef}
        className="page-html-source"
        value={draftHtml}
        onChange={(e) => {
          // Raw pass-through, same as before this tab had any formatting — an edit made on top of
          // the pretty-printed baseline becomes the new working copy verbatim, not reformatted
          // again mid-keystroke (which would fight the operator's cursor position).
          setDraftHtml(e.target.value);
          setHtml(e.target.value);
        }}
        onScroll={(e) => onHtmlScroll(e.currentTarget.scrollTop)}
        spellCheck={false}
        aria-label={t("Page HTML")}
        placeholder={t("This page has no HTML yet. Ask the assistant to build it, or write some here.")}
        {...agentHandle({ handle: "page-html-source" }, { role: "field", label: "This page's raw HTML source" })}
      />
    );
  }
  if (surface.kind === "interactive-pending") {
    return <div className="notice">{t("Loading the theme's styles…")}</div>;
  }
  return (
    <InteractiveHtmlEditor
      key={contentRevision}
      ref={interactiveEditorRef}
      html={html}
      onChange={setHtmlFromCanvas}
      canvasStyling={surface.styling}
      isProtectedElement={isProtectedEmbedElement}
      describeEmbedPlaceholder={embedPlaceholderDescriber}
      onRequestEditHtml={onRequestEditHtml}
      onSerializationError={onInteractiveSourceError}
      translate={t}
    />
  );
}

/**
 * Renders the page at a fixed viewport width and scales the whole thing down to fit the pane.
 *
 * The scale is a CSS transform on a fixed-width box, not a responsive iframe, and that difference is
 * the entire point — see `DEVICE_PREVIEW_WIDTHS`. The wrapper's height is scaled to match so the
 * transformed content does not leave a gap or overflow underneath it. Both branches below fill this
 * same scaled box identically (`.page-preview-iframe` sets `width/height: 100%` on either element),
 * so `3ac885e`'s live pane-width tracking and the toolbar-to-preview spacing are unaffected by which
 * branch renders.
 *
 * **What this shows, and why (2026-08-11 — the theme-CSS gap was diagnosed, not assumed a
 * regression)**: this component previously fed the page's raw stored body HTML into
 * `SrcDocSandbox` — a sandboxed `srcdoc` iframe with no template wrapper, no nav/footer, and no
 * theme stylesheet, regardless of the page's template choice. That was never wired to the real
 * render path; it cannot have regressed, because it never rendered themed. Rather than reimplement
 * that whole server-side render pipeline a second time in the admin (a second source of truth that
 * would drift from `src/server/routes/site/pages.ts`'s real one), it shares the real pipeline
 * instead of one, through two branches:
 *
 * 1. **Saved content** (`status === "published" && !dirty`): GETs the authenticated template-preview
 *    endpoint. Consent is excluded there because this opaque-origin sandbox cannot save a choice.
 * 2. **Template preview** (everything else — a draft, or a published page with a pending
 *    `templateChoice` and/or edited content): a hidden `<form method="post" target="{iframe name}">`
 *    POSTs the working-copy `html` into `templatePreviewUrl` (`usePageEditor`'s pre-built URL,
 *    `port.templatePreviewUrl`/`lib/api.ts`'s own `templatePreviewUrl` — the admin-only render
 *    through the SAME pipeline as branch 1: `renderViaTemplate`,
 *    `routes/admin/posts/template-preview.ts`, looked up by id instead of by public slug), landing
 *    the response inside a same-named `<iframe>`. `POST`, not the plain `GET` `<iframe src>` this
 *    branch used before 2026-09-09, because a `GET` can only carry `templateChoice` on the query
 *    string — it cannot hand the endpoint this page's own PENDING, possibly-unsaved `html`, which is
 *    exactly what a draft (or a published-but-dirty page) needs previewed. The debounced auto-submit
 *    effect (`usePageEditor`'s `schedulePendingHtmlPreviewSubmit`) fires this on template-choice
 *    change, body change, and switching into this tab — see that function's own doc for the "why a
 *    form submit, not `fetch`" reasoning, which mirrors `use-post-editor.hooks.ts`'s identical
 *    mechanism for Posts almost exactly (a `bodyHtml` field here where that one sends `bodyJson`).
 *
 *    Once a genuine per-id `bodyHtml` override existed server-side (`template-preview.ts`'s
 *    `pendingBodyHtml`, 2026-09-09 — see that file's own header), this branch no longer needs
 *    `status === "published"`: `findPublishedPostById`'s visibility guard on a draft's own
 *    `{"type":"content"}` slot is bypassed for exactly the one id this authenticated caller already
 *    fetched and authorized, the same way the PRE-EXISTING `bodyJson` override already did for a
 *    Post — see `resolveHtmlFormatContentMarkers`'s own doc for the full reasoning. That is what
 *    retired the THIRD branch this function used to have (a raw `SrcDocSandbox` fallback for a
 *    draft, or a published-and-dirty page): branch 2 is now simply "not the live site", so the two
 *    branches are exhaustive by construction and the fallback had become dead code, not merely rare
 *    — removed rather than left unreachable. This is also why only `canShowLiveSite` is computed
 *    below: its negation needs no name of its own. (`draftHtml`'s own textarea
 *    still exists on the HTML tab for hand-editing raw markup; nothing about that tab changed here.)
 *
 * Both branches use the existing authenticated API route (and its dev proxy), so the parent can
 * navigate the iframe with its session. The document itself remains sandboxed in an opaque origin;
 * it cannot read the admin document or save consent. A real URL preserves theme asset resolution.
 *
 * Preview fullscreen (2026-09-16). Expanding widens the PANE, never the previewed page: the
 * Desktop/Tablet/Mobile choice (`DEVICE_PREVIEW_WIDTHS`, the `page-preview-width-*` buttons) is the
 * operator's statement about which viewport they are inspecting, so it is carried into the expanded
 * panel unchanged rather than overridden to Desktop. Overriding would silently discard a selection
 * they just made and would make the single most useful thing this control can do — look at the
 * mobile layout properly — impossible. It also pays off arithmetically: `scale` is
 * `min(1, paneWidth / width)`, so a 390px Mobile preview that a narrow pane was scaling DOWN
 * renders at a true 1:1 once the pane is wide enough, and Desktop on a narrow pane keeps the
 * scaled-down behavior it already had. `pages.css`'s `.page-preview-expanded .page-preview-scaler`
 * centres it; see that rule for why `auto` margins are the right tool for both regimes.
 */
function PagePreview({
  html,
  width,
  slug,
  version,
  status,
  dirty,
  contentDirty,
  templatePreviewUrl,
  previewFormRef,
  previewFormTarget,
  frameRef,
  paneWidth,
  expanded,
  onToggleExpanded,
  onFrameLoad,
  t,
}: {
  html: string;
  width: number;
  slug: string;
  /** Cache-busts the live-site branch's `src` — see `PagePreviewFrame`'s own doc. */
  version: number;
  status: "draft" | "published";
  dirty: boolean;
  contentDirty: boolean;
  /** Pre-built by `usePageEditor` — see this function's own doc, branch 2. */
  templatePreviewUrl: string;
  /** Owned by `usePageEditor` — see `PageEditorController.previewFormRef`'s own doc for why the
   *  debounced auto-submit effect that reaches through this ref lives there, not here. */
  previewFormRef: (node: HTMLFormElement | null) => void;
  /** The hidden form's `target` and the iframe's `name` it submits into — must match at submit time. */
  previewFormTarget: string;
  /** Frame element to measure and its live-measured width — both owned by `usePageEditor`
   *  (`hooks/use-page-editor.hooks.ts`), not local state, so they survive this component's own
   *  mount/unmount as the operator switches tabs. `frameRef` is a CALLBACK ref, not a `RefObject` —
   *  see that hook's own comment on why the measuring effect there is keyed on the frame node itself
   *  rather than `view` or an empty dependency array. */
  frameRef: (node: HTMLDivElement | null) => void;
  paneWidth: number;
  /** Preview fullscreen (2026-09-16) — see `PageEditorController.previewExpanded`'s own doc for the
   *  state's lifetime, and this component's own doc for what expanding does and does NOT change. */
  expanded: boolean;
  /** `usePageEditor`'s `togglePreviewExpanded`, bound to the single `.page-preview-fab` this
   *  component renders in BOTH states. Nothing in `PageEditor`'s toolbar toggles it. */
  onToggleExpanded: () => void;
  /** Per-tab scroll memory — see `PageEditorController.onPreviewFrameLoad`'s own doc. Wired to both
   *  `PagePreviewFrame` branches' `<iframe onLoad>` below. */
  onFrameLoad: (iframe: HTMLIFrameElement) => void;
  t: Translate;
}) {
  const canShowLiveSite = status === "published" && !dirty;

  // ONE element tree in both states, only the outer class changes (2026-10-05 owner bug). The two
  // states used to return different trees, so every toggle unmounted the form + iframe pair and
  // mounted an empty `about:blank` one: a draft's preview went blank (fixed at the root by
  // `usePageEditor`'s node-keyed re-submit) and even a working toggle reloaded the page under the
  // operator. Keeping the same nodes keeps the rendered document, and its scroll, across the toggle.
  //
  // Expanded: `.page-preview-expanded` (`styles/pages.css`) is `position: absolute; inset: 0`
  // against `.admin-main-col` — see `styles/editor.css`'s `.post-preview-expanded` comment for the
  // full containment argument (why this covers only the admin content column, never
  // `.admin-chat-dock`); Pages reuses the geometry and the `z-index`, not the rule.
  //
  // `.page-preview-stage` wraps the frame and the control and is the `position: relative` box the
  // fab's `position: absolute` resolves against (`pages.css`), so the fab always sits INSIDE the
  // previewed area — never over the notice line above it, which is where it landed when the whole
  // surface (notice included) was its containing block.
  return (
    <div className={expanded ? "page-preview-expanded" : "page-preview-host"}>
      <div className="page-preview-surface">
        <p className="field-hint editor-preview-note">{t("Cookie banner hidden in preview. Embedded videos may not play here; open the page to check.")}</p>
        <div className="page-preview-stage">
          {/* Collapsed vs. expanded frame/scaler heights: see `devicePreviewFrameStyles`. */}
          <DevicePreviewFrame width={width} frameRef={frameRef} paneWidth={paneWidth} expanded={expanded}>
            <PagePreviewFrame
              canShowLiveSite={canShowLiveSite}
              slug={slug}
              version={version}
              html={html}
              templatePreviewUrl={templatePreviewUrl}
              previewFormRef={previewFormRef}
              previewFormTarget={previewFormTarget}
              onFrameLoad={onFrameLoad}
              t={t}
            />
          </DevicePreviewFrame>
          <PagePreviewFab expanded={expanded} onToggle={onToggleExpanded} t={t} />
        </div>
      </div>
    </div>
  );
}

/**
 * The one control that toggles the preview between its normal pane and the full-screen panel,
 * rendered in the SAME place in both states so the way out is always visible on screen — the
 * failure that killed an earlier overlay attempt was an operator who could not see how to get back.
 * A top-level component rather than inline JSX so its three state ternaries score in their own
 * scope, the same reason `PagePreviewFrame` below is one.
 *
 * The glyph is `aria-hidden`, so `aria-label` is the ONLY thing naming this button for a screen
 * reader; keep the two directions' names distinct. `data-agent-label` is a SEPARATE string and is
 * NOT an accessible description — `agentHandle` emits only `data-agent-element/-role/-label/-page`
 * (`handle.ts`), never `aria-label`/`aria-describedby`, so widening it carries no a11y consequence
 * and nobody should "fix" a11y by editing it.
 */
function PagePreviewFab({ expanded, onToggle, t }: { expanded: boolean; onToggle: () => void; t: Translate }) {
  return (
    <button
      type="button"
      className="page-preview-fab"
      onClick={onToggle}
      aria-label={expanded ? t("Exit full screen") : t("Show full screen")}
      {...agentHandle({ handle: "page-preview-expand" }, {
        role: "button",
        // These labels read redundantly ON PURPOSE. `page.find_elements`'s `query` is a plain
        // case-insensitive SUBSTRING match over handle and label only — no stemming, no synonyms,
        // no ranking, and `role` is not searched at all (`@jini-ai/agentic`'s `dom-page-driver.ts`,
        // `findElements`) — so a word that is not literally here retrieves NOTHING, and an
        // assistant that gets an empty list abandons the route rather than broadening its query.
        // That is not hypothetical: the Posts twin's label once read "Show the preview big, filling
        // the admin content area" while the button said "Show full screen", and on a recorded demo
        // an assistant asked to show the preview full screen called
        // `page.find_elements({query:"full"})`, got `{"elements":[]}`, and gave up.
        //
        // The durable rule that came out of that, and which both editors now follow: every word of
        // the button's own `aria-label` must appear in the label published to agents, and both
        // spellings — "full screen" and "fullscreen" — must be present, since they are different
        // substrings. Both directions also carry the OPPOSITE direction's vocabulary: a model that
        // asks for "fullscreen" while it is ALREADY full screen must find this control and read
        // "Exit full screen" off it, which tells it the state. Returning nothing instead teaches it
        // the feature does not exist. Direction is communicated by what the label SAYS, never by
        // being absent from the index. Prose, not a keyword dump — every synonym is worked into a
        // real sentence a person can read. Kept under `normalizeAgentLabel`'s 200-character
        // truncation (`handle.ts`), past which text is still matchable but invisible in a listing;
        // the agent-drive test pins both the vocabulary and that length.
        label: expanded
          ? "Exit full screen: exit fullscreen to collapse or close the expanded preview, putting it back to its normal, smaller size. Already maximized, so if the ask was to show it big, it already is."
          : "Show the preview full screen: fullscreen this page preview to maximize or expand it and show it big across the admin content area, at the Desktop, Tablet or Mobile width already chosen.",
      })}
    >
      <span aria-hidden="true">{expanded ? "\u2921" : "\u2922"}</span>
      {/* The hint is drawn in-page, not the native `title` tooltip (2026-10-05): the desktop app
          drew the native one past the window's right edge ("Exit f…"). Anchored to the button and
          opening leftwards (`pages.css`), it stays inside the preview. `aria-hidden` because
          `aria-label` above already names the button; this only repeats it visually. */}
      <span className="page-preview-fab-tip" aria-hidden="true">
        {expanded ? t("Exit full screen (Esc)") : t("Show full screen")}
      </span>
    </button>
  );
}

/**
 * The two-way surface choice from `PagePreview`'s own doc comment (live site / template preview), as
 * a top-level function so its branching scores independently of `PagePreview`'s own complexity — same
 * pattern `PageEditorToolbarEnd` above uses for `PageEditor`'s own render branches.
 */
function PagePreviewFrame({
  canShowLiveSite,
  slug,
  version,
  html,
  templatePreviewUrl,
  previewFormRef,
  previewFormTarget,
  onFrameLoad,
  t,
}: {
  canShowLiveSite: boolean;
  slug: string;
  /** Remount the no-store authenticated GET after an assistant saves a new version. */
  version: number;
  html: string;
  /** Pre-built by `usePageEditor` — see `PagePreview`'s own doc, branch 2. */
  templatePreviewUrl: string;
  previewFormRef: (node: HTMLFormElement | null) => void;
  previewFormTarget: string;
  /** Per-tab scroll memory — see `PageEditorController.onPreviewFrameLoad`'s own doc. Wired to both
   *  branches' `onLoad` below: cross-origin (the live-site branch) it silently does nothing. */
  onFrameLoad: (iframe: HTMLIFrameElement) => void;
  t: Translate;
}) {
  const fresh = useThemePreviewFrame({
    // Opaque-origin previews cannot save consent; the authenticated route already excludes its gate.
    liveUrl: templatePreviewUrl,
    templateUrl: templatePreviewUrl,
    canShowLiveSite,
  }, { navigation: "entry" });
  if (fresh.canShowLiveSite) {
    return (
      <iframe
        key={`${fresh.liveUrl}-${slug}-${version}`}
        src={fresh.liveUrl}
        title={t("Page preview")}
        className="page-preview-iframe"
        sandbox={PAGE_PREVIEW_IFRAME_SANDBOX}
        referrerPolicy="no-referrer"
        onLoad={(e) => onFrameLoad(e.currentTarget)}
      />
    );
  }
  return (
    <>
      {/* `hidden`, not left out of the DOM — a hidden form still submits fine, and this keeps it
          out of layout without relying on CSS. Posts to the same `templatePreviewUrl` a plain `GET`
          used to point this iframe's `src` at directly — `templateChoice` rides that URL's own query
          string exactly as it did there, so a pending template choice AND a pending body are both
          honored by one submit. Mirrors `PostEditor.tsx`'s identical `PostPreviewFrame` branch 3
          almost exactly (a `bodyHtml` field here where that one sends `bodyJson`). */}
      <form key={`form-${fresh.templateUrl}`} ref={previewFormRef} method="post" target={previewFormTarget} action={fresh.templateUrl} hidden>
        <input type="hidden" name="bodyHtml" value={html} />
      </form>
      <iframe
        key={fresh.templateUrl}
        name={previewFormTarget}
        title={t("Page preview")}
        className="page-preview-iframe"
        sandbox={PAGE_PREVIEW_IFRAME_SANDBOX}
        referrerPolicy="no-referrer"
        onLoad={(e) => onFrameLoad(e.currentTarget)}
      />
    </>
  );
}

import type { ReactNode } from "react";
import { agentHandle } from "@jini-ai/agentic";

import { adminHref, navigate } from "../../lib/router";
import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  themePageCollisionAdminPath,
  themePagePublishSummary,
  type ThemePageRow,
  type ThemePageSlugCollision,
} from "./hooks/use-theme-pages.hooks";
import { themePageCollisionMessage, themePagePublishState } from "./lib/theme-page-publish-state";
import { useThemePageDetailsModal } from "./ThemePageDetailsModal.hooks";

/**
 * @file The Theme Pages tab's "Details" info modal — 2026-08-31 owner review pass, replacing the
 * row's old inline "see more" disclosure (`Pages.tsx`'s own header covers that history). Owner:
 * *"that brings up a modal, like an info modal. And that info modal tells you whatever you need to
 * know."* Everything the old inline panel showed (file path, whether there is an original to reset
 * to) still lives here, plus two facts that panel never had room for: the row's own publish state/
 * reason (previously only on the switch itself) and any live content record already claiming this
 * page's slug (`row.collidingContent` — the same fact Theme Studio's Explore screen reflects in the
 * Publish toggle's inline hint; its separate warning card was removed 2026-10-10, owner ask).
 *
 * Same native-`<dialog>` foundation as `@jini-ai/admin/react`'s `ConfirmDialog` (already used by
 * this same screen, `Pages.tsx`'s delete confirmation) — `aria-labelledby` pointing at a visible
 * `<h2>`, rather than `MessageOverflowModal.tsx`'s `aria-label`-only shape: this dialog's title IS
 * the whole page id, worth showing rather than hiding behind an attribute a sighted user never
 * sees. `MessageOverflowModal.tsx` is still the closer precedent for WHY a generic per-row detail
 * modal exists at all (an "I can't show this well inline, so show it in a modal" affordance) — read
 * for that shape, not copied: it is scoped to arbitrary full-size chat content with its own
 * lifecycle hook, and this dialog's content has no side effects of its own, so `ThemePagesTab.tsx`
 * keeps exactly ONE instance of this component always mounted (never one per row — see this file's
 * own hook for why that also means no double-mount risk), toggling only `open`/`row` as the
 * selection changes, the same "controlled, never conditionally unmounted" shape `ConfirmDialog`
 * itself uses.
 *
 * **PART 2 — an Edit action (2026-08-31, owed-work pass; SUPERSEDED by PART 4 below, same day).**
 * This modal briefly offered its own `t("Edit")` button, pointed at the same Theme Studio
 * destination as `ThemePagesTab.tsx`'s own Theme Studio column. The owner then asked for that action
 * to live in the row's `RowMenu` instead, directly under `Details` — see PART 4. Left as history here
 * rather than deleted outright since it explains why `Close` alone can look like an odd choice for a
 * footer without the surrounding context.
 *
 * **PART 3 — visual pass (2026-08-31, same-day follow-up).** Owner: *"looks awful"* — a flat white
 * box with no hierarchy: the page id rendered as a small lowercase word, `File`/`Publish` were
 * undifferentiated `label: value` sentences, two paragraphs of explanatory prose read like
 * documentation, and the collision warning's own "Open {title}" link had no button affordance at
 * all against its amber background. Restructured into named blocks below (kept small enough to stay
 * flat, per this file's own complexity ceiling):
 * - {@link ThemePageDetailsHeader} — a kicker (`t("Page")`) over the id, the same eyebrow/title
 *   pairing `.page-kicker`/`.page-title` already use for "CONTENT" → "Pages" at the screen level
 *   (`styles.css`), just re-declared under this dialog's own class names rather than reusing those
 *   two directly — they are deliberately scoped to `.page-header` (see that rule's own comment on
 *   why), which this dialog is not.
 * - {@link ThemePageDetailsFacts} — `File`/`Publish` as an actual label/value grid (`<dl>`) instead
 *   of two sentences, reusing the exact `t("File")`/`t("Publish")` strings that already existed.
 * - {@link ThemePageDetailsNotes} — the two explanatory asides, grouped and kept at their existing
 *   quiet `.theme-page-details-muted` treatment rather than reading as body prose.
 * - {@link ThemePageDetailsCollisionWarning} — unchanged copy and unchanged trigger condition
 *   (`row.collidingContent` alone, still not gated on publish state — see this component's own
 *   comment for why that gate would hide the exact case this warning exists for), but the action is
 *   now `.btn-warning` — an existing primitive, not a new one — instead of a bare `<a>`, and a small
 *   `aria-hidden` triangle marks the block as a warning before its text is read.
 *
 * No copy changed anywhere in this pass, so `pages-i18n.ts` needed no new keys — every string above
 * is one already covered across all 21 locales.
 *
 * **PART 4 — Edit moved to the row's `RowMenu` (2026-08-31, same-day follow-up to PART 2).** Owner:
 * put `Edit` in the three-dot menu, directly under `Details`, not as a button inside the dialog. The
 * action itself (same Theme Studio destination, same `themeStudioHref`) now lives in
 * `themePageRowMenuItems` (`rules.ts`) and `ThemePagesTab.tsx`'s own `onEdit` handler — see those
 * files' own comments. This modal's footer is `Close` only again; `themeId` is gone from
 * {@link ThemePageDetailsModalProps} entirely rather than kept as a now-dead required prop, since a
 * repo-wide check turned up exactly one caller (`ThemePagesTab.tsx`) and no other reader.
 */

/** Stable id for the dialog's own accessible name — a static constant, not a generated one, since
 *  exactly one instance of this component is ever mounted at a time (see this file's own header). */
const TITLE_ID = "theme-page-details-title";

/**
 * The dialog's opening block — a small-caps `t("Page")` kicker over the page id itself, styled as
 * the actual heading it is (see this file's own header, PART 3) instead of inheriting body-text
 * size. Its own component purely so {@link ThemePageDetailsModal} stays a flat list of blocks.
 *
 * @complexity O(1).
 */
function ThemePageDetailsHeader({ pageId, t }: { pageId: string; t: Translate }): ReactNode {
  return (
    <div className="theme-page-details-header">
      <p className="theme-page-details-kicker">{t("Page")}</p>
      <h2 id={TITLE_ID}>{pageId}</h2>
    </div>
  );
}

/**
 * `File`/`Publish` as a real label/value grid (a `<dl>`, one `dt`/`dd` pair per fact) rather than
 * the two `"Label: value"` sentences this replaced — the two most scannable facts on the screen,
 * so they get their own row instead of blending into paragraph text (this file's own header, PART
 * 3). Same `t("File")`/`t("Publish")` strings as before; only the layout changed.
 *
 * @complexity O(1).
 */
function ThemePageDetailsFacts({ row, t }: { row: ThemePageRow; t: Translate }): ReactNode {
  return (
    <dl className="theme-page-details-facts">
      <div className="theme-page-details-fact">
        <dt>{t("File")}</dt>
        <dd>
          <code>{row.filePath}</code>
        </dd>
      </div>
      <div className="theme-page-details-fact">
        <dt>{t("Publish")}</dt>
        <dd>{themePagePublishSummary(row, t)}</dd>
      </div>
    </dl>
  );
}

/**
 * The toggle explainer and "no original to reset to" note — unchanged copy, grouped into one quiet
 * block instead of two full-weight paragraphs sitting in the middle of the dialog like documentation
 * (this file's own header, PART 3). Returns `null` when neither applies, so
 * {@link ThemePageDetailsModal} never renders an empty wrapper.
 *
 * @complexity O(1).
 */
function ThemePageDetailsNotes({ row, t }: { row: ThemePageRow; t: Translate }): ReactNode {
  const showsToggleHint = themePagePublishState(row, t).kind === "toggle";
  const showsNoOriginalHint = !row.resettable;
  if (!showsToggleHint && !showsNoOriginalHint) return null;
  return (
    <div className="theme-page-details-notes">
      {showsToggleHint ? (
        <p className="theme-page-details-muted">
          {t(
            "Whether this page has its own live URL on your site. Theme pages start off, because a theme ships generic placeholder content rather than yours. Turn one on once you've made it your own."
          )}
        </p>
      ) : null}
      {showsNoOriginalHint ? (
        <p className="theme-page-details-muted">
          {t("Added to this theme after it was installed — there is no original to reset to.")}
        </p>
      ) : null}
    </div>
  );
}

/**
 * Purely decorative (`aria-hidden`) triangle marking the collision block as a warning before its
 * text is read — the block's own `.notice.warning` background/border already carry the same signal
 * for a screen reader via nothing (color alone), so this is a sighted-only reinforcement same as
 * {@link ThemePageLockGlyph} in `ThemePagesTab.tsx` is for the lock icon, not a second source of
 * truth. Same hand-rolled `viewBox="0 0 24 24"`/`stroke="currentColor"`/`strokeWidth={2}` idiom that
 * icon uses, so both read as one icon language rather than two.
 *
 * @complexity O(1).
 */
function ThemePageCollisionIcon(): ReactNode {
  return (
    <svg
      className="theme-page-details-collision-icon"
      viewBox="0 0 24 24"
      width={16}
      height={16}
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      aria-hidden="true"
    >
      <path d="M10.29 3.86 1.82 18a1 1 0 0 0 .86 1.5h18.64a1 1 0 0 0 .86-1.5L13.71 3.86a1 1 0 0 0-1.72 0Z" />
      <path d="M12 9v4" />
      <path d="M12 17h.01" />
    </svg>
  );
}

/**
 * The slug-collision warning — same copy and same trigger (`row.collidingContent` alone) as before
 * this pass; only the presentation changed (this file's own header, PART 3). Deliberately NOT gated
 * on `row.published` too: a page can be off and still lose the URL race depending on the colliding
 * record's own override, so hiding this behind a publish check would hide exactly the case that
 * caused the original owner confusion this modal exists to prevent (Theme Studio's Explore screen
 * had a warning card gated the same way for the same reason, until it was removed 2026-10-10).
 *
 * The action was a bare `<a>` with no button styling — the thing that read as a "broken text input"
 * in the owner's report. It is now `.btn-warning`, an existing primitive already used elsewhere for
 * this exact severity (`styles.css`), not a new class invented for this one dialog.
 *
 * @complexity O(1).
 */
function ThemePageDetailsCollisionWarning({
  collision,
  t,
}: {
  collision: ThemePageSlugCollision;
  t: Translate;
}): ReactNode {
  const adminPath = themePageCollisionAdminPath(collision);
  return (
    <div className="notice warning theme-page-details-collision">
      <div className="theme-page-details-collision-body">
        <ThemePageCollisionIcon />
        <p>{themePageCollisionMessage(collision, t)}</p>
      </div>
      <a
        className="btn-warning"
        href={adminHref(adminPath)}
        onClick={(e) => {
          e.preventDefault();
          navigate(adminPath);
        }}
        {...agentHandle({ handle: "theme-page-details-collision-open" }, { role: "link", label: "Open the colliding content record" })}
      >
        {t("Open {title}").replace("{title}", collision.title)}
      </a>
    </div>
  );
}

export interface ThemePageDetailsModalProps {
  /** The row this modal describes, or `null` while closed — `ThemePagesTab.tsx` clears this back to
   *  `null` on close rather than leaving the last-viewed row's data live underneath a closed dialog. */
  row: ThemePageRow | null;
  onClose: () => void;
  t: Translate;
  /** Injectable seam for the dialog's open/close lifecycle. Defaults to the real
   *  {@link useThemePageDetailsModal}; a test can pass a fake here to exercise this component's
   *  rendering without driving the real `<dialog>` lifecycle. */
  useModal?: typeof useThemePageDetailsModal;
}

export function ThemePageDetailsModal({ row, onClose, t, useModal = useThemePageDetailsModal }: ThemePageDetailsModalProps) {
  const { dialogRef, handleNativeCancel, handleBackdropClick } = useModal(row !== null, onClose);

  return (
    <dialog
      ref={dialogRef}
      className="theme-page-details-dialog"
      aria-labelledby={TITLE_ID}
      onCancel={handleNativeCancel}
      onClick={handleBackdropClick}
      {...agentHandle({ handle: "theme-page-details-dialog" }, {
        role: "region",
        label: "This theme page's details — file path, publish state, and any colliding content record",
      })}
    >
      {row ? (
        <>
          <ThemePageDetailsHeader pageId={row.pageId} t={t} />
          <ThemePageDetailsFacts row={row} t={t} />
          <ThemePageDetailsNotes row={row} t={t} />
          {row.collidingContent ? <ThemePageDetailsCollisionWarning collision={row.collidingContent} t={t} /> : null}
        </>
      ) : null}
      <div className="theme-page-details-actions">
        <button
          type="button"
          className="btn-secondary"
          onClick={onClose}
          {...agentHandle({ handle: "theme-page-details-close" }, { role: "button", label: "Close this details dialog" })}
        >
          {t("Close")}
        </button>
      </div>
    </dialog>
  );
}

import { agentHandle } from "@jini-ai/agentic";

import { useAgentPluginDisableConfirm } from "./hooks/use-agent-plugin-disable-confirm.hooks";
import type { Translate } from "@jini-ai/ui/panel-kit";

/**
 * @file Confirmation gate in front of the SAME underlying operation from two different controls.
 * There is no admin uninstall route — the only two agent-plugins routes are `GET .../agent-plugins`
 * (list) and `PATCH .../agent-plugins/:pluginId` (set-enabled); `uninstallAgentPlugin()`
 * (`features/agent-plugins/uninstall.ts`) is reachable only from an assistant tool and refuses every
 * bundled package outright — see `AgentPluginRow`'s own header for why its trash icon is honestly
 * disabled for that reason. So "remove this plugin", mechanically, is what turning it off already
 * does: `resolveAgentPluginRefs()` refuses to pin a disabled plugin into a run, which is the only
 * lever an operator actually has over a bundled package. This dialog exists because that lever has a
 * real cost (the assistant loses those skills on its very next run) and, before it landed, a single
 * click fired that cost with no way to reconsider.
 *
 * Two `variant`s, same mechanism, added when Downloaded's row lost its Enable/Disable switch in
 * favor of a single Remove/Enable action (2026-09-09 — see `AgentPlugins.tsx`'s own header):
 *   - `"disable"` — Installed's switch. Confirm reads "Disable", matching the verb the switch itself
 *     already shows via the row's "Enabled"/"Disabled" word — the owner's explicit call against
 *     renaming that control to "Add to site / Remove from site".
 *   - `"remove"` — Downloaded's action button. Confirm reads "Remove" to match that button's own
 *     label; the body still discloses, honestly, that this can't delete anything the backend can't
 *     already refuse to delete — see `buildAgentPluginDisableConfirmCopy`'s own header.
 *
 * Enabling stays a plain one-click action in both places — see `AgentPlugins.tsx`'s own
 * `onRequestToggleEnabled`/`onRequestRemove` — because turning a plugin ON has no comparable cost to
 * interrupt: nothing an operator already depends on stops working.
 *
 * Markup, classes (`settings-dialog`/`settings-dialog-backdrop`, `btn-secondary`/`btn-danger`), and
 * behaviour (Escape-to-cancel via the paired hook, Cancel default-focused so the destructive-leaning
 * action is never the default) mirror `features/settings/ExternalMcpRemoveConfirmDialog.tsx` — the
 * most recent precedent for exactly this shape of dialog in this app, reused rather than
 * re-invented.
 */

export interface AgentPluginDisableConfirmDialogProps {
  /** The plugin's own human-readable display name (`agentPluginDisplayName(plugin)`) —
   *  must name the exact plugin being disabled, not a generic "this plugin". */
  name: string;
  /** Which control opened this dialog — see this file's own header for what each reads and why. */
  variant: "disable" | "remove";
  /** The row's recorded provenance; picks the body's last sentence (`buildAgentPluginDisableConfirmCopy`). */
  origin?: "bundled" | "operator-installed";
  /** Enabled plugins that need a capability this one provides, as the server listed them. */
  requiredBy?: readonly string[];
  /** This plugin row's own agent-handle base (e.g. `agent-plugin-row-site-compliance`) — Confirm/
   *  Cancel publish as `<rowHandle>-<variant>-confirm` / `<rowHandle>-<variant>-cancel`, nesting
   *  under the row's own control (`<rowHandle>-enabled` or `<rowHandle>-remove`) the same way
   *  `ExternalMcpRemoveConfirmDialog` nests its own controls under its card's handle. */
  agentHandleBase: string;
  onConfirm: () => void;
  onCancel: () => void;
  /** The screen's own bound translator, threaded down rather than called again here — same
   *  convention `ExternalMcpRemoveConfirmDialog` uses for its own `t`. */
  t: Translate;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention. */
  useAgentPluginDisableConfirmHook?: typeof useAgentPluginDisableConfirm;
}

export function AgentPluginDisableConfirmDialog({
  name,
  variant,
  origin,
  requiredBy,
  agentHandleBase,
  onConfirm,
  onCancel,
  t,
  useAgentPluginDisableConfirmHook = useAgentPluginDisableConfirm,
}: AgentPluginDisableConfirmDialogProps) {
  const { copy, dialogRef } = useAgentPluginDisableConfirmHook({ name, variant, origin, requiredBy, onCancel, t });
  const titleId = `${agentHandleBase}-${variant}-confirm-title`;
  const confirmWord = variant === "remove" ? "Turn off" : "Disable";

  return (
    <div className="settings-dialog-backdrop" onClick={onCancel}>
      <div
        ref={dialogRef}
        className="settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 id={titleId}>{copy.title}</h2>
        <p>{copy.body}</p>
        {copy.dependents ? <p>{copy.dependents}</p> : null}
        <span className="editor-actions">
          {/* Cancel is the default-focused control, matching `ExternalMcpRemoveConfirmDialog`'s own
              "the interrupting action is never the default" precedent. */}
          <button
            type="button"
            className="btn-secondary"
            autoFocus
            onClick={onCancel}
            {...agentHandle({ handle: `${agentHandleBase}-${variant}-cancel` }, {
              role: "button",
              label: `Close this dialog without ${variant === "remove" ? "turning off" : "disabling"} ${name}`,
            })}
          >
            {t("Cancel")}
          </button>
          <button
            type="button"
            className="btn-danger"
            onClick={onConfirm}
            {...agentHandle({ handle: `${agentHandleBase}-${variant}-confirm` }, {
              role: "button",
              label: variant === "remove" ? `Turn off ${name}` : `Disable ${name} for this site`,
            })}
          >
            {t(confirmWord)}
          </button>
        </span>
      </div>
    </div>
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { useId, type ReactNode } from "react";
import { AgentPluginLinkedLock } from "./AgentPluginLinkedLock";
import { AgentPluginMaturity, SOON_PLUGIN_TIP } from "./AgentPluginMaturity";

import { PlainTextBlocks } from "@/components/PlainTextBlocks";
import type { AdminAgentPlugin } from "@/lib/api";
import { AGENT_PLUGIN_GLYPHS, ChevronIcon, EyeIcon, LockIcon, TrashIcon } from "./agent-plugins-visuals";
import { agentPluginCompatibilityLines, agentPluginGlyphKind, agentPluginRemoveOrEnableAriaLabel, agentPluginToggleAriaLabel, agentPluginDisplayName } from "./rules";
import type { Translate } from "@jini-ai/ui/panel-kit";

/**
 * @file One installed Agent Plugin, as a ROW rather than a card (redesign, 2026-09-09).
 *
 * ---------------------------------------------------------------------------
 * What this replaced, and why
 * ---------------------------------------------------------------------------
 * Each plugin used to be a bordered `.jini-settings-section-card` holding a `<dl>` of stacked
 * VERSION / STATUS / KEYWORDS label-over-value pairs plus two labelled chip lists. Three installed
 * plugins came to 1275px of inner scroll — every field of every package shouted at once, at the
 * same weight, so nothing could be found by scanning. Owner's verdict on the result was blunt and
 * correct.
 *
 * The fix is hierarchy, not deletion: NOTHING that card showed is gone. The row carries only what
 * an operator scans a list for — is it on, what is it, which version — and the rest (keywords,
 * skills, MCP server ids) moves into a per-row detail panel that opens on demand.
 * Collapsed, a row is two lines.
 *
 * ---------------------------------------------------------------------------
 * Accessibility decisions worth not re-litigating
 * ---------------------------------------------------------------------------
 *  - The switch is a real `role="switch"` with `aria-checked`, and it is NEVER the only signal of
 *    applied state. The state word beside it and the row's left rail say the same thing, because
 *    colour alone must not carry meaning.
 *  - The expander is the row's own summary button (`aria-expanded`/`aria-controls`), not a separate
 *    chevron hit target competing with the three real controls to its right. Its label is its
 *    visible text, so it gets no `aria-label` — one would override the text a sighted user reads.
 *  - The detail panel is ALWAYS rendered and hidden with the `hidden` attribute, so `aria-controls`
 *    always resolves. `styles.css` carries the matching `[hidden] { display: none; }` guard for it,
 *    for the reason `.cms-section-items[hidden]` already documents in that file: a `display` rule
 *    on the element itself outranks the UA stylesheet's own `[hidden]`.
 *  - The icon-only eye and uninstall buttons carry `aria-label`s naming the plugin. "Inspect
 *    package files — {name}" is preserved verbatim from the text button this eye replaced, so the
 *    accessible name (and the translated `Inspect package files` key behind it) survives the
 *    redesign.
 *
 * ---------------------------------------------------------------------------
 * Two state-area shapes, one row (2026-09-09, Downloaded/Installed row-action split)
 * ---------------------------------------------------------------------------
 * Once Downloaded and Installed existed side by side, the same switch on BOTH tabs was genuinely
 * redundant — Installed already tells the operator "this is on" by which rows it lists at all, so
 * repeating the on/off state a second time on Downloaded's identical row added nothing. Owner's
 * call: Installed keeps the real switch (that tab IS the "what's active" view); Downloaded trades it
 * for a single Remove/Enable action naming what clicking it DOES rather than mirroring state that
 * tab doesn't own. `stateControl` (a discriminated union, not a boolean) carries that difference so
 * `AgentPluginList`/`AgentPlugins.tsx` decide the variant once per tab rather than this row
 * re-deriving it — a row has no way to know which tab it is rendering inside otherwise.
 */

/** The row's state-area control. `"toggle"` is Installed's real Enable/Disable switch, unchanged
 *  from before this split. `"remove-or-enable"` is Downloaded's single action: `onRemove` fires for
 *  a currently-enabled row (opens the same confirm dialog the switch does, reworded to "Remove" —
 *  see `AgentPluginDisableConfirmDialog`), `onEnable` for a currently-disabled one (a direct,
 *  unconfirmed call, same as flipping the switch on has always been). Both are supplied always,
 *  regardless of `plugin.enabled` — the row itself, not its caller, decides which one a click
 *  reaches, since only the row already knows the plugin's own current state at render time. */
export type AgentPluginRowStateControl =
  | { readonly kind: "toggle"; readonly onToggleEnabled: () => void }
  | { readonly kind: "remove-or-enable"; readonly onRemove: () => void; readonly onEnable: () => void };

export interface AgentPluginRowProps {
  readonly plugin: AdminAgentPlugin;
  readonly t: Translate;
  readonly locale: string;
  readonly expanded: boolean;
  readonly busy: boolean;
  readonly onToggleExpanded: () => void;
  readonly stateControl: AgentPluginRowStateControl;
  readonly onInspect: () => void;
  /** The row's Update control (an operator-installed package only; see `updatableAgentPluginDigest`),
   *  shown in the expanded details. The screen builds it, so this row stays props-only. */
  readonly update?: ReactNode;
  /** The plugin's own "Manage" entry (its admin screens), just left of the actions column; absent for most plugins. */
  readonly manage?: ReactNode;
  /** The id of the section-level note explaining why uninstall is unavailable. Referenced by the
   *  disabled uninstall control rather than repeated once per row. */
  readonly uninstallNoteId: string;
  readonly agentHandleBase: string;
}

/** The row's state area — split out of {@link AgentPluginRow} itself so that component's own
 *  branching stays flat; this is the one part of the row whose markup and accessible name genuinely
 *  differ by tab (see this file's own header). */
function AgentPluginRowStateArea({
  plugin,
  t,
  locale,
  busy,
  stateControl,
  agentHandleBase,
  displayName,
}: {
  plugin: AdminAgentPlugin;
  t: Translate;
  locale: string;
  busy: boolean;
  stateControl: AgentPluginRowStateControl;
  agentHandleBase: string;
  displayName: string;
}) {
  // "Soon" plugins are locked off (owner 2026-11-10): the server refuses to switch one on, so the
  // switch shows disabled on both tabs, ahead of a linked face's padlock. A disabled control is not
  // focusable, so the padlock tip beside it carries the reason to keyboard and touch. A Soon plugin
  // still on (boot switches those off) keeps its real switch so it can be turned off.
  if (plugin.maturity === "soon" && !plugin.enabled) {
    return (
      <>
        <span className="agent-plugin-state">{t("Disabled")}</span>
        <button type="button" role="switch" aria-checked={false} aria-label={agentPluginToggleAriaLabel(plugin, locale)} disabled className="agent-plugin-switch">
          <span className="agent-plugin-switch-knob" aria-hidden="true" />
        </button>
        <span className="agent-plugin-linked-lock">
          <InfoTip label={t(SOON_PLUGIN_TIP)} icon={<LockIcon />} agentHandle={`${agentHandleBase}-soon`} />
        </span>
      </>
    );
  }
  // One vendor, one switch (owner 2026-10-25): this plugin follows its provider plugin's switch on
  // the Plugins screen, so on both tabs it shows its state beside a padlock that explains and links
  // there, instead of a switch of its own.
  if (plugin.providerPlugin) {
    return <AgentPluginLinkedLock plugin={plugin} providerPlugin={plugin.providerPlugin} t={t} agentHandleBase={agentHandleBase} />;
  }
  if (stateControl.kind === "toggle") {
    return (
      <>
        {/* The word, not just the switch's position — see this file's header. */}
        <span className="agent-plugin-state">{plugin.enabled ? t("Enabled") : t("Disabled")}</span>
        <button
          type="button"
          role="switch"
          aria-checked={plugin.enabled}
          aria-label={agentPluginToggleAriaLabel(plugin, locale)}
          aria-busy={busy}
          disabled={busy}
          className="agent-plugin-switch"
          onClick={stateControl.onToggleEnabled}
          // `checkbox`, not `switch`: `AgentElementRole` (`@jini-ai/agentic`) has no `switch`
          // member, and `checkbox` is the two-state control a page driver already knows how to
          // read and flip. That vocabulary is the DRIVER's, independent of the ARIA `role`
          // above, which stays `switch` because that is what assistive tech should hear.
          {...agentHandle({ handle: `${agentHandleBase}-enabled` }, {
            role: "checkbox",
            label: `${plugin.enabled ? "Disable" : "Enable"} the "${displayName}" Agent Plugin`,
          })}
        >
          <span className="agent-plugin-switch-knob" aria-hidden="true" />
        </button>
      </>
    );
  }

  // Downloaded: a single action, not a toggle — its own label already names the state (a row
  // reading "Turn off" is implicitly on; one reading "Enable" is implicitly off), so this does not
  // need a second, separate state word the way the switch does.
  const enabled = plugin.enabled;
  const actionWord = enabled ? "Turn off" : "Enable";
  return (
    <button
      type="button"
      aria-busy={busy}
      disabled={busy}
      onClick={enabled ? stateControl.onRemove : stateControl.onEnable}
      aria-label={agentPluginRemoveOrEnableAriaLabel(plugin, locale)}
      {...agentHandle({ handle: `${agentHandleBase}-${enabled ? "remove" : "enable"}` }, {
        role: "button",
        label: `${actionWord} the "${displayName}" Agent Plugin`,
      })}
    >
      {t(actionWord)}
    </button>
  );
}

/** One labelled chip list inside the detail panel. Rendered only when the package actually declares
 *  the thing — an empty "MCP servers" heading would assert that the question was asked and answered
 *  "none", which is not the same as a package that declares none. Also skipped when its one chip is
 *  just the plugin's own id: 20 of 21 bundled plugins ship exactly one skill named after themselves,
 *  so that chip only repeated the row's name (owner, 2026-10-17). */
function DetailChips({ label, values, ownId }: { label: string; values: readonly string[]; ownId: string }) {
  if (values.length === 0 || (values.length === 1 && values[0] === ownId)) return null;
  return (
    <div className="agent-plugin-detail-group">
      <span className="agent-plugin-detail-label">{label}</span>
      <ul className="agent-plugin-chips">
        {values.map((value) => (
          <li key={value}>
            <code>{value}</code>
          </li>
        ))}
      </ul>
    </div>
  );
}

/** Prefer the package's owner-facing summary while preserving its descriptor fallback. */
function agentPluginBlurb(plugin: AgentPluginRowProps["plugin"]): string | null {
  return plugin.summary?.trim() || plugin.description;
}

export function AgentPluginRow(props: AgentPluginRowProps) {
  const { plugin, t, locale, expanded, busy, onToggleExpanded, stateControl, onInspect, manage, uninstallNoteId, agentHandleBase } = props;
  const displayName = agentPluginDisplayName(plugin);
  // The owner-facing explainer (`extensions.jini.summary`) when the package wrote one; else the
  // spec `description`, which is written for the assistant and can be dense with tool ids.
  const blurb = agentPluginBlurb(plugin);
  const Glyph = AGENT_PLUGIN_GLYPHS[agentPluginGlyphKind(plugin)];
  const detailId = useId();
  const headingId = useId();

  return (
    // `data-linked`: a linked plugin's row reads as disabled here; it is switched on the Plugins page.
    <li className="agent-plugin-row" data-enabled={plugin.enabled} data-linked={plugin.providerPlugin ? true : undefined} aria-label={displayName}>
      <div className="agent-plugin-row-main">
        <button
          type="button"
          className="agent-plugin-row-summary"
          aria-expanded={expanded}
          aria-controls={detailId}
          // The description lives INSIDE this button so the whole row is one comfortable hit
          // target, but it must not become the button's accessible name — verified rendered, the
          // name was the entire 60-word manifest description read aloud on focus. Pointing at the
          // heading narrows the name to "Site Compliance v1.0.0" while the description stays
          // visible, and stays reachable in browse mode, exactly as before.
          aria-labelledby={headingId}
          onClick={onToggleExpanded}
          {...agentHandle({ handle: `${agentHandleBase}-details` }, { role: "button", label: `Show or hide the "${displayName}" package details` })}
        >
          <span className="agent-plugin-row-glyph">
            <Glyph size={18} />
          </span>
          <span className="agent-plugin-row-text">
            <span className="agent-plugin-row-heading" id={headingId}>
              <span className="agent-plugin-row-name">{displayName}</span>
              {/* Shown only when the installed package actually carries a version — both are
                  genuinely optional in the Agent Plugins spec, and an invented "1.0.0" would be
                  worse than an absent chip.

                  The explicit `{" "}` is load-bearing, not formatting: this heading IS the summary
                  button's accessible name (`aria-labelledby`), and accessible-name computation
                  concatenates adjacent inline elements with no separator. The flex `gap` that
                  visually separates them is invisible to it, so without a real text node a screen
                  reader announced "Site Compliancev1.0.0". */}
              {plugin.version ? (
                <>
                  {" "}
                  <span className="agent-plugin-row-version">v{plugin.version}</span>
                </>
              ) : null}
              {/* Beside the version (owner, 2026-10-24), so it sits inside the summary button: the
                  wrapper keeps a tap on the pill opening its warning (mobile has no hover) instead of
                  also toggling the row. Its "Soon"/"Untested" label joins the row's accessible name. */}
              {plugin.maturity ? (
                <>
                  {" "}
                  <span className="agent-plugin-row-maturity" onClick={(e) => e.stopPropagation()}>
                    <AgentPluginMaturity maturity={plugin.maturity} t={t} />
                  </span>
                </>
              ) : null}
            </span>
            {plugin.connectionStatus ? <span className="agent-plugin-row-desc">{t({
              connected: "Signed in", disconnected: "Not signed in", pending: "Waiting for sign-in", needs_reauth: "Sign in again",
            }[plugin.connectionStatus])}</span> : null}
            {/* `title` is the ONLY way to read the rest of a clamped line without opening the row —
                a hover tooltip, not a substitute for the unclamped copy below in the expanded
                panel (screen readers and touch have no hover; that copy is the real fix). */}
            {/* Compatibility first: "Not for this Tovu version" explains a switch that refuses to
                turn on, and "Needs …" names capabilities no other enabled plugin provides. */}
            {agentPluginCompatibilityLines({ plugin, translate: t }).map((line) => (
              <span key={line} className="agent-plugin-row-desc">{line}</span>
            ))}
            {blurb ? (
              <span className="agent-plugin-row-desc" title={blurb}>
                {blurb}
              </span>
            ) : null}
          </span>
          <span className="agent-plugin-row-chevron">
            <ChevronIcon />
          </span>
        </button>

        {/* Outside the actions column, against its divider: the switch stays at the same x on every row. */}
        {manage ? <div className="agent-plugin-row-manage">{manage}</div> : null}
        <div className="agent-plugin-row-actions">
          <AgentPluginRowStateArea
            plugin={plugin}
            t={t}
            locale={locale}
            busy={busy}
            stateControl={stateControl}
            agentHandleBase={agentHandleBase}
            displayName={displayName}
          />
          <button
            type="button"
            className="agent-plugin-icon-btn"
            onClick={onInspect}
            // Preserved verbatim from the text button this replaced: "Inspect package files" reads
            // identically on every row, so the plugin's own name must stay in the accessible name.
            aria-label={`${t("Inspect package files")} — ${displayName}`}
            {...agentHandle({ handle: `${agentHandleBase}-inspect` }, { role: "button", label: `Inspect the "${displayName}" package files` })}
          >
            <EyeIcon />
          </button>
          {/* HONEST-DISABLED, not decorative, and the domain agrees.
              `features/agent-plugins/uninstall.ts`'s `uninstallAgentPlugin()` (landed 2026-09-09,
              concurrently with this redesign) REFUSES any package whose activation record says
              `origin: "bundled"`, with `AgentPluginNotUninstallableError` — precisely because
              `recordBundledAgentPluginIfAbsent` re-seeds it on the next boot, so a delete would
              appear to succeed and then silently reappear. That function's own header names this
              screen's enable/disable control (the switch on Installed, Remove/Enable on Downloaded
              — see this file's own header) as the lever an operator actually has for a bundled
              package.

              Every installed package today is bundled — `installAgentPluginFromUrl` exists but has
              zero production callers, so nothing can arrive as `operator-installed` — and there is
              no HTTP uninstall route either (the only wrapper is an assistant tool). So a live
              button here would refuse on every row that exists. It becomes real when an
              install-from-url path ships; until then the affordance holds its place and says why.

              The reason is stated once at section level and referenced by every row via
              `aria-describedby`: a disabled control is not focusable, so a per-row tooltip would
              never be read. */}
          <button
            type="button"
            className="agent-plugin-icon-btn"
            disabled
            aria-label={`${t("Uninstall")} ${displayName} — ${t("unavailable")}`}
            aria-describedby={uninstallNoteId}
          >
            <TrashIcon />
          </button>
        </div>
      </div>

      <div className="agent-plugin-row-detail" id={detailId} hidden={!expanded}>
        {/* The summary line above clips this same string to one line (`.agent-plugin-row-desc`,
            `-webkit-line-clamp: 1`) — a hover tooltip covers a sighted mouse user, but expanding
            the row is the only path assistive tech and touch have, so the full text repeats here,
            unclamped, first — before every other per-plugin fact this panel already held. */}
        <PlainTextBlocks text={blurb} className="agent-plugin-detail-description" />
        {/* The agent-facing `description` and the search `keywords` are NOT rendered here (owner,
            2026-10-17: a "Technical details" wall of tool ids and a 40-chip keyword cloud read as
            noise). Both still reach the assistant unchanged through `search_agent_plugin_local`,
            and the eye button's package viewer shows the raw manifest for anyone who wants it. */}
        <DetailChips label={t("Skills")} values={plugin.skills.map((skill) => skill.name)} ownId={plugin.pluginId} />
        <DetailChips label={t("MCP servers")} values={plugin.mcpServerIds} ownId={plugin.pluginId} />
        {props.update ?? null}
      </div>
    </li>
  );
}

import { RemixIcon } from "@jini-ai/ui";
import { PreviewModalShell } from "@jini-ai/ui/preview-modal-shell";
import { agentHandle } from "@jini-ai/agentic";
import { useId, type ReactNode } from "react";

import { buildAgentListHandles } from "@jini-ai/agentic";
import type { Translate } from "@jini-ai/ui/panel-kit";
import type { PackageFilesStatus, PackageFileView } from "./rules";
import { packageFileIconKind, type PackageFileIconKind } from "./package-file-tree";
import { usePackageFileTree } from "./hooks/use-package-file-tree.hooks";
import { useCodeWrap } from "@/components/CodeView/use-code-wrap.hooks";
import { CodeView, CodeWrapToggle } from "@/components/CodeView/CodeView";
import { CODE_PREVIEW_MODAL_ICONS } from "@/components/CodeView/preview-modal-icons";

/**
 * @file The read-only package-files browser BOTH plugin screens open — a VS Code-style file tree
 * (files first, chevrons, indent guides, file-type icons; since 2026-09-29) on the left, the
 * selected file's source on the right with a Wrap toggle, inside Jini's `PreviewModalShell` (which
 * supplies the expand and close controls). Extracted 2026-09-13 out of `AgentPluginDetailsModal.tsx`
 * so Agent Plugins and Plugins render through one component and cannot drift apart.
 *
 * Presentational only: it loads nothing and holds no data. Each caller owns its source and passes
 * files in — Agent Plugins and Plugins both read the installed package live from the server via
 * `AGENT_PLUGIN_FILES` / `PLUGIN_FILES` (see `hooks/use-agent-plugin-details-modal.hooks.ts` and
 * `hooks/use-plugin-package-files.hooks.ts`).
 *
 * Class names keep the `agent-plugin-source-*` prefix they had before the extraction, so
 * `styles.css` needed no change.
 */

export interface PackageFilesModalProps {
  readonly title: string;
  readonly headerExtras?: ReactNode;
  readonly subtitle?: string;
  readonly files: readonly PackageFileView[];
  readonly selectedFile: PackageFileView | null;
  readonly onSelectFile: (relativePath: string) => void;
  /** Shown in the content pane while no file is selected: loading, a load failure, or no files. */
  readonly status: PackageFilesStatus | null;
  /** One line above the file list, e.g. that the viewer's caps left some files out. */
  readonly listNotice?: string | null;
  /** Prefix for each file row's agent handle (`agent-plugin-file`, `plugin-file`). */
  readonly handlePrefix: string;
  readonly t: Translate;
  readonly onClose: () => void;
  readonly additionalViews?: readonly { id: string; label: string; custom: ReactNode }[];
  /** Forward the shared shell's selected-view notification so the host can update its header. */
  readonly onView?: (viewId: string) => void;
  /** The view to open on (an additional view's id); the package files otherwise. */
  readonly initialViewId?: string;
}

/** A package-relative path with a `<wbr>` after every `/` (visual QA, 2026-08-31). Used by the
 *  content pane's heading since the file list became a tree (2026-09-29). Paths run
 *  long (`skills/interface-design/references/commands/critique.md`) — without a preferred break point
 *  `overflow-wrap: anywhere` (styles.css) was free to split mid-filename, e.g. leaving a lone `d`
 *  orphaned on its own line after "critique.m". `<wbr>` only offers the browser a *preferred* spot
 *  to break, so `overflow-wrap: anywhere` still catches the rare segment too long for the pane on
 *  its own — this only makes the common case break at a path boundary instead of a word. */
function PackageFilePath({ path }: { path: string }) {
  const segments = path.split("/");
  return (
    <>
      {segments.map((segment, i) => (
        <span key={i}>
          {segment}
          {i < segments.length - 1 ? "/" : null}
          {i < segments.length - 1 ? <wbr /> : null}
        </span>
      ))}
    </>
  );
}

/** RemixIcon glyph per file family (`package-file-tree.ts`'s {@link packageFileIconKind}). The
 *  `is-<kind>` class on the icon carries its tint (styles.css). */
const FILE_ICON_GLYPH: Readonly<Record<PackageFileIconKind, string>> = {
  json: "braces-line",
  markdown: "markdown-line",
  javascript: "javascript-line",
  typescript: "code-s-slash-line",
  config: "settings-3-line",
  html: "html5-line",
  css: "css3-line",
  image: "image-line",
  shell: "terminal-box-line",
  text: "file-text-line",
  file: "file-line",
};

/** Folder state and file type determine only the decorative tree glyphs. */
function PackageTreeIcon({ folder, expanded, name }: { folder: boolean; expanded: boolean; name: string }) {
  if (folder) return <>
    <RemixIcon name={expanded ? "arrow-down-s-line" : "arrow-right-s-line"} size={16} className="agent-plugin-source-tree-twistie" />
    <RemixIcon name={expanded ? "folder-open-line" : "folder-line"} className="agent-plugin-source-tree-icon is-folder" />
  </>;
  return <>
    <span className="agent-plugin-source-tree-twistie" aria-hidden />
    <RemixIcon name={FILE_ICON_GLYPH[packageFileIconKind(name)]} className={`agent-plugin-source-tree-icon is-${packageFileIconKind(name)}`} />
  </>;
}

/**
 * The file list as a WAI-ARIA tree, one flat row per visible node (`aria-level` carries the
 * nesting), so the selected row's highlight spans the pane's full width the way VS Code's does.
 * Expansion, focus and keys are `usePackageFileTree`; a row's full path is its tooltip, since long
 * names truncate rather than wrap. File rows keep the `…-select` agent handles the flat list had.
 */
function PackageFileTree({
  files,
  selectedPath,
  onSelectFile,
  fileHandleByPath,
  handlePrefix,
  label,
}: {
  files: readonly PackageFileView[];
  selectedPath: string | null;
  onSelectFile: (relativePath: string) => void;
  fileHandleByPath: ReadonlyMap<string, string>;
  handlePrefix: string;
  label: string;
}) {
  const tree = usePackageFileTree({ paths: files.map((file) => file.relativePath), selectedPath, onOpenFile: onSelectFile });
  const folderPaths = tree.rows.filter((row) => row.node.kind === "folder").map((row) => row.node.path);
  const folderHandles = buildAgentListHandles({ prefix: `${handlePrefix}-folder`, ids: folderPaths });
  const folderHandleByPath = new Map(folderPaths.map((path, index) => [path, folderHandles[index]!]));

  return (
    <div ref={tree.treeRef} role="tree" aria-label={label} className="agent-plugin-source-tree" onKeyDown={tree.onKeyDown}>
      {tree.rows.map((row) => {
        const { node } = row;
        const folder = node.kind === "folder";
        const expanded = folder && tree.isExpanded(node.path);
        const handle = folder
          ? agentHandle({ handle: `${folderHandleByPath.get(node.path)}-toggle` }, { role: "button", label: `Expand or collapse the "${node.path}" folder` })
          : agentHandle({ handle: `${fileHandleByPath.get(node.path)}-select` }, { role: "button", label: `Select the "${node.path}" file` });
        return (
          <div
            key={`${node.kind}:${node.path}`}
            role="treeitem"
            aria-label={node.name}
            aria-level={row.depth + 1}
            aria-setsize={row.setSize}
            aria-posinset={row.posInSet}
            aria-expanded={folder ? expanded : undefined}
            aria-selected={folder ? undefined : node.path === selectedPath}
            tabIndex={node.path === tree.activePath ? 0 : -1}
            title={node.path}
            data-tree-path={node.path}
            className="agent-plugin-source-tree-row"
            onClick={() => tree.onRowClick(row)}
            onFocus={() => tree.onRowFocus(node.path)}
            {...handle}
          >
            <span className="agent-plugin-source-tree-indent" style={{ width: `calc(${row.depth} * var(--tree-indent))` }} aria-hidden />
            <PackageTreeIcon folder={folder} expanded={expanded} name={node.name} />
            <span className="agent-plugin-source-tree-label">{node.name}</span>
          </div>
        );
      })}
    </div>
  );
}

/**
 * Keyed by `file.relativePath` in the parent, so switching the selected file remounts this and
 * resets `wrap` to its default rather than carrying a manual toggle across files.
 *
 * Defaults to wrapped for every file. Previously unwrapped for `plugin.json`/`.ts` sources on the
 * theory that structure reads better with no wrap; in practice the most likely first click in this
 * modal (`plugin.json`) ran a long line off the pane indefinitely, and the owner had to scroll
 * horizontally just to read it (owner correction, 2026-09-10). The toggle keeps unwrapped one click
 * away for whoever genuinely wants raw structure.
 *
 * A file listed without content (binary, too large, a symlink) shows its reason instead, and has no
 * Wrap toggle — there is nothing to wrap.
 */
function PackageFileContent({
  file,
  headingId,
  agentHandleBase,
  t,
}: {
  file: PackageFileView;
  headingId: string;
  agentHandleBase: string;
  t: Translate;
}) {
  const { wrap, toggleWrap } = useCodeWrap();
  const hasContent = file.content !== null;

  return (
    <section className="agent-plugin-source-content" aria-labelledby={headingId}>
      <div className="agent-plugin-source-content-header">
        <h3 id={headingId}>
          <PackageFilePath path={file.relativePath} />
        </h3>
        {hasContent ? (
          <CodeWrapToggle wrap={wrap} onToggle={toggleWrap} t={t} agentHandleId={`${agentHandleBase}-wrap-toggle`} />
        ) : null}
      </div>
      <PackageFileBody file={file} wrap={wrap} />
    </section>
  );
}

function PackageFileBody({ file, wrap }: { file: PackageFileView; wrap: boolean }) {
  if (file.content === null) {
    return (
      <p className="notice" role="status">
        {file.unavailableReason}
      </p>
    );
  }
  return <CodeView text={file.content} wrap={wrap} />;
}

export function PackageFilesModal({
  title,
  headerExtras,
  subtitle,
  files,
  selectedFile,
  onSelectFile,
  status,
  listNotice,
  handlePrefix,
  t,
  onClose,
  additionalViews = [],
  onView,
  initialViewId,
}: PackageFilesModalProps) {
  const selectedFileHeadingId = useId();
  // File paths are stable and unique within one package, same per-row-handle derivation every
  // other list on this workstream uses (`buildAgentListHandles`).
  const fileHandles = buildAgentListHandles({ prefix: handlePrefix, ids: files.map((file) => file.relativePath) }
  );
  const fileHandleByPath = new Map(files.map((file, index) => [file.relativePath, fileHandles[index]!]));

  return (
    <PreviewModalShell
      className="agent-plugin-source-modal"
      icons={CODE_PREVIEW_MODAL_ICONS}
      title={title}
      headerExtras={headerExtras}
      subtitle={subtitle}
      onView={onView}
      initialViewId={initialViewId}
      views={[
        {
          id: "package-source",
          label: t("Package files"),
          custom: (
            <div className="agent-plugin-source-browser">
              <nav className="agent-plugin-source-files" aria-label={t("Package files")}>
                {listNotice ? (
                  <p className="page-description" role="note">
                    {listNotice}
                  </p>
                ) : null}
                <PackageFileTree
                  files={files}
                  selectedPath={selectedFile?.relativePath ?? null}
                  onSelectFile={onSelectFile}
                  fileHandleByPath={fileHandleByPath}
                  handlePrefix={handlePrefix}
                  label={t("Package files")}
                />
              </nav>
              {selectedFile ? (
                <PackageFileContent
                  file={selectedFile}
                  headingId={selectedFileHeadingId}
                  key={selectedFile.relativePath}
                  agentHandleBase={fileHandleByPath.get(selectedFile.relativePath)!}
                  t={t}
                />
              ) : null}
              {!selectedFile && status ? <p role={status.role}>{status.text}</p> : null}
            </div>
          ),
        },
        ...additionalViews,
      ]}
      onClose={onClose}
    />
  );
}

import { agentHandle } from "@jini-ai/agentic";

import { usePluginRemoveConfirm } from "./hooks/use-plugin-remove-confirm.hooks";
import type { Translate } from "@jini-ai/ui/panel-kit";

/** @file Confirmation gate before a site plugin moves to the 60-day Trash. */

export interface PluginRemoveConfirmDialogProps {
  /** The plugin's own display name (`plugin.name`) — must name the exact plugin being removed, not
   *  a generic "this plugin". */
  name: string;
  /** This plugin row's own agent-handle base — Confirm/Cancel publish as
   *  `<rowHandle>-remove-confirm` / `<rowHandle>-remove-cancel`, nesting under the row's own handle
   *  the same way `AgentPluginDisableConfirmDialog` nests under its row's `-enabled` switch. */
  agentHandleBase: string;
  onConfirm: () => void;
  onCancel: () => void;
  /** The screen's own bound translator, threaded down rather than called again here — same
   *  convention `AgentPluginDisableConfirmDialog` uses for its own `t`. */
  t: Translate;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention. */
  usePluginRemoveConfirmHook?: typeof usePluginRemoveConfirm;
}

export function PluginRemoveConfirmDialog({
  name,
  agentHandleBase,
  onConfirm,
  onCancel,
  t,
  usePluginRemoveConfirmHook = usePluginRemoveConfirm,
}: PluginRemoveConfirmDialogProps) {
  const { copy, dialogRef } = usePluginRemoveConfirmHook({ name, onCancel, t });
  const titleId = `${agentHandleBase}-remove-confirm-title`;

  return (
    <div className="settings-dialog-backdrop" onClick={onCancel}>
      <div
        ref={dialogRef}
        className="settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 id={titleId}>{copy.title}</h2>
        <p>{copy.body}</p>
        <span className="editor-actions">
          {/* Cancel stays default-focused because moving a shared package affects every workspace. */}
          <button
            type="button"
            className="btn-secondary"
            autoFocus
            onClick={onCancel}
            {...agentHandle({ handle: `${agentHandleBase}-remove-cancel` }, {
              role: "button",
              label: `Close this dialog without moving ${name} to the Trash`,
            })}
          >
            {t("Cancel")}
          </button>
          <button
            type="button"
            className="btn-danger"
            onClick={onConfirm}
            {...agentHandle({ handle: `${agentHandleBase}-remove-confirm` }, {
              role: "button",
              label: `Move ${name} to the Trash`,
            })}
          >
            {t("Move to trash")}
          </button>
        </span>
      </div>
    </div>
  );
}

