/** "Remove from Tovu," never "Revoke": removal forgets the stored copy, the provider keeps the key. */
const REMOVE_FROM_TOVU = "Remove from Tovu";

/**
 * @file The Access Tokens tab — `Security.tsx`'s one tab and this feature's actual content. One
 * flat, searchable, category-filtered list of every credential this install holds across all eight
 * stores `development/todos.md:1208` names — the 2026-08-16 owner ruling that replaced this page's
 * original two-surface shape (seven Tier 1 providers here, a banner naming six unread Tier 2 stores)
 * with a single list: "from a person's point of view a Cloudinary key and a GitHub token are the
 * same kind of thing — a secret this install holds." See `ADS-memory/reports/design/
 * 2026-08-16-access-tokens-visual-spec.md`'s "OWNER RULING" section for the ruling in full.
 *
 * Tier 1 (`ACCESS_TOKEN_PROVIDERS`, `rules.ts`: the hosting and source-control providers) still gets `[+ Add]` and multiple operator-named rows per provider — the
 * genuinely new capability this page adds (see `Security.tsx`'s own header for why "Create" living
 * here is not a repeat of what Static Site/Source Control already do). Tier 2
 * (`OTHER_CREDENTIAL_STORES`, `rules.ts`, rendered by `OtherCredentialsSection.tsx`) gets Replace/
 * Remove and a deep link to wherever Create actually lives, never a second Create — the tier split
 * survives only as that per-row CAPABILITY difference now, not as two separate surfaces. The
 * "showing 7 of 8" partial-inventory banner this page used to render is deleted; there is nothing
 * left to disclose once every store is read.
 *
 * ## Search
 *
 * Matches a provider's/store's brand label, its purpose subtitle ("Hosting"/"Source control"/
 * "AI"/… — the disambiguation `rules.ts`'s header calls "the two-store GitHub trap" for Tier 1, and
 * the same subtitle Tier 2 rows carry next to their own name), and a saved item's own name. A group
 * renders when EITHER its own info matches the query OR it has at least one matching saved row — so
 * typing "GitHub" surfaces both the GitHub Pages group (provider match) and the GitHub · Source
 * Control group (provider match), each rendering its own real rows, never merged into one card.
 *
 * ## Category filter
 *
 * `All / Source control / Hosting / Media / AI / Ops` (`rules.ts`'s `ACCESS_TOKEN_CATEGORIES`),
 * `All` default, borrowing Settings' wrapped icon-tab-row LOOK without adopting `SettingsDialogShell`
 * itself — that component bundles its own vertical sidebar plus a kicker/title/subtitle header that
 * fights this page's own `.page-header` (`Deployment.tsx`'s header documents the same rejection for
 * the identical reason). `.access-tokens-category-filter` is its own class, not an overload of
 * `.tab-bar` — a filter control, not a tab bar, and `.tab-bar` is shared by five other screens that
 * must not be affected by this page's own styling needs.
 *
 * ## Component split
 *
 * Per-scope ESLint complexity gate (hard 9/9 cyclomatic/cognitive) — same "extract, don't inline"
 * discipline `ProvidersTab.tsx`/`StaticSiteTab.tsx` already use for the identical reason.
 */

export interface AccessTokensTabProps {
  /** DI seams for tests — same convention as every other wired-hook prop in this app. */
  useAccessTokensHook?: typeof useWiredAccessTokens;
  useOtherCredentialsHook?: typeof useWiredOtherCredentials;
  useCopyKeysHook?: typeof useWiredCopyKeys;
  /** Whether the "Use a saved key" entry renders; defaults to
   *  {@link SHOW_COPY_KEYS_ENTRY} (hidden per owner 2026-10-11; shown again per owner 2026-11-08). */
  showCopyKeysEntry?: boolean;
}

/** A provider group can take another saved token unless it is custom or unlisted. */
function acceptsAnotherToken(info: { kind: string; unlisted?: boolean }): boolean {
  return info.kind !== "custom" && !info.unlisted;
}

function resolveAccessTokensHook(override: typeof useWiredAccessTokens | undefined): typeof useWiredAccessTokens {
  return override ?? useWiredAccessTokens;
}
function resolveOtherCredentialsHook(override: typeof useWiredOtherCredentials | undefined): typeof useWiredOtherCredentials {
  return override ?? useWiredOtherCredentials;
}

/** Whether the "Use a saved key" entry renders above the list (see its render site). */
const SHOW_COPY_KEYS_ENTRY = true;

export function AccessTokensTab(props: AccessTokensTabProps) {
  useAdminLocale();
  const useAccessTokensHook = resolveAccessTokensHook(props.useAccessTokensHook);
  const useOtherCredentialsHook = resolveOtherCredentialsHook(props.useOtherCredentialsHook);
  const controller = useAccessTokensHook();
  // Tier 2 reads `query`/`category` FROM Tier 1's own controller rather than owning either — one
  // search box, one category filter, across both tiers (this file's own header). See
  // `use-other-credentials.hooks.ts`'s header for why that state isn't duplicated here instead.
  const otherController = useOtherCredentialsHook({ query: controller.query, category: controller.category });
  const useCopyKeysHook = props.useCopyKeysHook ?? useWiredCopyKeys;
  const copyDialog = useCopyKeysHook({ t: controller.t });

  return (
    <div
      className="access-tokens-tab"
      {...agentHandle({ handle: "security-access-tokens" }, {
        role: "region",
        label: "Every access token and other saved credential this install holds, across all eight stores, searchable and filterable by category",
      })}
    >
      {/* Owner 2026-11-08: back on ("be able to share keys among databases") after being hidden
          2026-10-11. Same picker and route as the chat card. */}
      {(props.showCopyKeysEntry ?? SHOW_COPY_KEYS_ENTRY) ? (
        <>
          <button type="button" className="btn-secondary" onClick={copyDialog.show}>{controller.t("Use a saved key")}</button>
          <CopyKeysDialog dialog={copyDialog} t={controller.t} />
        </>
      ) : null}
      <AccessTokensBody controller={controller} otherController={otherController} />
    </div>
  );
}

/** Loading/error/populated split — pulled out of {@link AccessTokensTab} purely for the complexity
 *  gate, same reasoning `SourceControlCredentialsList` documents in `ProvidersTab.tsx`. Waits for
 *  BOTH tiers' first load: rendering Tier 1's list before Tier 2 has resolved would put the category
 *  filter and the row list on screen a beat before Tier 2's own rows could ever appear under it,
 *  which reads as those rows being silently absent rather than still loading.
 *
 * `useMergedSecretsOrder` (a hook) is called unconditionally, ahead of every early return below —
 * Rules of Hooks — even though its result is only rendered once the loading/error gates pass; it
 * tolerates either controller's `groups` still being `undefined` internally (`AccessTokensTab.hooks.tsx`'s
 * own doc), so calling it early costs nothing. */
function AccessTokensBody({ controller, otherController }: { controller: AccessTokensController; otherController: OtherCredentialsController }) {
  const addCustomDialogRef = useRef<HTMLDialogElement>(null);
  const merged = useMergedSecretsOrder(controller, otherController, controller.query);
  if (controller.loadError) {
    return (
      <p className="notice error" role="status" {...agentHandle({ handle: "security-access-tokens-load-error" }, { role: "status", label: "Shows the error when saved access tokens could not be loaded" })}>
        {controller.loadError}
      </p>
    );
  }
  if (otherController.loadError) {
    return (
      <p className="notice error" role="status" {...agentHandle({ handle: "security-other-credentials-load-error" }, { role: "status", label: "Shows the error when other saved credentials could not be loaded" })}>
        {otherController.loadError}
      </p>
    );
  }
  if (controller.groups === undefined || otherController.groups === undefined) {
    return <p className="access-tokens-loading">{controller.t("Loading access tokens…")}</p>;
  }
  return (
    <>
      <AccessTokensSearch controller={controller} otherController={otherController} />
      <AccessTokensCategoryFilter controller={controller} onAddCustomProvider={() => addCustomDialogRef.current?.showModal()} />
      <HostingPluginsHint controller={controller} />
      <div className="access-tokens-tier">
        {merged.length === 0 && !controller.query ? <div className="empty-state"><p>{controller.t("Not connected")}</p></div> : null}
        {merged.map((entry) =>
          entry.kind === "provider" ? (
            <ProviderGroup key={entry.key} group={entry.group} controller={controller} />
          ) : (
            <OtherCredentialEntry key={entry.key} store={entry.store} row={entry.row} controller={otherController} />
          )
        )}
      </div>
      <AddCustomCredentialDialog ref={addCustomDialogRef} controller={controller} t={controller.t} />
    </>
  );
}

/** The hosting filter can be empty while source-control groups still exist. */
function HostingPluginsHint({ controller }: { controller: AccessTokensController }) {
  if (controller.query || !["all", "hosting"].includes(controller.category) || controller.groups?.some((group) => group.info.category === "hosting")) return null;
  return <div className="empty-state">
    <p>{controller.t("Enable a hosting plugin to manage its access tokens.")}</p>
    <a href={adminHref("/addons/agent-plugins")}>{controller.t("Plugins")}</a>
  </div>;
}

/** The `All / Source control / Hosting / Media / AI / Ops` filter row, PLUS the "Add custom
 *  provider" button — see this file's header for why the filter row borrows Settings' wrapped
 *  icon-tab-row LOOK rather than the component itself. The button is a deliberately SEPARATE
 *  control after the mapped category pills (`margin-left: auto` in `access-tokens.css` pushes it to
 *  the far right of the row), not a pill itself — it opens a create form, it does not filter
 *  anything, so it must never read as an eighth category to a search/scan of this row. Pulled out
 *  of {@link AccessTokensBody} for the complexity gate; its own branching is a single `.map()` plus
 *  one static button, so this split is about readability/reuse rather than a budget this one
 *  function would otherwise exceed. */
function AccessTokensCategoryFilter({ controller, onAddCustomProvider }: { controller: AccessTokensController; onAddCustomProvider: () => void }) {
  const translate = controller.t;
  // Reuses `TabBar.hooks.tsx`'s WAI-ARIA tabs keyboard helpers rather than reimplementing them —
  // `ACCESS_TOKEN_CATEGORIES`'s `{ id, label }` shape structurally satisfies `TabBarTab`, and none
  // of these categories are ever disabled. `[role="tab"]` scoping already skips the non-tab
  // "+ Add custom provider" button below (this file's own header on why that button stays out of
  // the tablist's tab order).
  const { onKeyDown } = useTabBarKeyboard({ tabs: ACCESS_TOKEN_CATEGORIES, activeId: controller.category, onChange: (id) => controller.setCategory(id as AccessTokenCategoryId) });
  return (
    <div
      className="access-tokens-category-filter"
      role="tablist"
      aria-label={translate("Filter by category")}
      onKeyDown={onKeyDown}
      {...agentHandle({ handle: "security-access-tokens-category-filter" }, { role: "region", label: "Filter the credential list by category" })}
    >
      {ACCESS_TOKEN_CATEGORIES.map((c) => (
        <button
          key={c.id}
          type="button"
          role="tab"
          className="access-tokens-category-filter-item"
          aria-selected={controller.category === c.id}
          tabIndex={resolveTabBarTabIndex({ tabs: ACCESS_TOKEN_CATEGORIES, activeId: controller.category, tab: c })}
          onClick={() => controller.setCategory(c.id as AccessTokenCategoryId)}
          {...agentHandle({ handle: `security-access-tokens-category-${c.id}` }, { role: "button", label: `Filter the credential list to ${c.label}` })}
        >
          {translate(c.label)}
        </button>
      ))}
      <button
        type="button"
        className="access-tokens-add-custom-button"
        onClick={onAddCustomProvider}
        {...agentHandle({ handle: "security-access-tokens-add-custom-provider" }, { role: "button", label: "Add a custom provider not in the built-in list" })}
      >
        {translate("+ Add custom provider")}
      </button>
    </div>
  );
}

/** The search box and its own match-count line — counts are the SUM of both tiers'
 *  `totalCount`/`matchCount` (this file's header on why the combined count stays a GLOBAL fact,
 *  unaffected by the category filter below it). "token(s)" stays the noun even though the count now
 *  spans Tier 2's keys/credentials too — the existing e2e suite pins the exact string
 *  (`development/e2e/access-tokens.spec.ts`'s `/^0 tokens saved$/`), and nothing in this pass asked
 *  for new copy here; a person calling an API key a "token" loosely is the same shorthand this
 *  page's own tab name already uses for the whole install. The line itself is `rules.ts`'s
 *  `accessTokensCountText` — a whole translated sentence per plural form, not fragments glued in
 *  English word order (see that function's own doc for why). */
function AccessTokensSearch({ controller, otherController }: { controller: AccessTokensController; otherController: OtherCredentialsController }) {
  const translate = controller.t;
  const totalCount = controller.totalCount + otherController.totalCount;
  const matchCount = controller.matchCount + otherController.matchCount;
  const countText = accessTokensCountText(totalCount, matchCount, controller.query, translate);
  return (
    <div className="access-tokens-search">
      <label className="visually-hidden" htmlFor="access-tokens-search">
        {translate("Search access tokens")}
      </label>
      <span className="access-tokens-search-icon">
        <SearchIcon />
      </span>
      <input
        id="access-tokens-search"
        className="access-tokens-search-input"
        type="search"
        autoComplete="off"
        value={controller.query}
        onChange={(e) => controller.setQuery(e.target.value)}
        placeholder={translate("Search by provider, name, or purpose")}
        {...agentHandle({ handle: "security-access-tokens-search" }, { role: "field", label: "Search saved access tokens by provider, name, or purpose" })}
      />
      <p className="access-tokens-search-count" role="status" aria-live="polite">
        {countText}
      </p>
    </div>
  );
}

function ProviderGroup({ group, controller }: { group: AccessTokenProviderGroupState; controller: AccessTokensController }) {
  const ref: AccessTokenProviderRef = { kind: group.info.kind, providerId: group.info.providerId };
  const hasRows = group.rows.length > 0;
  return (
    <section
      className="access-tokens-provider-group"
      {...agentHandle({ handle: `security-access-tokens-group-${group.info.kind}-${agentHandleSegment({ value: group.info.providerId })}` }, {
        role: "region",
        label: providerGroupHandleLabel(group.info, group.rows.length),
      })}
    >
      <h3 className="access-tokens-provider-heading">
        <span translate="no">{group.info.label}</span>
        <span className="access-tokens-provider-purpose"> · {providerGroupSubtitleKeys(group.info).map(controller.t).join(" · ")}</span>
      </h3>
      {group.info.unlisted ? <p className="field-hint">{controller.t("Its plugin is off or missing. You can still remove saved tokens.")}</p> : null}
      {group.rows.map((row) => (
        <TokenRow key={row.row.id} state={row} info={group.info} controller={controller} groupRowCount={group.rows.length} t={controller.t} />
      ))}
      {!hasRows && !group.addForm.visible ? <NotConnectedRow ref={ref} label={group.info.label} onConnect={() => controller.openAddForm(ref)} t={controller.t} /> : null}
      {group.addForm.visible ? <AddTokenForm info={group.info} state={group.addForm} controller={controller} t={controller.t} /> : null}
      {/* No `[+ Add another]` for a `"custom"` group — it has no shared provider identity a second
          saved row could join; a second custom credential is a wholly new one, created through the
          standalone "Add custom provider" dialog, not this per-provider affordance. */}
      {/* Nor for an unlisted provider (plugin off or missing): it takes no new token. */}
      {hasRows && !group.addForm.visible && acceptsAnotherToken(group.info) ? <AddAnotherButton ref={ref} label={group.info.label} controller={controller} t={controller.t} /> : null}
    </section>
  );
}

function AddAnotherButton({ ref, label, controller, t: translate }: { ref: AccessTokenProviderRef; label: string; controller: AccessTokensController; t: Translate }) {
  return (
    <button
      type="button"
      className="link-button access-tokens-add-another"
      onClick={() => controller.openAddForm(ref)}
      {...agentHandle({ handle: `security-access-tokens-add-${ref.kind}-${agentHandleSegment({ value: ref.providerId })}` }, { role: "button", label: `Add another ${label} token` })}
    >
      {translate("Add another")} <span translate="no">{label}</span> {translate("token")}
    </button>
  );
}

function NotConnectedRow({ ref, label, onConnect, t: translate }: { ref: AccessTokenProviderRef; label: string; onConnect: () => void; t: Translate }) {
  return (
    <div className="access-tokens-row">
      <div className="access-tokens-row-summary">
        <span className="access-tokens-row-marker" aria-hidden="true" />
        <span className="access-tokens-row-name">{translate("Not connected")}</span>
        <button
          type="button"
          className="access-tokens-row-summary-expand"
          onClick={onConnect}
          // `aria-label`, not just the visible "Connect" text: every not-yet-connected provider on
          // this page renders this exact same bare word, so with two or more not-connected rows on
          // screen at once (the common case — most installs have not connected every one of the
          // seven providers), `getByRole("button", { name: "Connect" })` — or an agent resolving by
          // accessible name — cannot tell GitHub's row from GitLab's. `label` here is already the
          // provider's own display label (e.g. "GitHub Pages"), so this starts with the exact
          // visible word (WCAG 2.5.3 Label in Name).
          aria-label={`${translate("Connect")} ${label}`}
          // Handle built from `ref.kind`/`ref.providerId` (already lowercase, hyphen-safe — every
          // `AccessTokenProviderRef` in this app comes straight off `ACCESS_TOKEN_PROVIDERS`), never
          // from `label` — `agentHandle()` rejects any handle that isn't lowercase words joined by
          // single hyphens, and a proper-noun label like "GitHub Pages" (capitals, a space) throws
          // at render time. Caught live: an uncaught throw here unmounted this whole row with no
          // error boundary above it, which is worse than a defensive check — a crash, not a fallback.
          {...agentHandle({ handle: `security-access-tokens-connect-${ref.kind}-${agentHandleSegment({ value: ref.providerId })}` }, { role: "button", label: `Connect ${label}` })}
        >
          {translate("Connect")}
          <DisclosureChevronIcon />
        </button>
      </div>
    </div>
  );
}

function TokenRow({
  state,
  info,
  controller,
  groupRowCount,
  t: translate,
}: {
  state: AccessTokenExistingRowState;
  info: AccessTokenProviderInfo;
  controller: AccessTokensController;
  groupRowCount: number;
  t: Translate;
}) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const showDefaultUi = groupRowCount >= 2;
  return (
    <details
      className="access-tokens-row access-tokens-row-done"
      {...agentHandle({ handle: `security-access-tokens-row-${state.row.kind}-${agentHandleSegment({ value: state.row.providerId })}-${agentHandleSegment({ value: state.row.id })}` }, {
        role: "region",
        label: tokenRowHandleLabel(state.name, info.label),
      })}
    >
      <summary className="access-tokens-row-summary">
        <span className="access-tokens-row-marker access-tokens-row-marker-done" aria-hidden="true">
          <ConnectedMarkIcon />
        </span>
        <span className="access-tokens-row-name">{state.name}</span>
        <CustomKeyUsage state={state} controller={controller} />
        <TokenRowDefaultIndicator state={state} showDefaultUi={showDefaultUi} controller={controller} t={translate} />
        <span className="access-tokens-row-summary-meta">
          {state.row.worksFor?.length ? <span>{translate("Works for")}: {state.row.worksFor.join(", ")} · </span> : null}
          {translate("saved")} {formatTimestamp({ iso: state.row.updatedAt }, { timeZone: "local" })} <CredentialHint hint={state.row.tokenHint} />
        </span>
        <span className="access-tokens-row-summary-expand">
          {translate(state.row.scope === "project" && !state.row.usedByThisSite ? "Details" : "Replace token")}
          <DisclosureChevronIcon />
        </span>
      </summary>
      {state.row.scope === "project" && !state.row.usedByThisSite ? (
        <div className="access-tokens-row-actions">
          <p className="field-hint">{translate("Use on this site to replace this key.")}</p>
          <button type="button" className="btn-danger" onClick={() => dialogRef.current?.showModal()} aria-label={`${translate(REMOVE_FROM_TOVU)} — ${state.name}`}>
            {translate(REMOVE_FROM_TOVU)}
          </button>
        </div>
      ) : <ExistingTokenFields state={state} controller={controller} info={info} onRemoveClick={() => dialogRef.current?.showModal()} t={translate} />}
      <RemoveConfirmDialog ref={dialogRef} row={state.row} info={info} controller={controller} isLastForProvider={groupRowCount === 1} t={translate} />
    </details>
  );
}

/** Storage and attachment facts for custom keys. Summary actions preserve the disclosure state,
 * matching the existing default-token action; the controller owns all I/O and failures.
 */
function CustomKeyUsage({ state, controller }: { state: AccessTokenExistingRowState; controller: AccessTokensController }) {
  if (state.row.kind !== "custom") return null;
  const translate = controller.t;
  if (state.row.scope !== "project") return <span className="status status-neutral">{translate("This site only")}</span>;
  const sites = state.row.usedBy ?? [];
  const action = state.row.usedByThisSite ? "Stop using on this site" : "Use on this site";
  return <>
    <span className="status status-neutral">
      {sites.length ? <>{translate("Project — used by:")} <span translate="no">{sites.join(", ")}</span></> : translate("Project — not used by any site yet")}
    </span>
    <button type="button" className="link-button" disabled={controller.customKeyBusy[state.row.id]?.saving}
      aria-label={`${translate(action)} — ${state.name}`}
      onClick={event => {
        event.preventDefault();
        event.stopPropagation();
        void controller.setCustomKeyUse({ row: state.row, use: !state.row.usedByThisSite });
      }}
      {...agentHandle({ handle: `security-access-tokens-use-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `${action} — ${state.name}` })}
    >{translate(action)}</button>
    <span className="field-hint">{translate("Access is revoked within 30 seconds.")}</span>
    {controller.customKeyBusy[state.row.id]?.error ? <span className="save-error" role="alert">{controller.customKeyBusy[state.row.id].error}</span> : null}
  </>;
}

/** The `isDefault` indicator + `Make default` link — only shown once a provider has 2+ saved
 *  tokens (`rules.ts`'s own doc on why a lone row has nothing to choose between). Split out purely
 *  for the complexity gate.
 *
 * This button lives inside `TokenRow`'s own `<summary>`, a descendant of the native disclosure
 * toggle, so its click would otherwise ALSO open/close the enclosing `<details>` (the browser runs
 * `<summary>`'s toggle as the click event's default action regardless of which descendant was
 * actually clicked, unless that default action is cancelled) — `preventDefault`/`stopPropagation`
 * in the handler below is what keeps a "Make default" click from also expanding the row, same
 * pattern as `deployment/StaticSiteTab.tsx`'s `CredentialVerifyAction`. */
function TokenRowDefaultIndicator({ state, showDefaultUi, controller, t: translate }: { state: AccessTokenExistingRowState; showDefaultUi: boolean; controller: AccessTokensController; t: Translate }) {
  if (!showDefaultUi) return null;
  if (state.row.isDefault) return <span className="status status-neutral">{translate("Default")}</span>;
  return (
    <button
      type="button"
      className="link-button"
      onClick={(e) => {
        e.preventDefault();
        e.stopPropagation();
        void controller.makeDefault(state.row);
      }}
      // `aria-label`, not just the visible "Make default" text: this button renders once per
      // non-default row in a provider group that has 2+ saved tokens (the ONLY case it renders at
      // all — this function's own guard above), so with 3+ saved tokens for one provider, multiple
      // identically-labeled "Make default" buttons are on screen simultaneously. `state.name` is
      // this row's own operator-chosen display name, already unique enough to pick one out.
      aria-label={`${translate("Make default")} — ${state.name}`}
      {...agentHandle({ handle: `security-access-tokens-default-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Make ${state.name} the default token` })}
    >
      {translate("Make default")}
    </button>
  );
}

/** Shared input markup for BOTH the "add a new token" form and an existing row's "replace" fields —
 *  same split `PublishCredentialFields`/`SourceControlCredentialFields` use for the identical
 *  connected/not-connected duality. Every hint renders below its input as `.field-hint`, never as
 *  placeholder text — same "placeholder-as-label reads as a saved value" defect this app has already
 *  fixed twice (`ProvidersTab.tsx`'s own header). */
function TokenInputFields({
  idPrefix,
  info,
  name,
  token,
  values,
  username,
  onNameChange,
  onTokenChange,
  onFieldChange,
  onUsernameChange,
  connected,
  t: translate,
}: {
  idPrefix: string;
  info: AccessTokenProviderInfo;
  name: string;
  token: string;
  values: Readonly<Record<string, string>>;
  username: string;
  onNameChange: (value: string) => void;
  onTokenChange: (value: string) => void;
  onFieldChange: (name: string, value: string) => void;
  onUsernameChange: (value: string) => void;
  connected: boolean;
  t: Translate;
}) {
  // Only a custom row shows Username, always optional (`rules.ts`'s `AccessTokenProviderInfo` doc).
  const needsUsername = info.username !== undefined;
  const extraFields = extraFieldsAroundToken(info);
  return (
    <div className="access-tokens-row-fields">
      <div className="field">
        <label className="field-label" htmlFor={`${idPrefix}-name`}>
          {translate("Name")}
        </label>
        <input
          id={`${idPrefix}-name`}
          type="text"
          value={name}
          onChange={(e) => onNameChange(e.target.value)}
          {...agentHandle({ handle: `${idPrefix}-name` }, { role: "field", label: "This token's display name" })}
        />
        <p className="field-hint">{translate("A short label so you can tell this token apart from others for the same provider.")}</p>
      </div>
      <ExtraFieldInputs fields={extraFields.before} idPrefix={idPrefix} values={values} onFieldChange={onFieldChange} t={translate} />
      <div className="field">
        <label className="field-label" htmlFor={`${idPrefix}-token`}>
          {info.tokenLabel ?? translate("Access token")}
        </label>
        {/* `autoComplete="new-password"`, NOT `"off"` — Chrome deliberately ignores `off` on
            credential-shaped fields (a long-standing intentional decision, not a bug), and `off`
            here is what let the reported autofill through. `new-password` is the documented signal
            for "this field is not a saved-login field", which suppresses both the saved-credential
            dropdown and the silent fill.

            This input is why the SEARCH BOX at the top of the page was being filled with "admin":
            `TokenRow`'s `<details>` renders `ExistingTokenFields` unconditionally, so every saved
            token leaves a live password input in the DOM even while its row is collapsed. Chrome's
            formless credential heuristic groups a page's text-like fields with any password field
            by DOM proximity — no `<form>` required, and there is none in this feature — so the page
            read as a login surface and the first text-like field (the search box) got the site's
            saved username. Fixing the search box's own attribute could not work: the search box was
            the symptom, these fields are the trigger. */}
        <SecretInput
          label={info.tokenLabel ?? translate("Access token")}
          id={`${idPrefix}-token`}
          autoComplete="new-password"
          value={token}
          onChange={(e) => onTokenChange(e.target.value)}
          {...agentHandle({ handle: `${idPrefix}-token` }, { role: "field", label: "This token's secret value — stored encrypted, never shown again once saved" })}
        />
        <p className="field-hint">
          {connected ? translate("Leave blank to keep the current token.") : translate("Stored encrypted on the server. Once saved, Tovu never displays it again.")}
        </p>
        {info.scopeGuidanceKey !== "" || info.tokenPageUrl !== "" ? (
          <details className="access-tokens-scope-guidance">
            <summary className="access-tokens-scope-guidance-summary">
              {translate("Which token do I need?")}
              <DisclosureChevronIcon size={10} />
            </summary>
            <p className="field-hint">
              {info.scopeGuidanceKey !== "" ? <>{translate(info.scopeGuidanceKey)} </> : null}
              {info.tokenPageUrl !== "" ? (
                <a
                  href={info.tokenPageUrl}
                  target="_blank"
                  rel="noreferrer"
                  {...agentHandle({ handle: `${idPrefix}-token-page` }, { role: "link", label: `Open ${info.label}'s own page for creating a personal access token` })}
                >
                  {translate("Create a token")}
                </a>
              ) : null}
            </p>
          </details>
        ) : null}
      </div>
      <ExtraFieldInputs fields={extraFields.after} idPrefix={idPrefix} values={values} onFieldChange={onFieldChange} t={translate} />
      {needsUsername ? (
        <div className="field">
          <label className="field-label" htmlFor={`${idPrefix}-username`}>
            {translate("Username")}
          </label>
          <input
            id={`${idPrefix}-username`}
            type="text"
            value={username}
            onChange={(e) => onUsernameChange(e.target.value)}
            {...agentHandle({ handle: `${idPrefix}-username` }, { role: "field", label: "The username this token authenticates against, when this provider needs one" })}
          />
          <p className="field-hint">{translate("Optional — only needed if this provider authenticates a token against a username.")}</p>
        </div>
      ) : null}
    </div>
  );
}

/** A run of {@link ExtraFieldInput}s, in the order given. */
function ExtraFieldInputs({
  fields,
  idPrefix,
  values,
  onFieldChange,
  t: translate,
}: {
  fields: readonly AdminPublishTargetField[];
  idPrefix: string;
  values: Readonly<Record<string, string>>;
  onFieldChange: (name: string, value: string) => void;
  t: Translate;
}) {
  return (
    <>
      {fields.map((field) => (
        <ExtraFieldInput
          key={field.name}
          id={`${idPrefix}-${accessTokenExtraFieldIdSuffix(field.name)}`}
          field={field}
          value={values[field.name] ?? ""}
          onChange={(value) => onFieldChange(field.name, value)}
          t={translate}
        />
      ))}
    </>
  );
}

/** One of a provider's descriptor fields (a host's account ID, bucket, region…): the descriptor's
 *  label (a host term, verbatim) plus the translated "(optional)" suffix, and its help below. */
function ExtraFieldInput({
  id,
  field,
  value,
  onChange,
  t: translate,
}: {
  id: string;
  field: AdminPublishTargetField;
  value: string;
  onChange: (value: string) => void;
  t: Translate;
}) {
  return (
    <div className="field">
      <label className="field-label" htmlFor={id}>
        {field.label}
        {field.required ? null : ` ${translate("(optional)")}`}
      </label>
      <SecretInput
        label={field.label}
        secret={field.secret === true}
        id={id}
        autoComplete="new-password"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        {...agentHandle({ handle: id }, { role: "field", label: `This provider's ${field.label}` })}
      />
      {fieldHelpText(field) ? <p className="field-hint">{fieldHelpText(field)}</p> : null}
    </div>
  );
}

/** Reuse Jini's multiple-choice field, retaining disabled-plugin ids as removable raw chips.
 * Rendering costs O(options + selected) space and time; selection stays in the controller.
 */
function WorksForField({ value = [], options = [], onChange, t }: {
  value: string[];
  options: { value: string; label: string }[];
  onChange: (value: string[]) => void;
  t: Translate;
}, _options = {}) {
  const choices = new Map(options.map(option => [option.value, option]));
  for (const id of value) if (!choices.has(id)) choices.set(id, { value: id, label: id });
  return <div className="field" role="group" aria-label={t("Works for")}>
    <OnboardingChipField multiple label={t("Works for")} options={[...choices.values()]} value={value} onChange={onChange} />
  </div>;
}

function ExistingTokenFields({
  state,
  controller,
  info,
  onRemoveClick,
  t: translate,
}: {
  state: AccessTokenExistingRowState;
  controller: AccessTokensController;
  info: AccessTokenProviderInfo;
  onRemoveClick: () => void;
  t: Translate;
}) {
  const readyToSave = state.readyToSave;
  return (
    <>
      <TokenInputFields
        idPrefix={`security-existing-${agentHandleSegment({ value: state.row.id })}`}
        info={info}
        name={state.name}
        token={state.token}
        values={state.values}
        username={state.username}
        onNameChange={(v) => controller.setExistingField(state.row.id, { name: v })}
        onTokenChange={(v) => controller.setExistingField(state.row.id, { token: v })}
        onFieldChange={(name, v) => controller.setExistingField(state.row.id, { values: { ...state.values, [name]: v } })}
        onUsernameChange={(v) => controller.setExistingField(state.row.id, { username: v })}
        connected
        t={translate}
      />
      {info.kind !== "source-control" ? <WorksForField value={state.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setExistingField(state.row.id, { worksFor })} t={translate} /> : null}
      <SharedKeyReplaceNote row={state.row} t={translate} />
      <div className="access-tokens-row-actions">
        <button
          type="button"
          disabled={!readyToSave || state.saving}
          onClick={() => void controller.replaceToken(state.row)}
          // `aria-label`, not just the visible "Save"/"Saving…" text: a provider group can hold
          // several saved tokens (`AddAnotherButton` above), each opened via its own `<details>`
          // (unlike `RowMenu`'s exclusive-open items, more than one can be expanded at once) — with
          // two rows open, both show an identical bare "Save" button. `state.name` is this row's own
          // display name, already visible in its `<summary>` heading, so it disambiguates the same
          // way a sighted reader already can. Mirrors the visible text's own saving/idle split so the
          // accessible name never says "Save" while the button reads "Saving…" (WCAG 2.5.3).
          aria-label={`${state.saving ? translate("Saving…") : translate("Save")} — ${state.name}`}
          {...agentHandle({ handle: `security-access-tokens-save-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Save this ${info.label} token` })}
        >
          {state.saving ? translate("Saving…") : translate("Save")}
        </button>
        <button
          type="button"
          className="btn-danger"
          onClick={onRemoveClick}
          // Same multi-row-open ambiguity as Save above, on this page's one destructive action —
          // see `rules.ts`'s `restoreButtonAccessibleName` (`recovery/rules.ts`) for the identical
          // reasoning applied to a different screen's own always-visible destructive control.
          aria-label={`${translate(REMOVE_FROM_TOVU)} — ${state.name}`}
          {...agentHandle({ handle: `security-access-tokens-remove-${agentHandleSegment({ value: state.row.id })}` }, { role: "button", label: `Open the confirm dialog to remove this ${info.label} token from Tovu` })}
        >
          {translate(REMOVE_FROM_TOVU)}
        </button>
        {state.error ? (
          <p className="save-error" role="alert">
            {state.error}
          </p>
        ) : null}
      </div>
    </>
  );
}

/** Warns, before Save, that a shared project key's other sites switch to the new token too. */
function SharedKeyReplaceNote({ row, t: translate }: { row: AccessTokenExistingRowState["row"]; t: Translate }) {
  const warning = row.scope === "project" ? sharedKeyReplaceWarning({ usedBy: row.usedBy, usedByThisSite: row.usedByThisSite, t: translate }) : null;
  return warning ? <p className="save-warning">{warning}</p> : null;
}

function AddTokenForm({ info, state, controller, t: translate }: { info: AccessTokenProviderInfo; state: AccessTokenAddFormState; controller: AccessTokensController; t: Translate }) {
  const ref: AccessTokenProviderRef = { kind: info.kind, providerId: info.providerId };
  const readyToSave = state.readyToSave;
  return (
    <div className="access-tokens-row">
      <TokenInputFields
        idPrefix={`security-add-${info.kind}-${agentHandleSegment({ value: info.providerId })}`}
        info={info}
        name={state.name}
        token={state.token}
        values={state.values}
        username={state.username}
        onNameChange={(v) => controller.setAddField(ref, { name: v })}
        onTokenChange={(v) => controller.setAddField(ref, { token: v })}
        onFieldChange={(name, v) => controller.setAddField(ref, { values: { ...state.values, [name]: v } })}
        onUsernameChange={(v) => controller.setAddField(ref, { username: v })}
        connected={false}
        t={translate}
      />
      {info.kind === "publish" ? <WorksForField value={state.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setAddField(ref, { worksFor })} t={translate} /> : null}
      <div className="access-tokens-row-actions">
        <button
          type="button"
          disabled={!readyToSave || state.saving}
          onClick={() => void controller.createToken(ref)}
          // `aria-label`: more than one provider's "Add" form can be open at once (each provider
          // group owns its own independent `addForm.visible`), and every one of them renders this
          // same bare "Save"/"Saving…" text — `info.label` is the one thing that tells them apart
          // here (there is no operator-chosen name yet to use, unlike `ExistingTokenFields`' own
          // fix above, since this token has not been saved).
          aria-label={`${state.saving ? translate("Saving…") : translate("Save")} — ${info.label}`}
          {...agentHandle({ handle: `security-access-tokens-create-${info.kind}-${agentHandleSegment({ value: info.providerId })}` }, { role: "button", label: `Save this ${info.label} token` })}
        >
          {state.saving ? translate("Saving…") : translate("Save")}
        </button>
        <button
          type="button"
          className="link-button"
          onClick={() => controller.closeAddForm(ref)}
          aria-label={`${translate("Cancel")} adding this ${info.label} token`}
          {...agentHandle({ handle: `security-access-tokens-cancel-${info.kind}-${agentHandleSegment({ value: info.providerId })}` }, { role: "button", label: "Close this add-token form without saving" })}
        >
          {translate("Cancel")}
        </button>
        {state.error ? (
          <p className="save-error" role="alert">
            {state.error}
          </p>
        ) : null}
      </div>
    </div>
  );
}

/**
 * Native `<dialog>` confirm — same `.confirm-dialog` foundation `styles.css:2880` documents (`[open]`-
 * scoped `display`, never a bare-class rule — that comment's own header records the live bug an
 * unscoped rule caused). "Remove from Tovu," never "Revoke" — `rules.ts`'s own header, this page's
 * one load-bearing copy constraint: deleting Tovu's row does not revoke the credential at the
 * provider, and this dialog is the one place that fact has to be stated in words, not implied by a
 * button label.
 *
 * Confirm button carries no `agentHandle` — destructive, same boundary
 * `StaticSiteTab.tsx`'s own credential-entry fields already draw (no agent read/act surface over a
 * credential action); the row's own SUMMARY stays tagged (`TokenRow`'s `agentHandle`), only this
 * dialog's destructive action does not.
 */
const RemoveConfirmDialog = forwardRef<HTMLDialogElement, { row: AccessTokenRow; info: AccessTokenProviderInfo; controller: AccessTokensController; isLastForProvider: boolean; t: Translate }>(
  function RemoveConfirmDialog({ row, info, controller, isLastForProvider, t: translate }, ref) {
    const locale = useAdminLocale();
    const { close, confirm } = useRemoveConfirmDialog(ref, row, controller);
    // `aria-labelledby`, not left implicit: a native `<dialog>` has no accessible name of its own
    // from an `<h2>` sitting inside it — that link has to be stated, the same way the shared
    // `ConfirmDialog` (`@jini-ai/admin/react`) already does via its own `titleId`. Without it, every
    // one of this page's per-row remove dialogs reads to an accessibility tree as an unnamed
    // "dialog", indistinguishable from any other open dialog on the page. Scoped by `row.id` (not a
    // static id) because one `RemoveConfirmDialog` is mounted per token row, all in the DOM at once.
    const titleId = `security-access-tokens-remove-title-${agentHandleSegment({ value: row.id })}`;
    return (
      <dialog ref={ref} className="confirm-dialog" aria-labelledby={titleId}>
        <h2 id={titleId}>{removeDialogTitle(locale, row.name)}</h2>
        <p className="confirm-dialog-body">{removeDialogBody(locale, info.label, info.vendorLabel)}</p>
        {info.tokenPageUrl === "" ? null : <p>
          {/* `info.vendorLabel`, NOT `info.label` — this line says WHERE to revoke, and "GitHub
              Pages"/"Cloudflare Pages" are destinations with no revoke console of their own. See
              `rules.ts`'s `AccessTokenProviderInfo.vendorLabel` doc for the full reasoning; every
              other `info.label` on this page still names the destination on purpose. */}
          <a
            href={info.tokenPageUrl}
            target="_blank"
            rel="noreferrer"
            {...agentHandle({ handle: `security-access-tokens-revoke-page-${agentHandleSegment({ value: row.id })}` }, { role: "link", label: `Open ${info.vendorLabel} to revoke this token at the source` })}
          >
            {translate("Revoke it on")} <span translate="no">{info.vendorLabel}</span> ↗
          </a>
        </p>}
        {isLastForProvider ? <p className="confirm-dialog-body">{removeDialogLastRowNote(locale, info.label)}</p> : null}
        <div className="confirm-dialog-actions">
          <button
            type="button"
            onClick={close}
            {...agentHandle({ handle: `security-access-tokens-remove-cancel-${agentHandleSegment({ value: row.id })}` }, { role: "button", label: "Close this dialog without removing the token" })}
          >
            {translate("Cancel")}
          </button>
          <button type="button" className="btn-danger" onClick={confirm}>
            {translate(REMOVE_FROM_TOVU)}
          </button>
        </div>
      </dialog>
    );
  }
);

/** The red-star marker on a required field's label — Name/API base URL/Access token in the form
 *  below (Username stays unmarked, Category always carries a value so it's never actually blank).
 *  `aria-label`, not `aria-hidden`, so a screen reader announces "required" — same convention
 *  `Authentication.tsx`'s own `source-config-field-required` marker uses. */
function RequiredFieldMarker() {
  return (
    <span className="access-tokens-field-required" aria-label="required">
      {" "}
      *
    </span>
  );
}

/** The "Additional hosts" field — split out of {@link AddCustomCredentialDialog} purely so that
 *  function's own complexity stays under this repo's gate; the inline-error branch below adds one
 *  more decision point to whichever function renders it, and `AddCustomCredentialDialog` already
 *  carries a full field set's worth. */
function AdditionalHostsField({ value, onChange, translate }: { value: string; onChange: (value: string) => void; translate: Translate }) {
  const invalid = invalidAdditionalHostsEntries(value);
  return (
    <div className="field">
      <label className="field-label" htmlFor="security-add-custom-additional-hosts">
        {translate("Additional hosts")}
      </label>
      <textarea
        id="security-add-custom-additional-hosts"
        rows={2}
        value={value}
        placeholder="https://secondary-api.example.test"
        onChange={(e) => onChange(e.target.value)}
        {...agentHandle({ handle: "security-access-tokens-add-custom-additional-hosts" }, {
          role: "field",
          label: "Extra API hosts this same credential is also allowed to call, beyond the base URL",
        })}
      />
      <p className="field-hint">
        {translate("Optional — some providers use more than one API host for the same account (e.g. api.example.test and secondary-api.example.test). One per line, or comma-separated.")}
      </p>
      {invalid.length > 0 ? <p className="field-error">{translate("Each additional host must be a valid http:// or https:// URL.")}</p> : null}
    </div>
  );
}

/** Local API keys live in Shared Keys; this site's selection is only a grant/reference. */
function CustomKeyStorageChoice({ controller }: { controller: AccessTokensController }) {
  return <p className="field-hint">{controller.t(controller.projectKeysAvailable ? "Save to project and use on this site" : "This site only")}</p>;
}

/**
 * The "Add custom provider" form (`AccessTokensCategoryFilter`'s own button opens it) — a
 * standalone native `<dialog>`, not a per-provider `AddTokenForm` (this file's own header on why a
 * custom row has no shared provider group to attach an inline add-form to). Collects the four
 * fields the brief specifies (API base URL, Access token with a show/hide toggle, optional
 * Username, Category) plus a Name field every other row on this page already requires (the display
 * name the list/search will show — `TokenInputFields`' own "Name" field doc gives the identical
 * reasoning). Deliberately does NOT reuse `TokenInputFields`: that shared component's field set
 * (Name/Token/AccountId/Username) has no Base URL or Category concept, and both of those are
 * create-only here (see `rules.ts`'s `accessTokenRowProviderInfo` doc for why Replace on an
 * existing custom row does not re-collect them) — bolting a fifth, create-only field onto a
 * component shared with the seven catalog providers' Replace flow would risk it leaking there too.
 */
const AddCustomCredentialDialog = forwardRef<HTMLDialogElement, { controller: AccessTokensController; t: Translate }>(
  function AddCustomCredentialDialog({ controller, t: translate }, ref) {
    const { readyToSave, baseUrlInvalid, close, save } = useAddCustomCredentialDialog(ref, controller);
    const form = controller.customAddForm;
    // Same `aria-labelledby` fix as `RemoveConfirmDialog` above — one instance of this dialog per
    // page, so a static id is fine (contrast the per-row `row.id`-scoped id there).
    const titleId = "security-access-tokens-add-custom-title";

    return (
      <dialog
        ref={ref}
        className="confirm-dialog access-tokens-add-custom-dialog"
        aria-labelledby={titleId}
        {...agentHandle({ handle: "security-access-tokens-add-custom-dialog" }, { role: "region", label: "Add a custom provider not in the built-in list" })}
      >
        <h2 id={titleId}>{translate("Add custom provider")}</h2>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-name">
            {translate("Name")}
            <RequiredFieldMarker />
          </label>
          <input
            id="security-add-custom-name"
            type="text"
            value={form.name}
            onChange={(e) => controller.setCustomAddField({ name: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-name" }, { role: "field", label: "This custom provider's display name, e.g. a registrar" })}
          />
          <p className="field-hint">{translate("A short label so you can tell this apart from your other saved credentials.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-base-url">
            {translate("API base URL")}
            <RequiredFieldMarker />
          </label>
          <input
            id="security-add-custom-base-url"
            type="url"
            value={form.baseUrl}
            placeholder="https://api.example.com"
            onChange={(e) => controller.setCustomAddField({ baseUrl: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-base-url" }, { role: "field", label: "This provider's API base URL" })}
          />
          {baseUrlInvalid ? <p className="field-error">{translate("Enter a valid http:// or https:// URL.")}</p> : null}
        </div>
        <AdditionalHostsField
          value={form.additionalHosts}
          onChange={(value) => controller.setCustomAddField({ additionalHosts: value })}
          translate={translate}
        />
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-token">
            {translate("Access token")}
            <RequiredFieldMarker />
          </label>
          <SecretInput
            label={translate("Access token")}
            id="security-add-custom-token"
            autoComplete="new-password"
            value={form.token}
            onChange={(e) => controller.setCustomAddField({ token: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-token" }, { role: "field", label: "This provider's access token" })}
            toggleAttrs={agentHandle({ handle: "security-access-tokens-add-custom-token-toggle" }, { role: "button", label: "Show or hide the access token" })}
          />
          <p className="field-hint">{translate("This will not be shown again for security purposes.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-username">
            {translate("Username")}
          </label>
          <input
            id="security-add-custom-username"
            type="text"
            value={form.username}
            onChange={(e) => controller.setCustomAddField({ username: e.target.value })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-username" }, { role: "field", label: "This provider's username, if it authenticates a token against one" })}
          />
          <p className="field-hint">{translate("Optional — only needed if this provider authenticates a token against a username.")}</p>
        </div>
        <div className="field">
          <label className="field-label" htmlFor="security-add-custom-category">
            {translate("Category")}
          </label>
          <select
            id="security-add-custom-category"
            value={form.category}
            onChange={(e) => controller.setCustomAddField({ category: e.target.value as AccessTokenRowCategoryId })}
            {...agentHandle({ handle: "security-access-tokens-add-custom-category" }, { role: "field", label: "Which category this credential is filed under" })}
          >
            {ACCESS_TOKEN_CATEGORIES.filter((c) => c.id !== "all").map((c) => (
              <option key={c.id} value={c.id}>
                {translate(c.label)}
              </option>
            ))}
          </select>
        </div>
        <CustomKeyStorageChoice controller={controller} />
        <WorksForField value={form.worksFor} options={controller.worksForOptions} onChange={worksFor => controller.setCustomAddField({ worksFor })} t={translate} />
        {form.error ? (
          <p className="save-error" role="alert">
            {form.error}
          </p>
        ) : null}
        <div className="confirm-dialog-actions">
          <button
            type="button"
            onClick={close}
            {...agentHandle({ handle: "security-access-tokens-add-custom-cancel" }, { role: "button", label: "Close this dialog without saving a custom provider" })}
          >
            {translate("Cancel")}
          </button>
          <button
            type="button"
            disabled={!readyToSave || form.saving}
            onClick={() => void save()}
            {...agentHandle({ handle: "security-access-tokens-add-custom-save" }, { role: "button", label: "Save this custom provider credential" })}
          >
            {form.saving ? translate("Saving…") : translate("Save")}
          </button>
        </div>
      </dialog>
    );
  }
);

import { agentHandle } from "@jini-ai/agentic";
import type { useT } from "@jini-ai/ui";

import { useExternalMcpRemoveConfirm } from "./hooks/use-external-mcp-remove-confirm.hooks";

/**
 * @file Confirmation gate in front of `SourceConfigItemCard`'s "Remove" — added after an operator
 * pressed it on a live, fully-configured OAuth connection and lost it immediately, with no way
 * back (the sealed OAuth secret is never returned by the read API, so removal meant reconnecting
 * from scratch). `@jini-ai/ui`'s card cannot own this itself (`onRemove` fires on click, no
 * confirm step) and stays unmodified per the outline's "Zero Jini change" rule for this surface —
 * `ExternalMcpSettingsPanel.tsx` intercepts the callback instead and only calls the port's
 * `remove` once this dialog's own Confirm is pressed.
 *
 * Markup, classes (`settings-dialog`/`settings-dialog-backdrop`, `btn-secondary`/`btn-danger`),
 * and behaviour (Escape-to-cancel via the paired hook, Cancel default-focused so the destructive
 * action is never the default) all mirror `features/collections/Collections.tsx`'s
 * `LifecycleConfirmDialog` — the most recent precedent for exactly this shape of dialog in this
 * app, reused rather than re-invented. `.btn-secondary`/`.btn-danger` already declare `color`
 * explicitly in `styles.css` (verified: lines 1084/1088), so this does not trip the global
 * `button { color: var(--primary-ink) }` reset that made the sibling card's own pills briefly ship
 * invisible — no new CSS is added here.
 */

export interface ExternalMcpRemoveConfirmDialogProps {
  /** The server's own display name, e.g. `sourceDisplayLabel(source, fieldSpecs)` — must name
   *  the exact connection being removed, not a generic "this connection". */
  name: string;
  /** Whether this connection's credential is an OAuth-sealed secret — changes the body copy
   *  (see `buildExternalMcpRemoveConfirmCopy`). */
  isOAuth: boolean;
  /** This card's own agent-handle base (e.g. `mcp-server-higgsfield`) — Confirm/Cancel publish
   *  as `<cardHandle>-remove-confirm` / `<cardHandle>-remove-cancel`, nesting under the card's
   *  already-published `<cardHandle>-remove` the same way `-field-<key>-reveal` nests under
   *  `-field-<key>` in `@jini-ai/ui`'s own `agent-handles.ts` scheme. */
  cardHandle: string;
  onConfirm: () => void;
  onCancel: () => void;
  /** The panel's own translator (`useT()` from `@jini-ai/ui`) — threaded down rather than called
   *  again here, same convention `Collections.tsx` uses to hand `t` to `LifecycleConfirmDialog`. */
  t: ReturnType<typeof useT>;
  /** Dependency injection seam for tests — see `PostsProps.usePostsHook` for the convention. */
  useExternalMcpRemoveConfirmHook?: typeof useExternalMcpRemoveConfirm;
}

export function ExternalMcpRemoveConfirmDialog({
  name,
  isOAuth,
  cardHandle,
  onConfirm,
  onCancel,
  t,
  useExternalMcpRemoveConfirmHook = useExternalMcpRemoveConfirm,
}: ExternalMcpRemoveConfirmDialogProps) {
  const { copy, dialogRef } = useExternalMcpRemoveConfirmHook({ name, isOAuth, onCancel, t });
  const titleId = `${cardHandle}-remove-confirm-title`;

  return (
    <div className="settings-dialog-backdrop" onClick={onCancel}>
      <div
        ref={dialogRef}
        className="settings-dialog"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <h2 id={titleId}>{copy.title}</h2>
        <p>{copy.body}</p>
        <span className="editor-actions">
          {/* Cancel is the default-focused control — this action is not reversible from this
              screen (an OAuth secret cannot be recovered), matching `LifecycleConfirmDialog`'s
              own "Tombstone" precedent for the same reason. */}
          <button
            type="button"
            className="btn-secondary"
            autoFocus
            onClick={onCancel}
            {...agentHandle({ handle: `${cardHandle}-remove-cancel` }, {
              role: "button",
              label: `Close this dialog without removing ${name}`,
            })}
          >
            {t("Cancel")}
          </button>
          <button
            type="button"
            className="btn-danger"
            onClick={onConfirm}
            {...agentHandle({ handle: `${cardHandle}-remove-confirm` }, {
              role: "button",
              label: `Permanently remove ${name} — this cannot be undone from this screen`,
            })}
          >
            {t("Remove")}
          </button>
        </span>
      </div>
    </div>
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { useT } from "@jini-ai/ui";

import { useExternalMcpDriftCopy } from "./ExternalMcpSettingsPanel.hooks";
import { useExternalMcpToolsModalEscape } from "./ExternalMcpToolsModal.hooks";
import { ExternalMcpToolPicker } from "./ExternalMcpToolPicker";

/**
 * @file Per-server Tools modal (2026-09-10) — opened by the "Tools" button `ExternalMcpSettingsPanel.tsx`
 * now renders beside each configured server's card, replacing that file's own per-row Connection/Tools
 * `TabBar` (see its header's "Per-server Tools modal" section for why: with more than one configured
 * server, a flat tab strip left it ambiguous which server's Tools tab an operator was looking at —
 * owner call). Wraps the UNMODIFIED `ExternalMcpToolPicker` — same two-list wiring (allowlist + write
 * grant), same restart-drift footnote, same probe/refresh/save/cancel controls — inside a dialog
 * instead of a tab body; this file owns no picker state of its own, only the dialog chrome around it.
 *
 * Markup (backdrop, `.settings-dialog`), classes, and behaviour (Escape-to-close, click-off-to-close)
 * mirror `ExternalMcpRemoveConfirmDialog.tsx`'s own precedent — reused rather than re-invented, per
 * the outline's "Zero Jini change" rule for this surface. `.external-mcp-tools-modal`
 * (`styles/external-mcp-tool-picker.css`) widens the shared `.settings-dialog` the same way
 * `styles.css`'s own `.sitemap-modal` widens it for its own wide content; see that rule's comment for
 * why `width` (not just `max-width`) is required against `.settings-dialog-backdrop`'s
 * `place-items: center` shrink-to-fit sizing — a tool list that can run to 100+ rows needs the room.
 *
 * Closing this modal (Close, backdrop click, or Escape) never warns about unsaved picker edits. That
 * matches this feature's own PRIOR behaviour, not a new gap: under the old TabBar, switching from the
 * Tools tab back to Connection already unmounted `ExternalMcpToolPicker` — whose draft state
 * (`useWiredExternalMcpToolPicker`) lives in that component alone, not lifted — so an unsaved
 * selection was already silently discarded on tab-away. This modal's Close does the same thing the
 * old tab-away always did.
 */

export interface ExternalMcpToolsModalProps {
  /** The server's own display name (e.g. `sourceDisplayLabel(source, fieldSpecs)`) — must name the
   *  exact connection whose tools this modal edits, not a generic "this server's tools". */
  name: string;
  onClose: () => void;
  /** This card's own agent-handle base (e.g. `mcp-server-higgsfield`) — this modal's own Close
   *  control publishes as `<cardHandle>-tools-modal-close`, and `cardHandle` is threaded straight
   *  through to `ExternalMcpToolPicker` below, which derives ITS OWN base as `<cardHandle>-tools`
   *  (`toolPickerHandle`) — distinct from this modal's own `-tools-modal*` namespace so the two
   *  never collide, and distinct from the trigger button's own `<cardHandle>-tools-open` in
   *  `ExternalMcpSettingsPanel.tsx`. */
  cardHandle: string;
  /** The probe route's path parameter — see `ExternalMcpToolPicker`'s own `serverId` doc. */
  serverId: string;
  /** Whether the CONNECTION itself is switched on — see `ExternalMcpToolPicker`'s own doc. */
  connectionEnabled: boolean;
  allowedToolNames: string | undefined;
  writeAllowedToolNames: string | undefined;
  saving: boolean;
  onSave: (fields: { allowedToolNames: string; writeAllowedToolNames: string }) => void;
}

export function ExternalMcpToolsModal({
  name,
  onClose,
  cardHandle,
  serverId,
  connectionEnabled,
  allowedToolNames,
  writeAllowedToolNames,
  saving,
  onSave,
}: ExternalMcpToolsModalProps) {
  const { dialogRef, closeRef } = useExternalMcpToolsModalEscape(onClose);
  const t = useT();
  const tDrift = useExternalMcpDriftCopy();
  const titleId = `${cardHandle}-tools-modal-title`;

  return (
    <div className="settings-dialog-backdrop" onClick={onClose}>
      <div
        ref={dialogRef}
        className="settings-dialog external-mcp-tools-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby={titleId}
        onClick={(e) => e.stopPropagation()}
      >
        <div className="external-mcp-tools-modal-head">
          <div>
            <p className="external-mcp-tools-modal-kicker">{tDrift("Tools")}</p>
            <h2 id={titleId}>{name}</h2>
          </div>
          {/* An icon, not a second labelled button (2026-10-13 redesign): the footer's Cancel/Save
              is the dialog's one action area. `aria-label` keeps the accessible name "Close". */}
          <button
            ref={closeRef}
            type="button"
            className="external-mcp-tools-modal-close"
            aria-label={t("Close")}
            onClick={onClose}
            {...agentHandle({ handle: `${cardHandle}-tools-modal-close` }, { role: "button", label: `Close ${name}'s tool permissions` })}
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path d="M4 4l8 8M12 4l-8 8" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
            </svg>
          </button>
        </div>
        <div className="external-mcp-tools-modal-body">
          <ExternalMcpToolPicker
            serverId={serverId}
            active
            connectionEnabled={connectionEnabled}
            allowedToolNames={allowedToolNames}
            writeAllowedToolNames={writeAllowedToolNames}
            saving={saving}
            onSave={onSave}
            onCancel={onClose}
            cardHandle={cardHandle}
          />
        </div>
      </div>
    </div>
  );
}

import { agentHandle } from "@jini-ai/agentic";
import { SecretInput } from "@/components/SecretInput/SecretInput";
import { InfoTip } from "@jini-ai/ui/admin-widgets";

import type { Translate } from "@jini-ai/ui/panel-kit";
import {
  resolveCreateInputDisabled,
  resolveCreateSubmitDisabled,
  useCreateSiteDatabase,
  type SiteDatabaseDisclosure,
} from "./Sites.hooks";
import type { CreateSitePluginTokenField, CreateSitePluginTokensController } from "./hooks/use-create-site-plugin-tokens.hooks";
import type { useWiredSites } from "./hooks/use-sites.hooks";

/**
 * @file The create-a-site form — the body of the **"New site" tab**, not a page of its own.
 *
 * Its CONTENT was ported from Tovu Runner's `CreateWebsiteOnboarding.tsx` and the owner kept it.
 * Its PLACEMENT was not hers and is now corrected: the port also moved creation onto a full-page
 * `?tab=new` screen reached from a header button, which deleted the tab bar she had asked for in
 * words, twice. See `Sites.tsx`'s header for the full sequence and the rule it produced. What
 * changed here is the frame — no back link, no page-title swap, Cancel returns to the first tab —
 * and nothing inside the card.
 *
 * ## What was ported, and what was rebuilt
 *
 * PORTED — the shape and the words: one sectioned card running "Site details" -> "Database" ->
 * actions, with Cancel beside the submit. The three database options keep Runner's own titles and
 * hint wording ("Default · …", "Hosted · requires a project URL and API key", "Any vendor · add its
 * endpoint and credential") so the two products read as one family. Vendor fields now disclose
 * only under their selected radio (owner, 2026-10-08), rather than advertising inputs on every card.
 *
 * REBUILT — everything below the markup. Runner's version is backed by `useCreateWebsiteForm`, with
 * `database` state, `supabaseUrl`/`customProvider`/`customConnection` state, two credential refs,
 * and a `computeCanCreate` that varies by branch. None of that is ported, because Tovu's create
 * call takes a name and optional agent-plugin tokens, and this feature already owns its controller
 * (`use-sites.hooks.ts`). Runner's CSS is not ported either — the classes here are Tovu admin's own
 * tokens, per the dispatch.
 *
 * ## Why Runner can offer three backends and this screen cannot
 *
 * **Site creation is SQLite and only SQLite, and porting Runner's pixels must not port a promise
 * this backend cannot keep.** Verified against the code, not assumed: `initSite`
 * (`apps/website/src/platform/site-dir/init-site.ts`) calls
 * `openContentDb(path.join(target, "content.db"), seed)` — hardcoded, with no dialect anywhere in
 * its input shape; the create route (`server/inbound/admin-http/routes/system/sites.ts`) reads
 * a name (`parseCreateSiteName`) and optional agent-plugin tokens, with no database-provider input;
 * and `schema.postgres.ts`, though a real generated Postgres schema, is reachable only from
 * drift/parity tests. Supabase's Agent Plugin connects app data for the assistant, which is a
 * different feature from provisioning the site's content database.
 *
 * At the original port, Runner rendered all three live because its create screen provisioned
 * nothing — its footer said as much. It carried a `blocked` project status for this case, commented
 * in its own source: *"A blocked project is waiting on database-provider support Tovu does not
 * have, so the only honest affordance is none — starting it would fail every time."* Tovu's button
 * really does create a site. So the same principle Runner states there is applied one step earlier
 * here: the affordance is shown, and it is not live.
 *
 * The guarantee is structural rather than cosmetic. The disclosure hook starts on SQLite and
 * refuses unavailable selections, including a disabled radio forced on in the DOM. The submit
 * handler still calls `createSite()` — a zero-argument function with nowhere to put a dialect.
 * "Chose Supabase, silently received SQLite" has no production code path to travel down, which
 * is the standard the rest of this screen is already held to — see `Sites.tsx`'s header.
 *
 * ## Optional service tokens (2026-09-29; inline disclosure 2026-10-08)
 *
 * Supabase still cannot be the site's CONTENT database, and its database card still says so. What
 * works is connecting the Supabase Agent Plugin, so the assistant can make and manage a Supabase
 * database for the site's app data. The existing token controller (`use-create-site-plugin-tokens
 * .hooks.ts`) remains the owner; its Supabase field appears only under a selected Supabase radio.
 * Empty means skip; the site is created as before and the assistant can connect it later from chat.
 * There is no standalone section. Production's unavailable hosted radios keep their fields hidden,
 * matching desktop's availability policy without inventing a hosted content provisioner.
 *
 * ## Chat data
 *
 * "Chats always use SQLite" is literally true and deliberate rather than a simplification: chat
 * history lives in a separate `chat.db` sidecar (`platform/db/sqlite/chat-db.ts`), specifically so
 * a whole-file restore or duplicate of `content.db` can never carry — or erase — conversation
 * history.
 *
 * ## Guards
 *
 * All three create-form guards survive this move as they survived the last one, each with its own
 * test: the name field disables while a create is in flight or switching is off ({@link
 * resolveCreateInputDisabled}), the submit button keeps its four-condition guard ({@link
 * resolveCreateSubmitDisabled}), and every edit still routes through the controller's own
 * `setCreateName` rather than a local copy — which is also what clears the confirmation line.
 *
 * ## Where the "Created." line went
 *
 * To `AllSitesTab`. A successful create now returns to the "All sites" tab (the owner's own
 * requirement: *"That should go back to the first tab, and then we should see the new website
 * created there"*), so a confirmation rendered in this footer could only ever be seen in the state
 * where it is STALE — an operator coming back to this tab after a create, with the field already
 * cleared. The confirmation belongs where the new card is.
 */

export interface CreateSiteOnboardingProps {
  controller: Pick<
    ReturnType<typeof useWiredSites>,
    "createName" | "setCreateName" | "createNameError" | "createSite" | "creating" | "switchingEnabled" | "pluginTokens" | "t" | "adminPassword" | "setAdminPassword" | "shownStarterPassword"
  >;
  /** Back to the "All sites" tab, creating nothing. Supplied by `Sites.tsx` so this form owns no
   *  routing of its own — same seam Runner's own `onBack` is. */
  onCancel: () => void;
  /** Hook injection follows desktop's form seam; production retains its SQLite-only capabilities. */
  useDatabase?: typeof useCreateSiteDatabase;
}

/** The vendor fields Runner shows under its "Custom" option, every control `readOnly`, so the shape
 *  of the eventual flow is visible when selected without collecting a credential this product has
 *  nowhere to put. (Supabase's inert URL/key fields were removed on 2026-09-29: the working way to
 *  bring Supabase is the token field under its selected radio.) Read-only inputs can receive
 *  disclosure focus without collecting a credential this backend cannot use. */
function CustomVendorFields({ t, id }: { t: Translate; id: string }) {
  return (
    <span className="site-db-vendor" id={id}>
      <span className="field">
        <label className="field-label" htmlFor="site-db-custom-provider">
          {t("Provider name")}
        </label>
        <input id="site-db-custom-provider" readOnly autoFocus placeholder={t("e.g. Neon, PlanetScale, Turso")} />
      </span>
      <span className="field">
        <label className="field-label" htmlFor="site-db-custom-connection">
          {t("Connection string or API endpoint")}
        </label>
        <input id="site-db-custom-connection" readOnly placeholder="https://… or postgres://…" autoComplete="off" />
        <span className="field-hint">{t("Shown for what's coming. It isn't stored anywhere yet.")}</span>
      </span>
    </span>
  );
}

/**
 * One database option.
 *
 * A `<div>` with sibling `<label htmlFor>`s rather than Runner's wrapping `<label>`: the two vendor
 * options each carry their own labelled controls, and a `<label>` nested inside another `<label>`
 * is invalid HTML whose accessible-name resolution is genuinely ambiguous. SQLite is built the same
 * way for symmetry.
 *
 * `available` decides both the radio's `disabled` and the status pill, from one source — so a card
 * cannot render as choosable while being refused, or vice versa.
 */
function DatabaseOption({ option, pluginTokens, t }: { option: SiteDatabaseDisclosure; pluginTokens: CreateSitePluginTokensController; t: Translate }) {
  return (
    <div className={option.className}>
      <input
        type="radio"
        id={option.inputId}
        name="site-db"
        value={option.id}
        checked={option.selected}
        disabled={option.disabled}
        aria-disabled={option.ariaDisabled}
        aria-expanded={option.ariaExpanded}
        aria-controls={option.ariaControls}
        onChange={option.onSelect}
      />
      <span className="site-db-option-text">
        <span className="site-db-option-head">
          <label className="site-db-option-name" htmlFor={option.inputId}>
            {option.title}
          </label>
          <span className={option.statusClassName}>
            {option.statusLabel}
          </span>
        </span>
        <span className="site-db-option-note">{option.hint}</span>
        {option.showCustomFields && <CustomVendorFields t={t} id={option.disclosureId} />}
        {option.tokenField && <PluginTokenField field={option.tokenField} id={option.disclosureId} onChange={pluginTokens.setToken} t={t} />}
      </span>
    </div>
  );
}

/** The "Database" section. Runner's own section blurb, plus the one sentence Runner has no need for
 *  — the reason two of its three options are inert here. */
function DatabaseSection({ t, database, pluginTokens }: { t: Translate; database: ReturnType<typeof useCreateSiteDatabase>; pluginTokens: CreateSitePluginTokensController }) {
  return (
    <fieldset className="onboarding-section site-db-fieldset">
      <legend className="onboarding-section-title">{t("Database")}</legend>
      <div className="onboarding-section-head">
        <p className="onboarding-section-lead">{t("SQLite is the zero-configuration default. Bring a hosted vendor when you need one.")}</p>
      </div>
      <div
        className="site-db-options"
        {...agentHandle({ handle: "sites-create-database" }, {
          role: "region",
          label: "Which database backs the new site — SQLite is the only one Tovu can create today",
        })}
      >
        {database.options.map((option) => (
          <DatabaseOption key={option.id} option={option} pluginTokens={pluginTokens} t={t} />
        ))}
      </div>
      <p className="field-hint">{t("Tovu creates every site's content database as SQLite today, so the other two can't be chosen yet. Chats always use SQLite, in a separate chat.db — restoring content never touches conversation history.")}</p>
    </fieldset>
  );
}

/** One optional service's token field. The token is typed into a password input and sent only with
 *  the create request. */
function PluginTokenField({ field, id, onChange, t }: { field: CreateSitePluginTokenField; id: string; onChange: (pluginId: string, value: string) => void; t: Translate }) {
  return (
    <span className="site-db-vendor" id={id}>
      <span className="site-db-option-text">
        <span className="site-db-option-head">
          <label className="field-label" htmlFor="site-key-supabase">
            {t("Paste an access token")}
          </label>
          <span className="status status-neutral">{t("Optional")}</span>
        </span>
        <span className="field">
          {/* `new-password`, not `off` — see `security/AccessTokensTab.tsx`'s token input. */}
          <SecretInput
            label={t("Paste an access token")}
            id="site-key-supabase"
            value={field.token}
            placeholder={t("Paste an access token")}
            autoComplete="new-password"
            autoFocus
            onChange={(e) => onChange(field.pluginId, e.target.value)}
            {...agentHandle({ handle: `sites-create-token-${field.pluginId}` }, { role: "field", label: `Optional ${field.displayName} access token for the new site` })}
          />
          <span className="field-hint">
            <a href={field.helpUrl} target="_blank" rel="noopener noreferrer">
              {t("Create a token")}
            </a>{" "}
            {t("No token? Leave it empty. You can ask the assistant to connect it later.")}
          </span>
        </span>
      </span>
    </span>
  );
}

/** The "Site details" section — Runner's "Website details", named for what this product calls the
 *  thing. The hint is Runner's ("This becomes the isolated local workspace folder") rewritten for
 *  the fact that in Tovu the name IS the folder, not a slug derived from one. */
function DetailsSection({ controller }: { controller: CreateSiteOnboardingProps["controller"] }) {
  const { createName, setCreateName, createNameError, creating, switchingEnabled, t } = controller;
  return (
    <div className="onboarding-section">
      <div className="onboarding-section-head">
        <h3 className="onboarding-section-title">{t("Site details")}</h3>
        <p className="onboarding-section-lead">{t("Name the isolated workspace folder for this site.")}</p>
      </div>
      <div className="field">
        <label className="field-label" htmlFor="site-name">
          {t("Folder name")}
        </label>
        <input
          id="site-name"
          name="name"
          className="site-name-input"
          value={createName}
          disabled={resolveCreateInputDisabled({ creating, switchingEnabled })}
          placeholder="my-second-site"
          autoComplete="off"
          onChange={(e) => setCreateName(e.target.value)}
          {...agentHandle({ handle: "sites-create-name" }, { role: "field", label: "New site folder name" })}
        />
        {createNameError ? (
          <p className="field-error">{createNameError}</p>
        ) : (
          <p className="field-hint">{t("Lowercase letters, digits, and dashes. This becomes the folder under sites/.")}</p>
        )}
      </div>
    </div>
  );
}

/** The card's footer: the restart truth, then Cancel and the submit — Runner's own `onboarding__
 *  actions` shape, where a sentence about what will actually happen sits beside the buttons.
 *  Creating never switches the running server, and this is the moment an operator would otherwise
 *  assume it did. */
function OnboardingActions({ controller, onCancel }: CreateSiteOnboardingProps) {
  const { createName, createNameError, creating, switchingEnabled, t } = controller;
  return (
    <footer className="onboarding-actions">
      <p className="onboarding-actions-note">{t("Creating a site never switches this server onto it. Activate it from All sites, then restart.")}</p>
      <div className="onboarding-actions-buttons">
        <button type="button" className="btn-secondary" onClick={onCancel} {...agentHandle({ handle: "sites-create-cancel" }, { role: "button", label: "Go back to the site list without creating anything" })}>
          {t("Cancel")}
        </button>
        <button
          type="submit"
          disabled={resolveCreateSubmitDisabled({ creating, switchingEnabled, createNameError, createName })}
          {...agentHandle({ handle: "sites-create-submit" }, { role: "button", label: "Create the site folder" })}
        >
          {creating ? t("Creating…") : t("Create site")}
        </button>
      </div>
    </footer>
  );
}

export function CreateSiteOnboarding({ controller, onCancel, useDatabase = useCreateSiteDatabase }: CreateSiteOnboardingProps) {
  const database = useDatabase({ t: controller.t, pluginTokens: controller.pluginTokens });
  return (
    <form
      className="onboarding"
      {...agentHandle({ handle: "sites-create-form" }, { role: "form", label: "Create a new site folder under sites/" })}
      onSubmit={(e) => {
        e.preventDefault();
        controller.createSite();
      }}
    >
      <div className="onboarding-card">
        <DetailsSection controller={controller} />
        <div className="onboarding-section">
          <p className="field-hint site-admin-login-hint">
            {/* Shown while the field below is blank (owner, 2026-10-22): the value comes from the
                sites listing, never from this bundle — see `default-credential-exposure.ts`. */}
            {controller.shownStarterPassword ? (
              <>
                {controller.t("Starter login:")} <strong>admin</strong> / <strong className="site-admin-starter-password" data-agent-private="">{controller.shownStarterPassword}</strong>.{" "}
                {controller.t("Change it under Users before you deploy.")}
              </>
            ) : null}
            <InfoTip
              label={controller.t("This is a starter password for this site only. Change it after your first sign-in under Users → admin, or set a different one below.")}
              triggerLabel={controller.t("About the default admin login")}
              agentHandle="sites-create-admin-login-info"
            />
          </p>
          <div className="field">
            <label className="field-label" htmlFor="site-admin-password">{controller.t("Set a different admin password")}</label>
            <SecretInput
              label={controller.t("Set a different admin password")}
              id="site-admin-password"
              value={controller.adminPassword}
              minLength={1}
              maxLength={512}
              autoComplete="new-password"
              disabled={resolveCreateInputDisabled(controller)}
              onChange={(e) => controller.setAdminPassword(e.target.value)}
              {...agentHandle({ handle: "sites-create-admin-password" }, { role: "field", label: "Optional admin password for the new site" })}
              toggleAttrs={agentHandle({ handle: "sites-create-admin-password-reveal" }, { role: "button", label: "Show or hide the new site's admin password" })}
            />
          </div>
        </div>
        <DatabaseSection t={controller.t} database={database} pluginTokens={controller.pluginTokens} />
        <OnboardingActions controller={controller} onCancel={onCancel} />
      </div>
    </form>
  );
}

import { useRef } from "react";
import { DataTable } from "@jini-ai/admin/react";
import { SecretInput } from "@/components/SecretInput/SecretInput";
import { agentHandle } from "@jini-ai/agentic";
import { FileDropzone } from "@jini-ai/ui";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { formatTimestamp, interpolate, type Translate } from "@jini-ai/ui/panel-kit";
import type { SiteImport } from "./hooks/site-transfer-dependencies.hooks";
import { CredentialWarningList, TransferNoticeTip, credentialSummary } from "./CredentialWarnings";
import { useWiredSiteImport, type SiteImportController } from "./hooks/use-site-transfer.hooks";
import { useWiredLiveImportSite, type LiveImportSiteController } from "./hooks/use-live-import-site.hooks";
import { useDesktopImport, type DesktopImportController } from "./hooks/use-desktop-import.hooks";
import { formatTransferBytes, importOptionsTip, importSourceLabel, importStateView, liveImportMode } from "./site-transfer-rules";

/**
 * @file The "Import Site" screen (owner, 2026-10-18; on Sites, then the Import & Export page's
 * Import tab from 2026-10-25). Two ways in, under one ⓘ:
 * - a Tovu share link or `.tovu.zip` becomes a NEW site, then the new owner's password is chosen
 *   here (the backend's needs-owner step; the password never goes through an agent tool);
 * - a live website goes to the existing `site-import` agent plugin as a drafted assistant request.
 *   v1 (coordinator, 2026-10-18) imported into THIS site, with a New site link. Since 2026-11-10
 *   (owner) it makes a NEW site first, as the desktop app does, and the request is drafted on that
 *   site ({@link useWiredLiveImportSite}); it never imports into the site this page belongs to.
 *   Inside the desktop app, which can't make a site here, it hands off to the app's own Import tab
 *   with the typed address instead ({@link useDesktopImport}, owner 2026-11-10).
 * Files come before web addresses, as on the desktop app's Import page (owner, 2026-11-10).
 * Then the list of past imports. Markup only; every effect is in {@link useWiredSiteImport}.
 */

export interface SiteImportTabProps {
  t: Translate;
  /** Test seam, same convention as `SitesProps.useSitesHook`. */
  useImport?: typeof useWiredSiteImport;
  /** Same seam, for the live website's new site. */
  useLiveSite?: typeof useWiredLiveImportSite;
  /** Same seam, for the desktop app's Import tab hand-off. */
  useDesktop?: typeof useDesktopImport;
  /** Whether this host can make a new site. Off where this deployment has no Sites section (the
   *  desktop app, a hosted install): a live website is then not offered, except on the site made for it,
   *  or inside the desktop app, where it hands off to the app's own Import tab. */
  canMakeSites?: boolean;
}

export function SiteImportTab({ t, useImport = useWiredSiteImport, useLiveSite = useWiredLiveImportSite, useDesktop = useDesktopImport, canMakeSites = false }: SiteImportTabProps) {
  const controller = useImport({ t });
  const liveSite = useLiveSite({ t });
  const desktop = useDesktop({ t });
  const mode = liveImportMode({ arrivedForImport: controller.arrivedForImport, canMakeSites }, { desktopImport: desktop.available });
  return (
    <section className="site-transfer" aria-label={t("Import Site")}>
      <div className="site-transfer-head">
        <p className="onboarding-section-lead site-transfer-lead">
          {t("Bring in a site from a Tovu export or a live website.")}
          <InfoTip label={importOptionsTip(t)} triggerLabel={t("About importing")} placement="inline" agentHandle="sites-import-info" />
        </p>
      </div>
      <ImportProgress controller={controller} t={t} />
      <div className="onboarding-card">
        <ArchiveSource controller={controller} t={t} />
        {mode === "desktop"
          ? <DesktopImportSource controller={controller} desktop={desktop} t={t} />
          : <LiveWebsiteSource controller={controller} liveSite={liveSite} mode={mode} t={t} />}
      </div>
      <h3 className="site-transfer-subtitle">{t("Past imports")}</h3>
      <ImportList controller={controller} t={t} />
    </section>
  );
}

/** Opens the drop zone's own file picker, so the button and a click on the zone are one flow. */
function openZonePicker(zone: HTMLElement | null): void {
  zone?.querySelector<HTMLInputElement>('input[type="file"]')?.click();
}

/** "From a .tovu.zip or share link": a file OR a link, one Import button. */
function ArchiveSource({ controller, t }: { controller: SiteImportController; t: Translate }) {
  const zone = useRef<HTMLDivElement>(null);
  return (
    <form
      className="onboarding-section"
      onSubmit={(event) => {
        event.preventDefault();
        void controller.startImport();
      }}
      {...agentHandle({ handle: "sites-import-archive-form" }, { role: "form", label: "Import a Tovu share link or .tovu.zip as a new site" })}
    >
      <div className="onboarding-section-head">
        <h3 className="onboarding-section-title">{t("From a .tovu.zip or share link")}</h3>
        <p className="onboarding-section-lead">{t("Makes a new site. This site stays as it is.")}</p>
      </div>
      {controller.file ? (
        <div className="site-transfer-file">
          <span className="site-transfer-file-name">{controller.file.name}</span>
          <span className="site-transfer-num">{formatTransferBytes(controller.file.size)}</span>
          <button type="button" className="btn-secondary" disabled={controller.importing} onClick={controller.clearFile}
