            {t("Remove")}
          </button>
        </div>
      ) : (
        <div className="site-transfer-drop" ref={zone}>
          <FileDropzone
            accept=".zip,application/zip"
            prompt={t("Drop a .tovu.zip here, or click to browse")}
            helper={t("Up to 300 MB")}
            onFiles={controller.chooseFiles}
          />
          <button type="button" className="btn-secondary" disabled={controller.importing} onClick={() => openZonePicker(zone.current)}
            {...agentHandle({ handle: "sites-import-file-choose" }, { role: "button", label: "Choose a .tovu.zip file to import" })}>
            {t("Choose file…")}
          </button>
        </div>
      )}
      <p className="site-transfer-or">{t("or")}</p>
      <div className="field">
        <label className="field-label" htmlFor="sites-import-link">{t("Share link")}</label>
        <input
          id="sites-import-link"
          type="url"
          inputMode="url"
          placeholder="https://"
          value={controller.link}
          disabled={controller.importing}
          onChange={(event) => controller.setLink(event.target.value)}
          {...agentHandle({ handle: "sites-import-link" }, { role: "field", label: "Tovu share link to import" })}
        />
      </div>
      {controller.importError ? <div className="notice error" role="alert">{controller.importError}</div> : null}
      <div className="site-transfer-actions">
        <button type="submit" className="btn-primary" disabled={!controller.canImport || controller.importing} aria-busy={controller.importing}
          {...agentHandle({ handle: "sites-import-start" }, { role: "button", label: "Import the link or zip as a new site" })}>
          {controller.importing ? <span className="site-transfer-spinner" aria-hidden="true" /> : null}
          {controller.importing ? t("Importing…") : t("Import as a new site")}
        </button>
      </div>
    </form>
  );
}

/** "From a live website": makes a NEW site and opens it with the request drafted; on that new site
 *  itself, hands the drafted request to the assistant; the owner presses Send. */
function LiveWebsiteSource({ controller, liveSite, mode, t }: {
  controller: SiteImportController; liveSite: LiveImportSiteController; mode: Exclude<ReturnType<typeof liveImportMode>, "desktop">; t: Translate;
}) {
  if (mode === "unavailable") {
    return (
      <div className="onboarding-section">
        <div className="onboarding-section-head">
          <h3 className="onboarding-section-title">{t("From a live website")}</h3>
          <p className="onboarding-section-lead">{t("This host can't make new sites, so it can't import a live website here.")}</p>
        </div>
      </div>
    );
  }
  const newSite = mode === "new-site";
  return (
    <form
      className="onboarding-section"
      onSubmit={(event) => {
        event.preventDefault();
        if (newSite) void liveSite.start(controller.liveAddress);
        else controller.startLiveImport();
      }}
      {...agentHandle({ handle: "sites-import-live-form" }, { role: "form", label: "Import a live website into a new site with the assistant" })}
    >
      <div className="onboarding-section-head">
        <h3 className="onboarding-section-title">{t("From a live website")}</h3>
        <p className="onboarding-section-lead">{newSite ? t("Makes a new site. This site stays as it is.") : t("Imports into this new site.")}</p>
      </div>
      <div className="field">
        <label className="field-label" htmlFor="sites-import-live-address">{t("Website address")}</label>
        <input
          id="sites-import-live-address"
          type="url"
          inputMode="url"
          placeholder="https://"
          value={controller.liveAddress}
          disabled={liveSite.creating}
          aria-describedby="sites-import-live-hint"
          onChange={(event) => controller.setLiveAddress(event.target.value)}
          {...agentHandle({ handle: "sites-import-live-address" }, { role: "field", label: "Address of the live website to import" })}
        />
        <p className="field-hint" id="sites-import-live-hint">
          {newSite ? t("The new site opens with the request written. Press Send there to start.") : t("The assistant opens with the request written. Press Send to start.")}
        </p>
      </div>
      {liveSite.error ? <div className="notice error" role="alert">{liveSite.error}</div> : null}
      <div className="site-transfer-actions">
        <button type="submit" className="btn-secondary" disabled={!controller.liveAddressValid || liveSite.creating} aria-busy={liveSite.creating}
          {...agentHandle({ handle: "sites-import-live-start" }, { role: "button", label: newSite ? "Make a new site and open its assistant with the import request" : "Open the assistant with the import request" })}>
          {liveSite.creating ? <span className="site-transfer-spinner" aria-hidden="true" /> : null}
          {liveSite.creating ? t("Creating…") : t("Import with the assistant")}
        </button>
      </div>
    </form>
  );
}

/** "From a live website" inside the desktop app: the app's own Import tab makes the site, so this
 *  only opens it, passing the address when one is typed. An address it would refuse keeps the button off. */
function DesktopImportSource({ controller, desktop, t }: { controller: SiteImportController; desktop: DesktopImportController; t: Translate }) {
  const address = controller.liveAddress.trim();
  const refused = address !== "" && !controller.liveAddressValid;
  return (
    <form
      className="onboarding-section"
      onSubmit={(event) => {
        event.preventDefault();
        void desktop.open(address);
      }}
      {...agentHandle({ handle: "sites-import-live-form" }, { role: "form", label: "Open Tovu's Import tab for a live website" })}
    >
      <div className="onboarding-section-head">
        <h3 className="onboarding-section-title">{t("From a live website")}</h3>
        <p className="onboarding-section-lead">{t("Tovu's Import tab makes a new site from it.")}</p>
      </div>
      <div className="field">
        <label className="field-label" htmlFor="sites-import-live-address">{t("Website address")}</label>
        <input
          id="sites-import-live-address"
          type="url"
          inputMode="url"
          placeholder="https://"
          value={controller.liveAddress}
          disabled={desktop.opening}
          onChange={(event) => controller.setLiveAddress(event.target.value)}
          {...agentHandle({ handle: "sites-import-live-address" }, { role: "field", label: "Address of the live website to import" })}
        />
      </div>
      {desktop.error ? <div className="notice error" role="alert">{desktop.error}</div> : null}
      <div className="site-transfer-actions">
        <button type="submit" className="btn-secondary" disabled={refused || desktop.opening} aria-busy={desktop.opening}
          {...agentHandle({ handle: "sites-import-live-desktop" }, { role: "button", label: "Open Tovu's Import tab with this address" })}>
          {t("Open Import in Tovu")}
        </button>
      </div>
    </form>
  );
}

/** The import just started or resumed: the new owner's password step, then Open. */
function ImportProgress({ controller, t }: { controller: SiteImportController; t: Translate }) {
  const current = controller.current;
  if (!current) return null;
  const name = current.newSiteName ?? t("the new site");
  if (current.state === "needs-owner") return <OwnerStep controller={controller} name={name} t={t} />;
  if (current.state === "failed") return <div className="notice error" role="alert">{current.error ?? t("Import failed. No site was changed.")}</div>;
  if (current.state === "ready") {
    return (
      <div className="notice site-transfer-done" role="status">
        <span className="site-transfer-status">{interpolate({ template: t("{name} is ready."), vars: { name } })}</span>
        <CurrentImportNotices item={current} t={t} />
        {current.adminUrl ? (
          <a className="btn-primary" href={current.adminUrl} target="_blank" rel="noreferrer"
            {...agentHandle({ handle: "sites-import-open" }, { role: "link", label: "Open the imported site's admin" })}>
            {t("Open")}
          </a>
        ) : <span>{t("Start it from All sites to open its admin.")}</span>}
      </div>
    );
  }
  return <div className="notice" role="status">{t("Checking the archive…")}</div>;
}

/** Confirmation must match a nonempty password before the owner setup can be submitted. */
function importOwnerPasswordReady({ password, confirm }: Pick<SiteImportController, "password" | "confirm">): boolean {
  return password.length > 0 && confirm === password;
}

function OwnerStep({ controller, name, t }: { controller: SiteImportController; name: string; t: Translate }) {
  const ready = importOwnerPasswordReady(controller);
  return (
    <form
      className="onboarding-card site-transfer-owner"
      onSubmit={(event) => {
        event.preventDefault();
        void controller.completeOwner();
      }}
      {...agentHandle({ handle: "sites-import-owner-form" }, { role: "form", label: "Choose the imported site's owner password" })}
    >
      <div className="onboarding-section">
        <div className="onboarding-section-head">
          <h3 className="onboarding-section-title">{interpolate({ template: t("Choose a password for {name}"), vars: { name } })}</h3>
          <p className="onboarding-section-lead">{t("The site opens once it has an owner password. Username: admin")}</p>
        </div>
        <CurrentImportNotices item={controller.current} t={t} />
        <div className="field">
          <label className="field-label" htmlFor="sites-import-owner-password">{t("Password")}</label>
          <SecretInput label={t("Password")} id="sites-import-owner-password" autoComplete="new-password" maxLength={512} value={controller.password}
            // It appears in answer to Import or Finish setup, often above the button pressed: focus
            // brings it into view and puts the cursor where the next keystroke belongs.
            autoFocus
            disabled={controller.settingOwner} onChange={(event) => controller.setPassword(event.target.value)} />
        </div>
        <div className="field">
          <label className="field-label" htmlFor="sites-import-owner-confirm">{t("Confirm password")}</label>
          <SecretInput label={t("Confirm password")} id="sites-import-owner-confirm" autoComplete="new-password" maxLength={512} value={controller.confirm}
            disabled={controller.settingOwner} aria-invalid={controller.passwordProblem ? true : undefined}
            aria-describedby={controller.passwordProblem ? "sites-import-owner-problem" : undefined}
            onChange={(event) => controller.setConfirm(event.target.value)} />
          {controller.passwordProblem ? <p className="field-error" id="sites-import-owner-problem">{controller.passwordProblem}</p> : null}
        </div>
        {controller.current?.hasEncryptedKeys ? (
          <div className="field">
            <label className="field-label" htmlFor="sites-import-saved-keys-password">{t("Saved keys password")}</label>
            <SecretInput label={t("Saved keys password")} id="sites-import-saved-keys-password" autoComplete="new-password" maxLength={512}
              value={controller.savedKeysPassword} disabled={controller.settingOwner}
              onChange={event => controller.setSavedKeysPassword(event.target.value)} />
          </div>
        ) : null}
        {controller.ownerError ? <div className="notice error" role="alert">{controller.ownerError}</div> : null}
        <div className="site-transfer-actions">
          <button type="submit" className="btn-primary" disabled={!ready || controller.settingOwner} aria-busy={controller.settingOwner}
            {...agentHandle({ handle: "sites-import-owner-submit" }, { role: "button", label: "Create the imported site with this password" })}>
            {controller.settingOwner ? t("Creating…") : t("Create site")}
          </button>
        </div>
      </div>
    </form>
  );
}

function ImportList({ controller, t }: { controller: SiteImportController; t: Translate }) {
  if (controller.listError) return <div className="notice error">{controller.listError}</div>;
  if (!controller.imports) return <div className="notice">{t("Loading imports…")}</div>;
  return (
    <DataTable
      rows={controller.imports}
      rowKey={(item) => item.importId}
      label={t("Past imports")}
      empty={<div className="sites-empty"><p className="sites-empty-lead">{t("No imports yet.")}</p></div>}
      rowDetail={(item) => item.credentialWarnings?.length ? <div className="site-transfer-detail"><CredentialWarningList warnings={item.credentialWarnings} t={t} /></div> : null}
      columns={[
        { key: "date", header: t("Date"), cellClassName: "site-transfer-num", cell: (item) => formatTimestamp({ iso: item.createdAt }, { timeZone: "local" }) },
        { key: "source", header: t("Source"), cell: (item) => "url" in item.source ? <span className="site-transfer-link" title={item.source.url}>{importSourceLabel(item.source, t)}</span> : importSourceLabel(item.source, t) },
        { key: "site", header: t("New site"), cell: (item) => item.newSiteName ?? <span className="muted-cell">—</span> },
        {
          key: "status",
          header: t("Status"),
          cell: (item) => {
            const view = importStateView(item.state, t);
            return <span className="site-transfer-status"><span className={view.className}>{view.label}</span><TransferNoticeTip notices={importRowNotices({ item, t })} t={t} /></span>;
          },
        },
        { key: "actions", headerLabel: t("Actions"), cell: (item, index) => <ImportAction item={item} index={index} controller={controller} t={t} /> },
      ]}
    />
  );
}

/** The import's warning sign: its own warnings, plus where credentials may be. @complexity O(n) warnings. */
function importRowNotices({ item, t }: { item: SiteImport; t: Translate }, _options = {}): readonly string[] {
  const warnings = item.warnings ?? [];
  if (!item.credentialWarnings?.length) return warnings;
  return [...warnings, credentialSummary({ subject: "import", warnings: item.credentialWarnings, t })];
}

/** What the import just made warns about, before its row reaches the list; never blocks its setup. */
function CurrentImportNotices({ item, t }: { item: SiteImport | null | undefined; t: Translate }) {
  if (!item) return null;
  const notices = importRowNotices({ item, t });
  if (!notices.length) return null;
  return (
    <div className="site-transfer-detail">
      <TransferNoticeTip notices={notices} t={t} />
      <CredentialWarningList warnings={item.credentialWarnings ?? []} t={t} />
    </div>
  );
}

function ImportAction({ item, index, controller, t }: { item: SiteImport; index: number; controller: SiteImportController; t: Translate }) {
  if (item.state === "needs-owner") {
    return (
      <button type="button" className="btn-secondary" onClick={() => controller.resume(item)}
        {...agentHandle({ handle: `sites-import-${index + 1}-finish` }, { role: "button", label: "Finish this import's owner password step" })}>
        {t("Finish setup")}
      </button>
    );
  }
  if (item.state === "ready" && item.adminUrl) {
    return (
      <a className="btn-secondary" href={item.adminUrl} target="_blank" rel="noreferrer"
        {...agentHandle({ handle: `sites-import-${index + 1}-open` }, { role: "link", label: "Open this imported site's admin" })}>
        {t("Open")}
      </a>
    );
  }
  return <span className="muted-cell">—</span>;
}

import { useId, type ReactNode } from "react";
import { interpolate, type Translate } from "@jini-ai/ui/panel-kit";
import { SettingsDialogShell } from "@jini-ai/ui";
import { InfoTip } from "@jini-ai/ui/admin-widgets";
import { useSitesConfig } from "./hooks/use-sites-config.hooks";

type SitesSettings = ReturnType<typeof useSitesConfig>;

/** Jini supplies settings dialog chrome; the hook owns loading, drafts, saving and remedies.
 *
 *  Layout (2026-10-09, owner: "awful ui"): the entry point is a quiet secondary button at the right
 *  end of the Sites tab row (`tabs` is that row's `TabBar`), not a full-width primary bar. The dialog
 *  is a stacked form — label above, capped control, one hint line or an ⓘ — with the config path as
 *  a muted footer beside Save. Every control and sentence the flat version had is still here. */
export function SitesHomeSetting({ home: _home, tabs, useSettings = useSitesConfig, t = (key) => key }: { home: string; tabs?: ReactNode; useSettings?: typeof useSitesConfig; t?: Translate }) {
  const settings = useSettings({});
  return <>
    <div className="sites-tabs-row">
      {tabs}
      <button type="button" className="btn-secondary sites-settings-button" onClick={settings.show}><GearIcon />{t("Sites settings")}</button>
    </div>
    <SitesSyncWarning settings={settings} t={t} />
    {settings.error && !settings.open && <p className="notice error" role="alert">{settings.error}</p>}
    {settings.open && <SettingsDialogShell onClose={settings.close} fullscreenEnabled={false} dialogAriaLabelledBy="sites-settings-title" className="sites-settings-dialog"
      tabs={[{ id: "sites", label: t("Sites"), title: t("Sites settings"), panel: <SitesSettingsForm settings={settings} t={t} /> }]} />}
  </>;
}

/** The cloud-sync warning and its two remedies; nothing when the folder is not synced. */
function SitesSyncWarning({ settings, t }: { settings: SitesSettings; t: Translate }) {
  const warning = settings.config?.warning;
  if (!warning) return null;
  return (
    <div className="notice warning sites-sync-warning" role="alert">
      <p>{interpolate({ template: t(settings.config?.databases === "appData" ? "{provider} syncs this folder. New databases use app-data for safety." : "{provider} syncs this folder. Store databases in app-data to prevent corruption."), vars: { provider: warning.provider } })}</p>
      <div className="sites-sync-warning-actions">
        <button type="button" className="btn-primary" disabled={settings.saving} onClick={() => void settings.useAppData()}>{t("Store databases in app-data")}</button>
        <button type="button" className="btn-secondary" disabled={settings.saving || settings.config?.overrides.sitesHome} onClick={() => void settings.useLocalHome()}>{interpolate({ template: t("Use {path}"), vars: { path: warning.localHome } })}</button>
      </div>
    </div>
  );
}

function SitesSettingsForm({ settings, t }: { settings: SitesSettings; t: Translate }) {
  const id = useId();
  return (
    <form className="sites-settings-form" onSubmit={(event) => { event.preventDefault(); void settings.save(); }}>
      <SitesHomeField settings={settings} id={id} t={t} />
      <SitesRootsField settings={settings} t={t} />
      <SitesDatabasesField settings={settings} id={id} t={t} />
      {settings.error && <p className="notice error" role="alert">{settings.error}</p>}
      <SitesSettingsFooter settings={settings} t={t} />
    </form>
  );
}

/** The "{name} overrides this setting." hint under a field an environment variable pins. */
function OverrideHint({ name, t }: { name: string; t: Translate }) {
  return <p className="field-hint">{interpolate({ template: t("{name} overrides this setting."), vars: { name } })}</p>;
}

/** The new-websites folder; read-only (with its hint) while `TOVU_SITES_HOME` pins it. */
function SitesHomeField({ settings, id, t }: { settings: SitesSettings; id: string; t: Translate }) {
  const overridden = settings.config?.overrides.sitesHome;
  return (
    <div className="sites-settings-field">
      <FieldLabel htmlFor={`${id}-home`} label={t("New websites folder")} info={t("New sites are created in this folder. Existing site folders stay where they are.")} handle="sites-settings-home-info" t={t} />
      <input id={`${id}-home`} className="field-mono" value={settings.home} title={settings.home} spellCheck={false} autoComplete="off"
        disabled={overridden} onChange={(event) => settings.setHome(event.target.value)} />
      {overridden && <OverrideHint name="TOVU_SITES_HOME" t={t} />}
    </div>
  );
}

/** The extra sites folders group; its rows are disabled (with a hint) while `TOVU_SITE_ROOTS` pins them. */
function SitesRootsField({ settings, t }: { settings: SitesSettings; t: Translate }) {
  const overridden = settings.config?.overrides.siteRoots ?? false;
  return (
    <fieldset className="sites-settings-field">
      <legend><FieldLabel label={t("Extra sites folders")} info={t("Sites inside these folders are listed here too.")} handle="sites-settings-roots-info" t={t} /></legend>
      <SitesRootRows settings={settings} disabled={overridden} t={t} />
      {overridden && <OverrideHint name="TOVU_SITE_ROOTS" t={t} />}
    </fieldset>
  );
}

/** Where new databases go: inside each site folder, or the OS app-data folder. */
function SitesDatabasesField({ settings, id, t }: { settings: SitesSettings; id: string; t: Translate }) {
  return (
    <div className="sites-settings-field">
      <FieldLabel htmlFor={`${id}-databases`} label={t("Database location")} info={t("App-data site folders are not self-contained. Transfer their databases too.")} handle="sites-settings-databases-info" t={t} />
      <select id={`${id}-databases`} value={settings.databases} onChange={(event) => settings.setDatabases(event.target.value as "inSite" | "appData")}>
        <option value="inSite">{t("Inside each site (data.nosync)")}</option><option value="appData">{t("OS app-data")}</option>
      </select>
      <p className="field-hint">{t("Existing databases keep their location. Stop the site before moving databases.")}</p>
    </div>
  );
}

/** The config path as a muted footer beside Save; Save waits for the config to load. */
function SitesSettingsFooter({ settings, t }: { settings: SitesSettings; t: Translate }) {
  return (
    <div className="sites-settings-footer">
      {settings.config && <p className="sites-settings-saved-in" title={settings.config.configPath}>{interpolate({ template: t("Saved in {path}"), vars: { path: settings.config.configPath } })}</p>}
      <button type="submit" className="btn-primary" disabled={settings.saving || !settings.config}>{t("Save")}</button>
    </div>
  );
}

/** A field's label with its ⓘ. `htmlFor` is omitted inside a `<legend>`, which labels its group. */
function FieldLabel({ htmlFor, label, info, handle, t }: { htmlFor?: string; label: string; info: string; handle: string; t: Translate }) {
  return (
    <span className="sites-settings-label">
      {htmlFor ? <label htmlFor={htmlFor}>{label}</label> : <span>{label}</span>}
      <InfoTip label={info} placement="inline" triggerLabel={interpolate({ template: t("About {name}"), vars: { name: label } })} agentHandle={handle} />
    </span>
  );
}

/** One row per extra folder, each removable, then "Add folder". Blank rows are dropped on save. */
function SitesRootRows({ settings, disabled, t }: { settings: SitesSettings; disabled: boolean; t: Translate }) {
  return <>
    {settings.rootList.length === 0
      ? <p className="field-hint">{t("No extra folders.")}</p>
      : <ul className="sites-settings-roots">
        {settings.rootList.map((root, index) => (
          // Index keys: rows are plain strings that may repeat or be blank while being typed.
          <li key={index} className="sites-settings-root">
            <input className="field-mono" value={root} title={root} spellCheck={false} autoComplete="off" disabled={disabled}
              autoFocus={index === settings.addedIndex}
              aria-label={interpolate({ template: t("Extra folder {number}"), vars: { number: index + 1 } })}
              onChange={(event) => settings.setRootAt(index, event.target.value)} />
            <button type="button" className="btn-ghost sites-settings-root-remove" disabled={disabled}
              aria-label={interpolate({ template: t("Remove folder {number}"), vars: { number: index + 1 } })}
              onClick={() => settings.removeRoot(index)}><CloseIcon /></button>
          </li>
        ))}
      </ul>}
    <button type="button" className="btn-secondary sites-settings-add" disabled={disabled} onClick={settings.addRoot}>
      <span aria-hidden="true">+</span>{t("Add folder")}
    </button>
  </>;
}

function GearIcon() {
  return (
